// ---------- role-name translations (the profession menu; a cache apart from the skills') ------
// A role template (a Claude Code subagent, a Codex agent) has an English name. The user can have the names put into
// Chinese, once, on their own account; the result is a machine translation kept in its own file. Only a fresh
// translation is shown (one whose source changed is not), always with the English beside it.
// problem: why a translation could not start, as the server said it ({ code, message }), until the next try; hintOff: the
// person turned the prompt down in the profession picker (kept in the browser)
const RT = { entries: {}, counts: {}, job: null, engine: "claude", error: null, loaded: false, problem: null,
  hintOff: store.get("cw.rolehint", false) === true, listeners: new Set() };
const ROLE_WHAT_MISSING = "原文未提供";   // what the translator writes when the author wrote no description
function notifyRoleTranslations() { for (const listener of [...RT.listeners]) listener(); }
function roleZhName(id) {
  if (typeof id !== "string" || !Object.prototype.hasOwnProperty.call(RT.entries, id)) return "";
  const t = RT.entries[id];
  return t && t.state === "fresh" && t.entry && typeof t.entry.name_zh === "string" ? t.entry.name_zh.trim() : "";
}
// 中文名稱（English name); the name alone when there is no fresh translation.
function roleLabel(id, name) {
  const en = typeof name === "string" ? name : "";
  const zh = roleZhName(id);
  return !zh ? en : en ? `${zh}（${en}）` : zh;
}
// The one Chinese sentence of a fresh translation ("" when none, or when the author wrote nothing to translate).
function roleWhat(id) {
  if (typeof id !== "string" || !Object.prototype.hasOwnProperty.call(RT.entries, id)) return "";
  const t = RT.entries[id];
  const what = t && t.state === "fresh" && t.entry && typeof t.entry.what === "string" ? t.entry.what.trim() : "";
  return what === ROLE_WHAT_MISSING ? "" : what;
}
// A name is waiting to be translated only when the state is known: an unread state is not guessed at.
function roleIsPending(id) { return RT.loaded && !RT.error && !roleZhName(id); }
function roleUntranslated() { return (RT.counts.none || 0) + (RT.counts.stale || 0); }
function roleJobRunning() { return !!(RT.job && (RT.job.status === "running" || RT.job.status === "cancelling")); }
async function refreshRoleTranslations() {
  try {
    const data = await api.get("/api/role-translations");
    if (!data || !data.entries || typeof data.entries !== "object") throw new Error("職業翻譯狀態未知");
    Object.assign(RT, { entries: data.entries, counts: data.counts || {}, job: data.job || null,
      engine: data.engine || "claude", loaded: true, error: null });
  } catch (e) { RT.error = e.message || "職業翻譯狀態未知"; }
  notifyRoleTranslations();
}
function ensureRoleTranslations() { return RT.loaded ? Promise.resolve() : refreshRoleTranslations(); }
// The timer's turn: read again only before the first read and while a role job runs.
function pollRoleTranslations() { return !RT.loaded || roleJobRunning() ? refreshRoleTranslations() : Promise.resolve(); }
function roleTranslationSummary(count, engine = RT.engine) {
  const what = count === 1 ? "這個職業名稱" : `這 ${count} 個職業名稱`;
  return (engine === "claude"
    ? `會用你自己的 Claude 帳號翻譯${what}，${count === 1 ? "" : "每個"}通常不到 1 美分。`
    : `會用你自己的 Codex 帳號翻譯${what}，費用上限未知。`) + "送出的只有職業名稱和作者自己寫的說明，不送路徑、模型或其他欄位。";
}
function roleTranslationDisclosure(count, engine = RT.engine) {
  const budget = engine === "claude"
    ? `Claude 請求預算每項 US$0.05，${count} 項合計 US$${(count * 0.05).toFixed(2)}；CLI 在回合結束檢查，這不是保證帳單上限。`
    : "Codex 費用上限未知。";
  return `將 ${count} 個職業（角色範本）的名稱，以及作者自己寫的說明（沒有就不送），送到本機已登入的 ${engine} CLI，可能消耗該帳號的額度或產生費用。${budget} Token 消耗未知。` +
    "送出前會先遮蔽疑似金鑰；不送檔案路徑、模型、能力、適用任務或限制。中文名稱是機器翻譯，存在這台電腦的 role-translations.json，" +
    "不會改動角色範本本身，也不會載入或執行它。每項最多 60 秒；可以隨時取消。";
}
async function startRoleTranslation() {
  const count = roleUntranslated();
  if (!count || RT.error || roleJobRunning()) return;
  if (!(await confirmInPage("確認送出職業名稱", roleTranslationSummary(count), "翻成中文", { details: roleTranslationDisclosure(count) }))) return;
  RT.problem = null;
  try { await api.post("/api/role-translations/batch", { which: "stale+none" }); await refreshRoleTranslations(); }
  catch (e) {
    // these two are said where the person is looking, with what to do; any other reason is a toast
    if (e.code === "boundary_unverified" || e.code === "cli_not_found") { RT.problem = { code: e.code, message: e.message }; notifyRoleTranslations(); }
    else toast("無法翻譯：" + e.message);
  }
}
async function cancelRoleTranslation() {
  try { await api.post("/api/role-translations/batch/cancel", {}); await refreshRoleTranslations(); }
  catch (e) { toast(e.message); }
}
// The prompt at the top of the open profession picker: what is not in Chinese yet and the way to translate it. Only
// what is true is offered: the button when something is left and the state is known, the safety check when the first
// translation needs it, a note when the engine is Codex.
function roleTranslateRow() {
  const kids = [];
  if (RT.error) return [el("p", { class: "small muted", "data-cw": "role-translate-error" }, "職業名稱的翻譯狀態讀不到，先顯示英文。")];
  if (roleJobRunning()) {
    const j = RT.job;
    return [el("p", { class: "small", role: "status", "data-cw": "role-translate-status" }, `職業名稱翻譯中（${j.done || 0} / ${j.total || 0}）`),
      el("button", { class: "btn small", type: "button", "data-cw": "role-translate-cancel", on: { click: cancelRoleTranslation } }, "取消翻譯")];
  }
  if (RT.job && RT.job.status === "failed" && RT.job.error)
    kids.push(el("p", { class: "small cw-error", role: "status", "data-cw": "role-translate-failed" }, "上次職業名稱翻譯沒有完成：" + String(RT.job.error.message || "原因不明")));
  const n = roleUntranslated();
  if (!n) return kids;
  if (RT.hintOff) {
    kids.push(el("button", { class: "btn small", type: "button", "data-cw": "role-translate-show",
      on: { click: () => { RT.hintOff = false; store.set("cw.rolehint", false); notifyRoleTranslations(); } } }, "把職業名稱翻成中文…"));
    return kids;
  }
  kids.push(el("p", { class: "small", "data-cw": "role-translate-text" }, `還有 ${n} 個職業是英文。`));
  if (RT.engine !== "claude") {
    kids.push(el("p", { class: "small muted", "data-cw": "role-translate-note" }, "Codex 翻譯還沒開放，可以到設定改用 Claude Code。"));
  } else if (RT.problem && RT.problem.code === "boundary_unverified") {
    kids.push(el("p", { class: "small", "data-cw": "role-translate-note" }, "第一次翻譯前要先做一次安全檢查（會用你自己的 Claude 帳號，通常不到 1 美分）。"),
      el("button", { class: "btn small", type: "button", "data-cw": "role-translate-check", on: { click: verifyTranslationBoundary } }, "先檢查"));
  } else {
    if (RT.problem) kids.push(el("p", { class: "small cw-error", role: "status", "data-cw": "role-translate-note" }, String(RT.problem.message || "")));
    kids.push(el("button", { class: "btn small", type: "button", "data-cw": "role-translate", on: { click: startRoleTranslation } },
      `把職業名稱翻成中文（${n} 個未翻）`));
  }
  kids.push(el("button", { class: "btn small", type: "button", "data-cw": "role-translate-later",
    on: { click: () => { RT.hintOff = true; store.set("cw.rolehint", true); notifyRoleTranslations(); } } }, "先不翻"));
  return kids;
}

// ---------- data -----------------------------------------------------------

const D = { overview: null, skills: null, categories: [], roles: null, live: null, config: null, meetings: null, staffing: null, byId: new Map() };

async function loadStatic(force) {
  if (force || !D.overview) D.overview = await api.get("/api/overview");
  if (force || !D.skills) {
    const r = await api.get("/api/skills");
    D.skills = r.skills; D.categories = r.categories || [];
    D.byId = new Map(D.skills.map((s) => [s.skill_id, s]));
  }
  if (force || !D.roles) D.roles = (await api.get("/api/roles")).roles;
  renderScanStatus();
}
async function loadFlows() {
  try { D.flows = await api.get("/api/flows"); }
  catch (e) { D.flows = { error: e.message, flows: [] }; }
  return D.flows;
}

async function loadLive(force, timeoutMs) {
  try { D.live = await api.get("/api/live" + (force ? "?force=1" : ""), { timeoutMs }); }
  catch (e) { D.live = { error: e.message, sessions: [], projects: [], attention: [], usage: { sessions: [] }, runtime: { available: false, problems: [e.message] } }; }
  return D.live;
}

function renderScanStatus() {
  const box = document.getElementById("scan-status");
  if (!box || !D.overview) return;
  setKids(box, 
    el("div", { class: D.overview.stale ? "stale" : null }, `索引更新於 ${ago(D.overview.generated_at)}`, D.overview.stale ? "（已過期）" : ""),
    el("div", null, `${D.overview.totals.active} 個可使用技能`),
    el("button", { class: "btn small", on: { click: rescan } }, "重新掃描"),
  );
}

async function rescan(ev) {
  const btn = ev && ev.currentTarget;
  if (btn) btn.disabled = true;
  try {
    const r = await api.post("/api/rescan");
    await loadStatic(true);
    await loadLive(true);
    toast(`掃描完成（${r.scan_seconds} 秒）`);
    route();
  } catch (e) { toast("掃描失敗：" + e.message); }
  finally { if (btn) btn.disabled = false; }
}

// ---------- search ---------------------------------------------------------

function norm(s) { return String(s || "").toLowerCase(); }
function ann(s) { return s.annotation || {}; }
function displayName(s) { return (ann(s).aliases || [])[0] || s.name; }

function searchSkills(query, pool) {
  const q = norm(query).trim();
  if (!q) return pool.map((s) => ({ s, score: 0, why: [] }));
  const terms = q.split(/[\s,，、]+/).filter(Boolean);
  const catHits = new Set();
  for (const cat of D.categories) {
    if (norm(cat.label).includes(q) || cat.query.some((w) => q.includes(norm(w)) || terms.includes(norm(w)))) catHits.add(cat.id);
  }
  // A category hit counts more when the category is small: "資安" (a few
  // skills) says more about intent than "網站" (many).
  const catSize = new Map();
  for (const s of D.skills) if (s.activation === "active") for (const c of s.categories || []) catSize.set(c.id, (catSize.get(c.id) || 0) + 1);
  const activeTotal = D.skills.filter((s) => s.activation === "active").length || 1;
  const catWeight = (id) => Math.round(20 * (1 + Math.log(activeTotal / Math.max(1, catSize.get(id) || 1))));
  const out = [];
  for (const s of pool) {
    const name = norm(s.name), inv = norm(s.invoke_name);
    const desc = norm(s.description && s.description.value);
    const when = norm(s.when_to_use && s.when_to_use.value);
    const translated = translationOf(s.skill_id);
    const translationText = norm(translated.entry ? [translated.entry.description_zh, ...Object.values(translated.entry.summary)].join(" ") : "");
    let score = 0; const why = [];
    const a = ann(s);
    const aliases = (a.aliases || []).map(norm), tags = (a.tags || []).map(norm), note = norm(a.note);
    if (aliases.some((x) => x === q)) { score += 120; why.push("我的別名"); }
    if (tags.some((x) => x === q)) { score += 60; why.push("我的標籤"); }
    for (const t of terms) {
      if (aliases.some((x) => x.includes(t))) { score += 45; why.push("我的別名"); }
      if (tags.some((x) => x.includes(t))) { score += 30; why.push("我的標籤"); }
      if (note.includes(t)) { score += 10; why.push("我的備註"); }
      if (name === t || inv === t) { score += 100; why.push("名稱相符"); }
      else if (name.includes(t) || inv.includes(t)) { score += 40; why.push("名稱包含"); }
      if (desc.includes(t)) { score += 18; why.push("用途描述"); }
      if (when.includes(t)) { score += 8; why.push("使用時機"); }
      if (translationText.includes(t)) { score += 16; why.push(translated.state === "stale" ? "過期機器翻譯" : "機器翻譯"); }
    }
    for (const c of s.categories || []) if (catHits.has(c.id)) { score += catWeight(c.id); why.push(`用途：${categoryZh(c.label)}`); }
    if (score > 0) out.push({ s, score: score + (s.activation === "active" ? 5 : 0), why: [...new Set(why)] });
  }
  return out.sort((a, b) => b.score - a.score || a.s.name.localeCompare(b.s.name));
}

// ---------- components -----------------------------------------------------

function skillCard(s, why) {
  const dups = (s.duplicate_of || []).length;
  // a chip card: the corner cut and the band across the top are in the colours of the tool the skill belongs to (the tag says it too)
  return withSkillTip(el("a", { class: "card skill-chip camp-frame", "data-camp": campKeyOf(s), href: `#/skills/${s.skill_id}` },
    el("div", { class: "card-top" },
      el("div", { style: "min-width:0" },
        el("div", { class: "card-title" }, displayName(s)),
        el("div", { class: "card-sub mono" }, displayName(s) !== s.name ? `原名 ${s.invoke_name}` : s.invoke_name !== s.name ? `呼叫名稱 ${s.invoke_name}` : SCOPE[s.scope] || s.scope)),
      activationWithHelp(s.activation)),
    translationBadge(s.skill_id),
    translationDescription(s)
      ? el("p", { class: "clamp" }, firstSentence(translationDescription(s), 170))
      : el("p", { class: "muted" }, "作者沒有提供用途描述"),
    (ann(s).tags || []).length ? el("div", { class: "chips" }, ann(s).tags.map((t) => el("span", { class: "tag mine", title: "我的標籤" }, "#" + t))) : null,
    el("div", { class: "chips" },
      toolTag(s.tool),
      el("span", { class: "tag" }, SCOPE[s.scope] || s.scope),
      (s.categories || []).slice(0, 2).map((c) => el("span", { class: "tag cat", title: `自動分類：描述中出現「${c.keyword}」` }, categoryZh(c.label))),
      dups ? badge(`同名 ${dups + 1} 份`, "b-warn", "有其他來源使用相同名稱，詳情頁可比較") : null,
      (s.missing_files || []).length ? badge("引用檔缺失", "b-bad", s.missing_files.join(", ")) : null),
    why && why.length ? el("div", { class: "card-sub" }, "符合：" + why.join("、")) : null), s);
}

function sessionCard(x) {
  const models = modelList(x.models_observed);
  const used = (x.skills_used || []).slice(0, 4);
  const project = (D.live.projects || []).find((p) => p.project_id === x.project_id);
  return el("div", { class: "card" },
    el("div", { class: "card-top" },
      el("div", { class: "who" },
        el("div", { class: "avatar", "aria-hidden": "true" }, initialOf(x.role_label || x.agent)),
        el("div", null,
          el("div", { class: "card-title" }, x.role_label || `${TOOL[x.agent] || x.agent} 工作階段`),
          el("div", { class: "card-sub" }, x.role_label_source ? "角色名稱來自分頁名稱" : "未命名"))),
      statusBadge(x.status, x.activity)),
    x.title ? el("p", { class: "clamp" }, x.title) : null,
    el("dl", { class: "kv small" },
      el("dt", null, "執行工具"), el("dd", null, TOOL[x.agent] || x.agent || "未知"),
      el("dt", null, "狀態依據"), el("dd", { class: "small" }, activityBasis(x.activity)),
      el("dt", null, "本次模型"), el("dd", null,
        models.length ? [models.join("、"), " ", prov({ origin: "runtime", detail: "對話紀錄" })]
          : el("span", { class: "muted" }, x.supported_tool ? (x.usage_matched ? "紀錄中沒有模型資訊" : "找不到對應的對話紀錄") : "此工具不提供可讀紀錄")),
      el("dt", null, "專案"), el("dd", null, project ? el("a", { href: `#/projects/${project.project_id}` }, project.name) : "—"),
      el("dt", null, "本次用過的技能"), el("dd", null,
        used.length ? el("div", { class: "chips" }, used.map((u) => usedChip(u)))
          : el("span", { class: "muted" }, x.usage_matched ? "紀錄中沒有技能使用" : "無紀錄可查"))),
    el("div", { class: "row" },
      el("span", { class: "small muted mono" }, `${x.workspace_label || x.workspace_id} · ${x.pane_id}`),
      el("span", { class: "spacer" }),
      el("a", { class: "btn small primary", href: `#/term/${encodeURIComponent(x.pane_id)}`, title: "開啟終端機串流（預設僅觀看）" }, "開啟終端")));
}

function usedChip(u) {
  const [label, cls, explain] = EVIDENCE[u.evidence] || ["使用紀錄", "b-mute", ""];
  const target = u.skill_ids && u.skill_ids[0];
  const text = `${u.label}${u.count > 1 ? ` ×${u.count}` : ""}`;
  const title = `${label}：${explain}${u.resolution === "ambiguous" ? "（對應到多份同名技能）" : ""}${u.resolution === "unresolved" ? "（索引中找不到對應的技能檔）" : ""}`;
  return target
    ? el("a", { class: `badge ${cls}`, href: `#/skills/${target}`, title }, text)
    : el("span", { class: `badge ${cls}`, title }, text);
}

// Native runtime sessions (pane ids "n-" + 12 hex) can be closed from the
// console. Closing a Profile-managed session also removes its scratch and
// settings once every one of its processes is proven gone; otherwise they are
// kept for review, and the toast says so.
const NATIVE_SESSION_RE = /^n-[0-9a-f]{12}$/;

// In-page confirmation (not window.confirm): a native browser dialog blocks
// the page and cannot be driven by browser automation, which left the close
// button unverifiable in acceptance. Resolves true only on the confirm button.
// opts.details: the long print, kept whole behind a 「詳細」 fold under the short sentence.
function confirmInPage(title, message, confirmLabel, opts = {}) {
  return new Promise((resolve) => {
    const titleId = "modal-confirm-title";
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      closeModal();
      resolve(value);
    };
    const confirmBtn = el("button", { class: "btn primary", type: "button", on: { click: () => finish(true) } }, confirmLabel);
    const cancelBtn = el("button", { class: "btn", type: "button", on: { click: () => finish(false) } }, "取消");
    const modalElem = el("div", { class: "modal-backdrop", role: "dialog", "aria-modal": "true", "aria-labelledby": titleId },
      el("div", { class: "modal-box" },
        el("h2", { id: titleId }, title),
        el("p", null, message),
        opts && typeof opts.details === "string" && opts.details
          ? el("details", { class: "confirm-details", "data-confirm": "details" }, el("summary", null, "詳細"), el("p", { class: "small" }, opts.details)) : null,
        el("div", { class: "modal-actions" }, cancelBtn, confirmBtn)));
    document.body.append(modalElem);
    // Escape or a view teardown closes the dialog through this teardown: that is a "no".
    const closeModal = withModalA11y(modalElem, () => {
      modalElem.remove();
      if (!settled) { settled = true; resolve(false); }
    });
    cancelBtn.focus();
  });
}
// ---- Skill card (design game-ui 4.2) -----------------------------------------------------------------------
// One dialog for the workbench's role card and the Armory. Its data is GET /api/skills/<id>?view=card, which
// answers from what is already loaded. Every string is set as text; a field that was not provided says so.
function skillObservationText(o) {
  const period = o && typeof o.window_days === "number" ? `最近 ${o.window_days} 天` : "觀察期間：未知";
  if (o && o.state === "observed") return `觀察期間內有紀錄（${period}；來源：執行觀察）`;
  if (o && o.state === "none") return `目前沒有觀察紀錄（${period}；來源：執行觀察）。這不代表沒有用過。`;
  return `觀察資料不可用（${period}；來源：執行觀察）`;
}

// What to say about a skill's installed state: only a not_installed copy is "not installed"; any other state
// that is not an installed one (unknown, archived, not loaded...) is named with its reason, not inferred.
function skillStatusText(sk) {
  const act = sk && sk.activation;
  const label = (ACT[act] || [])[0] || act || "未提供";
  const reason = sk && sk.activation_reason ? "：" + sk.activation_reason : "";
  if (sk && sk.installed) return `已安裝（${label}）${reason}`;
  if (act === "not_installed") return `沒有安裝在這台 Mac（市集上的副本）${reason}`;
  return `${label}${reason}`;
}

// The five armor groups and the level words each holds (agent_launch.ARMOR_GROUPS / ARMOR_GROUP_LEVELS; a test
// compares this table with the server's). Only a frame: the level words and notes are always shown as they are.
const ARMOR_GROUPS_UI = [
  { id: "blocked", label: "擋住了", levels: ["強制（限已測路徑、版本與執行層）"] },
  { id: "partial", label: "部分擋住", levels: ["部分強制"] },
  { id: "not_granted", label: "沒有專用權限", levels: ["不授予"] },
  { id: "not_blocked", label: "沒有擋", levels: ["僅意圖", "未限制"] },
  { id: "unproven", label: "未證明", levels: ["未驗證（此 Claude Code 版本尚未實測）", "未知"] },
];
// A level this table does not know is put in the last group (not proven), never in a protective one.
function armorGroupOf(level) {
  const g = ARMOR_GROUPS_UI.find((x) => x.levels.includes(level));
  return g ? g.id : "unproven";
}

function skillCardField(label, src, extra) {
  const v = src && src.value;
  const has = !(v === null || v === undefined || v === "" || (Array.isArray(v) && !v.length));
  return el("div", { class: "sc-field" },
    el("div", { class: "sc-label" }, label),
    el("div", { class: "sc-value" }, has ? (Array.isArray(v) ? v.map(String).join("、") : String(v)) : null,
      has ? " " : null, prov(src)),
    extra || null);
}

// opts: { profile } when it is opened from a role card (adds 「從這個角色移除」), { onChanged } after a change.
async function openSkillCard(skillId, opts = {}) {
  const titleId = "modal-skill-card-title";
  const body = el("div", { class: "sc-body" }, el("p", { class: "loading" }, "載入技能卡…"));
  const actions = el("div", { class: "modal-actions" });
  const modalElem = el("div", { class: "modal-backdrop", role: "dialog", "aria-modal": "true", "aria-labelledby": titleId },
    el("div", { class: "modal-box sc-box" },
      el("h2", { id: titleId }, "技能卡"), body, actions));
  document.body.append(modalElem);
  let open = true;
  const closeModal = withModalA11y(modalElem, () => { open = false; modalElem.remove(); });
  const backBtn = el("button", { class: "btn", type: "button", on: { click: () => closeModal() } }, "返回");
  setKids(actions, backBtn);
  backBtn.focus();
  let d;
  let failure = null;
  try {
    await refreshTranslations();
    d = await api.get(`/api/skills/${encodeURIComponent(skillId)}?view=card`);
  } catch (e) {
    failure = e;
  }
  // closed while it was loading: nothing is drawn into the window that is gone, and the focus is where closing put it
  if (!open) return;
  // the buttons below are built again, which takes the focus off 返回; it goes back there unless the person moved it
  const restoreFocus = keepDialogFocus(modalElem);
  if (failure) {
    setKids(body, notice("bad", "無法顯示技能卡：" + (failure && failure.message ? failure.message : "未知錯誤")));
    restoreFocus(backBtn);
    return;
  }
  const sk = d.skill || {};
  const refs = sk.referenced_files || {};
  const roles = (d.added_to_roles && d.added_to_roles.items) || [];
  const scopeSrc = sk.scope ? { ...sk.scope, value: SCOPE[sk.scope.value] || sk.scope.value } : null;
  // the other tools whose own files say they read this skill (today AGY), worded as the camps are
  const readBy = sk.read_by && Array.isArray(sk.read_by.value) ? sk.read_by.value.filter((t) => typeof t === "string").map((t) => TOOL[t] || t) : [];
  const nameValue = sk.name && typeof sk.name === "object" ? sk.name.value : sk.name;
  const nameText = nameValue ? String(nameValue) : `未提供（ID：${skillId}）`;
  const nameSrc = sk.name && typeof sk.name === "object" ? sk.name : { origin: "missing", detail: "" };
  const listOf = (x) => (x && Array.isArray(x.items) ? x.items : Array.isArray(x) ? x : []);
  const missingFiles = listOf(sk.missing_files);
  const warnings = listOf(sk.warnings);
  const fixed = d.effect_note || "效果是作者的描述，不是 VBear 驗證過的能力，只適用於你自己啟動並載入這張技能的工具";
  setKids(body,
    el("div", { class: "sc-head" },
      el("strong", { class: "sc-name" }, nameText),
      prov(nameSrc),
      badge(SKILL_NOT_LOADED, "b-mute", SKILL_NOT_LOADED_TIP)),
    notice("info", fixed),
    skillCardField("類別", sk.categories && Array.isArray(sk.categories.value) ? { ...sk.categories, value: sk.categories.value.map(categoryZh) } : sk.categories),
    skillCardField("陣營", sk.tool),
    readBy.length ? skillCardField("也會讀它的工具", { ...sk.read_by, value: readBy }) : null,
    skillCardField("來源（位置）", scopeSrc),
    translationPanel(skillId, el("div", null,
    skillCardField("效果（技能作者的說明）", sk.description),
    skillCardField("發動時機", sk.when_to_use),
    skillCardField("需要（輸入）", sk.inputs),
    skillCardField("產出", sk.outputs),
    skillCardField("依賴", sk.dependencies))),
    el("div", { class: "sc-field" },
      el("div", { class: "sc-label" }, "引用的檔案"),
      el("div", { class: "sc-value" },
        `共 ${refs.count ?? "未提供"} 個；${refs.note || "VBear 不會執行這些檔案"} `, prov(refs),
        (refs.items || []).length ? el("ul", { class: "sc-refs" }, refs.items.map((r) =>
          el("li", null, el("span", { class: "mono" }, String(r.ref)), " ",
            el("span", { class: "muted" }, r.status === "present" ? "存在" : r.status === "missing" ? "缺少" : "非套件檔案"))))
          : null,
        refs.truncated ? el("p", { class: "rc-note" }, "清單過長，只列出前面的部分。") : null)),
    missingFiles.length ? notice("warn", ["缺少的檔案：" + missingFiles.join("、") + " ", prov(sk.missing_files)]) : null,
    warnings.length ? notice("warn", ["結構檢查：" + warnings.join("；") + " ", prov(sk.warnings)]) : null,
    el("div", { class: "sc-field" },
      el("div", { class: "sc-label" }, "這張卡的狀態"),
      el("ul", { class: "sc-status" },
        el("li", null, skillStatusText(sk) + " ", prov(sk.status_source)),
        el("li", null, ((d.added_to_roles && d.added_to_roles.unavailable)
          ? `收藏在哪些角色卡上：無法讀取（${d.added_to_roles.unavailable}）`
          : roles.length ? `收藏在 ${roles.length} 張角色卡上：${roles.map((r) => r.name || r.id).join("、")}（${SKILL_NOT_LOADED}）`
          : "沒有角色卡收藏這張技能") + " ", prov(d.added_to_roles)),
        el("li", null, "觀察狀態：" + skillObservationText(d.observation) + " ", prov(d.observation)),
        el("li", null, ((d.marketplace_copies || []).length
          ? `市集有其他副本（${d.marketplace_copies.length} 個，尚未安裝）` : "市集沒有找到其他副本") + " ",
          prov(d.marketplace_source)))));
  const kids = [];
  const profile = opts.profile;
  if (profile && (profile.equipped_skill_ids || []).includes(skillId)) {
    kids.push(el("button", { class: "btn", type: "button", on: { click: async () => {
      if (!(await confirmInPage("從這個角色移除",
        `把「${nameText}」從角色「${profile.name || profile.id}」的已選技能移除？這只會改你的挑選紀錄，不會刪除技能。`,
        "移除"))) return;
      try {
        const next = (profile.equipped_skill_ids || []).filter((x) => x !== skillId);
        await api.post(`/api/agent-profiles/${encodeURIComponent(profile.id)}`, { equipped_skill_ids: next });
        toast("已從角色移除");
        closeModal();
        if (typeof opts.onChanged === "function") await opts.onChanged();
        focusMainIfLost();   // the card behind was drawn again, and the button that opened this window went with it
      } catch (err) {
        toast("移除失敗：" + err.message);
      }
    } } }, "從這個角色移除"));
  }
  kids.push(el("a", { class: "btn", href: `#/skills/${encodeURIComponent(skillId)}`,
    on: { click: () => closeModal() } }, "打開技能檔案"));
  kids.push(backBtn);
  setKids(actions, ...kids);
  restoreFocus(backBtn);
}

// Plain-language names for the terminal-title checks of 「驗證這個版本」.
const TITLE_CHECK_TEXT = {
  idle_before_prompt: "送出提示前沒有出現閒置符號 ✳",
  working_after_prompt: "送出後沒有出現工作中的 ◐／◑",
  idle_after_turn: "回合結束後沒有回到 ✳",
  spinner_cadence: "工作中的標題更新間隔超過 5 秒",
  title_check_missing: "報告裡沒有標題檢查",
  not_checked: "那次沒有檢查標題",
};
function titleFailureText(names) {
  const list = Array.isArray(names) ? names : [];
  return list.map((n) => TITLE_CHECK_TEXT[n] || `其他（${n}）`).join("、") || "原因未知";
}

function closeSessionButton(paneId, afterHash = "#/team") {
  if (!NATIVE_SESSION_RE.test(paneId || "")) return null;
  const btn = el("button", { class: "btn small", type: "button",
    title: "結束這個終端裡的程式並關閉它",
    on: { click: async () => {
      if (!(await confirmInPage("關閉終端", "確定要關閉這個終端？裡面正在執行的程式會被結束。", "關閉終端"))) return;
      btn.disabled = true;
      try {
        const r = await api.post(`/api/native/sessions/${encodeURIComponent(paneId)}/close`, {});
        const m = r.managed;
        toast(!m ? "終端已關閉"
          : m.cleaned ? "終端已關閉，暫存區與設定已清除"
          : `終端已關閉；暫存區保留待檢查。${terminalFailureLine(m.retained_reason || "", m.retained_reason ? "沒能確認原因。" : "原因未知。")}`);
        if (location.hash === afterHash) route();  // no hashchange: re-render in place
        else if (!location.hash.startsWith("#/workbench")) location.hash = afterHash;
      } catch (e) {
        if (e.status === 404) {
          toast("這個終端已不存在或已結束");
          if (!location.hash.startsWith("#/workbench")) location.hash = afterHash;
          return;
        }
        toast(terminalFailureLine(e, TERM_GENERAL.close));
        btn.disabled = false;
      }
    } } }, "關閉終端");
  return btn;
}

function roleCard(r) {
  const skills = r.skills || [];
  return el("a", { class: "card", href: `#/team/role/${r.role_id}` },
    el("div", { class: "card-top" },
      el("div", { class: "who" },
        el("div", { class: "avatar", "aria-hidden": "true" }, r.emoji || initialOf(r.name)),
        el("div", null,
          el("div", { class: "card-title" }, roleLabel(r.role_id, r.name)),
          el("div", { class: "card-sub" }, r.kind === "cli" ? "主代理（直接執行的工具）" : "子代理／角色設定"))),
      toolTag(r.tool)),
    r.description && r.description.value ? el("p", { class: "clamp" }, firstSentence(r.description.value, 160)) : el("p", { class: "muted" }, "沒有描述"),
    el("div", { class: "stat-line" },
      el("span", null, "預設模型 ", el("b", null, (r.model && r.model.value) || "未指定"),
        r.model && r.model.origin === "derived" ? el("span", { class: "muted", title: r.model.detail }, "（沿用全域預設）") : null),
      el("span", null, "可用技能 ", el("b", null, r.kind === "cli" || r.skill_link_basis === "declared" ? skills.length : "未宣告"))),
    (r.warnings || []).length ? el("div", { class: "chips" }, badge(r.warnings[0], "b-warn")) : null);
}

function emptyState(title, detail) {
  return el("div", { class: "empty-state" }, el("strong", null, title), detail ? el("span", null, detail) : null);
}
// A message in a box. A text that is a string goes through plainWords (P47-1): a sentence the table knows is said in plain words with the
// original behind 「技術細節」; any other text is shown as it is. A text that is nodes (or a list) is the caller's own words.
function notice(kind, text) {
  return typeof text === "string" ? plainNotice(kind, text) : noticeBox(kind, text);
}
function noticeBox(kind, text) {
  const ico = { warn: "!", info: "i", bad: "×" }[kind] || "i";
  return el("div", { class: `notice ${kind}`, role: kind === "bad" ? "alert" : "note" }, el("span", { class: "ico", "aria-hidden": "true" }, ico), el("div", null, text));
}
// What the server and the runtime say when a terminal, a takeover, a close, a handoff or a link to a task card does not work
// (P19). One table of the sentences they really send: each is said in plain words with what to do next, and the original is kept,
// whole, for the person to open (a fold 「技術細節」 in a notice, in brackets in a toast). A sentence the table does not know gets
// only the general sentence of the place, never a guess at the cause. The server's and the runtime's own text and codes are not changed
// (a test finds each sentence below in their code). raw: a string matched by the regex (or by `test`); text: the plain words;
// next: what can be done; gone: the answer was "no such session", so there is nothing left to reconnect to.
const TERMINAL_WORDS = [
  { re: /沒有這個 session|沒有這個 Terminal/, text: "這個終端已經不存在了（可能已關閉）。", next: "要繼續的話，請重新開啟一個終端。", gone: true },
  { re: /連線上限|同時開啟的 Terminal 過多/, text: "這個終端的連線數已滿，暫時連不上；關閉其他正在看它的分頁後可以再試。" },
  { re: /目前不是這個 Terminal 的操作者/, text: "你現在不是這個終端的操作者，所以輸入沒有送出（可能其他分頁接手了，或已經改成只觀看）。", next: "要打字請先按「接管操作」。" },
  { re: /缺少輸入內容/, text: "沒有內容可以送出。" },
  { re: /單次輸入過長/, text: "一次輸入的內容太長，沒有送出。", next: "請分成幾段再貼。" },
  { re: /背景程序正在關閉，不接受新的 session/, text: "VBear 的背景程序正在關閉，現在不能開新的終端。", next: "請稍後再試。" },
  { re: /VBear runtime|無法連線到 runtime/, text: "VBear 的背景程序現在連不上，終端暫時操作不了。", next: "請稍後再試；一直這樣的話，請重新開啟 VBear。" },
  { re: /無效的 session id/, text: "這個終端的編號對不上，沒有處理。", next: "請重新整理頁面，再從列表打開它。" },
  { re: /需要從 VBear 開啟/, text: "這個分頁沒有 VBear 的通行證，VBear 不接受它的要求。", next: "請從 VBear 重新開啟一個分頁。" },
  { re: /^(forbidden|invalid host)$/, text: "VBear 擋下了這個要求，因為它不是從 VBear 自己的頁面送出的。", next: "請從 VBear 重新開啟頁面再試。" },
  { re: /^內部錯誤：/, text: "VBear 這邊出了內部錯誤，這次沒有完成。", next: "請稍後再試一次。" },
  { test: (raw, x) => (x && x.name === "TypeError") || /^(failed to fetch|load failed|networkerror|網路錯誤)/i.test(raw),
    text: "連不上 VBear（它可能已經關掉，或網路中斷了）。", next: "請確認 VBear 還開著，再試一次。" },
  { re: /^HTTP \d{3}$/, text: "VBear 回了一個沒有說明的錯誤，這次沒有完成。", next: "請稍後再試一次。" },
  { re: /找不到此任務卡/, text: "找不到這張任務卡（可能已經被刪除）。", next: "請回到任務卡清單重新整理，再看一次。" },
  { re: /交接必須填寫接手的對象/, text: "交接要寫明交給誰。", next: "請在「交給」欄填上接手的角色、Agent 或人。" },
  { re: /此任務卡已結案，不能再交接/, text: "這張任務卡已經結案，不能再交接。", next: "請從最新的一張接續。" },
  { re: /^任務卡已達上限/, text: "任務卡的數量已經到上限。", next: "請先刪掉用不到的卡，再試一次。" },
  { re: /任務儲存/, text: "VBear 的任務卡儲存區現在讀寫不了，這次沒有完成。", next: "它的說明在原文裡；處理好之後再試。" },
  // why the scratch of a closed managed terminal was kept (the runtime's reasons, agent_sessions.cleanup_launch and daemon._finish_managed)
  { re: /^leader 尚未結束/, text: "終端裡的主程式還沒結束。", next: "VBear 先保留著，沒有刪。" },
  { re: /process group 仍有程序/, text: "主程式那一組裡還有程式在跑。", next: "VBear 先保留著，沒有刪。" },
  { re: /^仍有已觀測的後代程序存活/, text: "它啟動的程式裡還有沒結束的。", next: "VBear 先保留著，沒有刪。" },
  { re: /^無法取得程序表或有無法確認身分的後代/, text: "查不到有哪些程式在跑，確認不了是不是都結束了。", next: "VBear 先保留著，沒有刪。" },
  { re: /^無法證明程序已全部結束/, text: "沒辦法證明裡面的程式都已經結束。", next: "VBear 先保留著，沒有刪。" },
  { re: /^leader 已被回收|^leader 已不是未回收|^leader 在回收前已失去/, text: "沒辦法確認主程式那一組是不是都結束了。", next: "VBear 先保留著，沒有刪。" },
  { re: /^launch 目錄身分與 manifest 不符|^暫存區位置與核准樣式不符|^暫存區 inode 與 manifest 不符/, text: "暫存區的記錄和實際內容對不上，為了安全沒有刪它。", next: "VBear 先保留著，沒有刪。" },
  { re: /刪除後仍存在/, text: "刪除之後暫存區還在，沒刪乾淨。", next: "VBear 先保留著，沒有刪。" },
  { re: /^清理檢查失敗|^manifest 無法讀取/, text: "清理前的檢查沒通過，所以沒有刪。", next: "VBear 先保留著，沒有刪。" },
  // the folder of a new built-in terminal (server._terminal_open)
  { re: /資料夾必須在你的家目錄內/, text: "這個資料夾不在你的家目錄裡。", next: "請換一個家目錄裡的資料夾。" },
  { re: /找不到這個資料夾/, text: "找不到這個資料夾。", next: "請確認路徑打對了、資料夾還在。" },
  { re: /資料夾必須是絕對路徑，或以 ~ 開頭/, text: "資料夾路徑要從 / 或 ~ 開頭。", next: "請改成完整的路徑。" },
];
// The general sentence of each place: what did not work, nothing about why.
const TERM_GENERAL = {
  takeover: "沒能接手這個終端。",
  autoTakeover: "沒能取得這個終端的輸入控制。",
  release: "沒能改成只觀看，仍維持可操作的狀態。",
  input: "鍵盤輸入沒有送出，沒送出的內容已經捨棄（不會自動重送）。",
  stream: "沒能連上這個終端的畫面。",
  close: "沒能關閉這個終端。",
  handoff: "沒能交接這張任務卡。",
  link: "沒能更新任務卡和終端的關聯。",
  open: "沒能開啟這個終端機。",
};
// x: the original (a string, or an Error or a server answer that carries it). -> { text, next, detail, gone, known }
function terminalWords(x, general) {
  const raw = typeof x === "string" ? x.trim()
    : x && typeof x.message === "string" ? x.message.trim()
    : x && typeof x.error === "string" ? x.error.trim() : "";
  const hit = raw || (x && x.name === "TypeError") ? TERMINAL_WORDS.find((w) => (w.re ? w.re.test(raw) : w.test(raw, x))) : null;
  if (hit) return { text: hit.text, next: hit.next || "", detail: raw, gone: Boolean(hit.gone), known: true };
  return { text: general, next: "", detail: raw, gone: false, known: false };
}
// For a toast, which holds one line of plain text: the plain words, then the original in brackets.
function terminalFailureLine(x, general) {
  const w = terminalWords(x, general);
  return `${w.text}${w.next}${w.detail ? `（原文：${w.detail}）` : ""}`;
}
// For a notice: the plain words, and the original behind 「技術細節」.
function terminalFailureNotice(x, general, kind = "bad") {
  const w = terminalWords(x, general);
  return notice(kind, [`${w.text}${w.next}`,
    w.detail ? el("details", { class: "small term-tech", "data-term": "tech" },
      el("summary", null, "技術細節"), el("code", { class: "term-tech-raw" }, w.detail)) : null]);
}
// The runtime's words for a terminal it could not attach to arrive as "terminal attach failed: <its message>" (P14). The ones
// known are said in plain words (the table above), with the original kept in a fold ("技術細節"); one that is not known gets only
// a general line. Any other reason (for example 終端機已結束) is shown as it is. The server's text and codes are not changed.
// gone: the answer was "no such session", so there is nothing left to reconnect to.
function terminalClosedView(reason) {
  const raw = typeof reason === "string" ? reason.trim() : "";
  const m = /^terminal attach failed:\s*([\s\S]*)$/.exec(raw);
  if (!m) return { text: raw, gone: false, detail: "" };
  const w = terminalWords(m[1], "沒能連上這個終端。");
  return { text: w.text, gone: w.gone, detail: raw };
}
// The line under the terminal when its stream has closed: the reason (plain words), what to do next, and the original.
function terminalClosedNotice(reason, sessionGone, goneAdvice) {
  const v = terminalClosedView(reason);
  const next = sessionGone ? goneAdvice : "如需重新開啟請點選右上方「重新連線」。";
  const said = v.text && !/[。！？.!?]$/.test(v.text) ? v.text + "。" : v.text;
  return notice("info", [`指令視窗連線已關閉${said ? "：" + said : ""}${next}`,
    v.detail ? el("details", { class: "small term-tech", "data-term": "tech" },
      el("summary", null, "技術細節"), el("code", { class: "term-tech-raw" }, v.detail)) : null]);
}
function staleNotice() {
  if (!D.overview || !D.overview.stale) return null;
  return el("div", { class: `notice warn`, role: "note" }, el("span", { class: "ico", "aria-hidden": "true" }, "!"),
    el("div", null, `技能索引已經 ${ago(D.overview.generated_at).replace("前", "")}沒有更新，新增、移除或升級的技能可能還沒反映。 `,
      el("button", { class: "btn small", on: { click: rescan } }, "立即重新掃描")));
}
function corruptNotice() {
  if (!D.overview || !D.overview.config_corrupt) return null;
  return notice("bad", "設定檔（config.json）無法讀取。你原本選的掃描範圍目前不明，所以 VBear 已關閉所有掃描來源，也不會重新掃描，畫面上是先前的索引。請修復或刪除 ~/.vbear/config.json 後重新啟動 VBear；原檔不會被覆寫。");
}
function runtimeNotice() {
  const h = D.live && D.live.runtime;
  if (!h) return null;
  if (!h.available) return notice("warn", ["無法連線到 VBear runtime，終端的資訊暫時看不到。", (h.problems || []).join("；")].join(" "));
  return null;
}
// One-time notice after a Herdr-era config was switched to native (until acknowledged).
function herdrMigrationNotice() {
  if (!D.overview || !D.overview.herdr_migration_notice) return null;
  const ack = el("button", { class: "btn small", type: "button", on: { click: async () => {
    ack.disabled = true;
    try {
      await api.post("/api/config", { herdr_migration_acknowledged: true });
      D.overview.herdr_migration_notice = false;
      wrap.remove();
    } catch (e) { toast("無法儲存：" + e.message); ack.disabled = false; }
  } } }, "知道了");
  const wrap = el("div", { class: "notice info" },
    el("span", { class: "ico", "aria-hidden": "true" }, "i"),
    el("div", null, "VBear 已改用內建的背景程式，不再支援 Herdr，設定已自動切換。在 Herdr 或其他終端自行啟動的 AI 工具不會出現在這裡；請從員工的「開始前的檢查」開啟。 ", ack));
  return wrap;
}
function sectionHead(title, sub, action) {
  return el("div", { class: "section-head" },
    el("div", null, el("h2", null, title), sub ? el("p", { class: "small muted" }, sub) : null), action || null);
}

// ---------- views ----------------------------------------------------------

// The home page (v0.21, P47-2, ADR 0013): what waits for the person to decide, their employees (a click on an avatar is a chat), what is on today,
// and one box to say what they want to the CEO. A person with no employee sees three steps instead. The page shows no amount of money and sends
// nothing by itself: the only write it can make is the person's own press of 送出 (and the buttons of a row of 「等你決定」, which are the
// routines page's own requests). The parts of the old lobby (the board, task cards, skill search, recent projects) are under 「進階」 and only in
// the advanced mode, which decides nothing but what is shown.
let homeTick = null;     // the refresh of the home page every 5 seconds (route() runs it); null on any other page
async function viewHome() {
  const token = seq;
  // /api/flows reads live state from the cache /api/live fills, so live goes first.
  const [, , tasksRes, profilesRes, catalogRes, configRes, chatsRes, routinesRes, waitingRes, ledgerRes] = await Promise.all([loadStatic(), loadLive().then(() => loadFlows()),
    api.get("/api/tasks").catch(() => null), api.get("/api/agent-profiles").catch(() => null),
    api.get("/api/agent-builder/catalog").catch(() => null), api.get("/api/config").catch(() => null),
    api.get("/api/chats").catch(() => null), api.get("/api/routines").catch(() => null), api.get("/api/waiting").catch(() => null),
    api.get("/api/meetings/ledger").catch(() => null), loadMeetings(), loadStaffingList(), loadDispatchList(), loadGroupList()]);
  const setup = setupGateWanted(configRes) ? await setupGate(configRes) : setupGateQuiet(configRes);
  if (token !== seq) return;
  if (setup.redirect) { location.hash = welcomeWanted(configRes) ? "#/welcome" : "#/setup"; return; }
  const conf = configRes && configRes.config && typeof configRes.config === "object" ? configRes.config : null;
  const advanced = conf && typeof conf.advanced_mode === "boolean" ? conf.advanced_mode : navAdvanced;   // a display only: which blocks are drawn
  const profiles = profilesRes && Array.isArray(profilesRes.profiles) ? profilesRes.profiles.filter((p) => p && typeof p === "object" && typeof p.id === "string") : null;
  const toolsRes = profiles && !profiles.length ? await api.get("/api/setup/tools").catch(() => null) : null;
  if (token !== seq) return;
  noteTasks(tasksRes && tasksRes.tasks);
  const state = {
    token, profiles, conf, catalog: catalogRes && catalogRes.ok ? catalogRes : null, chats: chatsRes, routines: routinesRes,
    lamp: ledgerRes && typeof ledgerRes.lamp === "string" ? ledgerRes.lamp : "", waitingList: waitingRes && Array.isArray(waitingRes.waiting) ? waitingRes.waiting : null,
    shown: "", now: () => new Date(),
  };
  const board = boardGroups(D.live, D.flows, D.meetings, D.staffing, D.dispatch, D.groups);
  boardShownKey = boardKey(board, boardKeyContext());
  const waiting = homeWaiting(state, board);
  const advancedPart = advanced ? homeAdvanced({ tasksRes, profilesRes, catalogRes, configRes, board }) : null;
  const main = claim(token);
  let body;
  if (profiles === null) {
    body = [el("section", { class: "section", "data-home": "team" }, sectionHead(WORDS.employeeList.use, null),
      notice("warn", "讀不到員工的資料，所以先不顯示。重新整理看看；還是不行，請到「設定」看一下 VBear 的狀態。")), homeToday(state)];
  } else if (!profiles.length) body = [homeFirstSteps(toolsRes, chatsRes)];
  else body = [homeTeam(state), homeToday(state), homeAsk(state)];
  setKids(main,
    el("h1", null, WORDS.home.use),
    el("p", { class: "lede" }, "這裡看有什麼等你決定、你的員工，和今天要做的事。"),
    corruptNotice(),
    staleNotice(),
    herdrMigrationNotice(),
    setup.notice ? setupUpgradeNotice() : null,
    runtimeNotice(),
    waiting.node,
    body,
    advancedPart ? advancedPart.node : null);
  homeTick = async () => {
    if (token !== seq) return;
    await state.refreshWaiting();
    if (advancedPart) await advancedPart.refresh();
  };
  activeViewCleanup = () => { homeTick = null; };
  // no auto-focus on the boxes: it would scroll the page past what waits for the person
}

// The old lobby, kept whole for the advanced mode: the first game, the board of flows, task cards, the skill search, recent projects, skills with problems.
function homeAdvanced({ tasksRes, profilesRes, catalogRes, configRes, board }) {
  const L = D.live;
  const onboardingHost = el("div", { id: "h-onboarding" });
  const onboardingInput = () => ({
    profiles: profilesRes && Array.isArray(profilesRes.profiles) ? profilesRes.profiles : null,
    catalog: catalogRes && catalogRes.ok ? catalogRes : null,
    tasks: tasksRes && Array.isArray(tasksRes.tasks) ? tasksRes.tasks : null,
    flows: D.flows && !D.flows.error && Array.isArray(D.flows.flows) ? D.flows.flows : null,
    dismissed: configRes && configRes.config && typeof configRes.config.onboarding_dismissed === "boolean" ? configRes.config.onboarding_dismissed : null,
  });
  boardFirstGame = onboardingState(onboardingInput()).mode === "steps";
  const drawOnboarding = () => setKids(onboardingHost, onboardingSection(onboardingState(onboardingInput()), {
    onImport: () => openImportProject({ onCreated: () => route(), onOpenTask: (id) => { location.hash = `#/workbench?task=${encodeURIComponent(id)}`; } }),
    onDismiss: async () => {
      try {
        await api.post("/api/config", { onboarding_dismissed: true });
        configRes.config.onboarding_dismissed = true;
        drawOnboarding();
      } catch (e) { toast("沒有存成：" + e.message); }
    },
  }));
  drawOnboarding();
  const input = el("input", { type: "search", placeholder: "想做什麼？例如：網站安全檢查、做簡報、剪影片、部署…", "aria-label": "用途搜尋技能" });
  const results = el("div", { class: "grid", style: "margin-top:14px" });
  const runSearch = () => {
    const q = input.value.trim();
    if (!q) { setKids(results, ); return; }
    const hits = searchSkills(q, D.skills.filter((s) => s.activation === "active")).slice(0, 6);
    setKids(results, ...(hits.length ? hits.map((h) => skillCard(h.s, h.why)) : [emptyState("沒有找到可使用的技能", "試試別的說法，或到技能庫顯示全部來源")]),
      hits.length ? el("a", { class: "btn", href: `#/skills?q=${encodeURIComponent(q)}`, style: "align-self:start" }, "在技能庫看全部結果 →") : null);
  };
  const searchSoon = debounce(runSearch);
  input.addEventListener("input", searchSoon);
  input.addEventListener("keydown", (e) => { if (e.key === "Enter" && !e.isComposing) { searchSoon.cancel(); location.hash = `#/skills?q=${encodeURIComponent(input.value.trim())}`; } });
  const examples = ["網站安全", "做簡報", "剪影片", "部署網站", "寫小說", "設計品牌"];
  const recentProjects = (L.projects || []).filter((p) => p.live_session_ids.length || p.last_activity).slice(0, 6);
  const problemSkills = (D.overview.skills_with_problems || []).map((id) => D.byId.get(id)).filter(Boolean);
  const node = el("section", { class: "section home-advanced", "data-home": "advanced" },
    el("h2", null, "進階"),
    el("p", { class: "small muted" }, "這一區只有在設定打開進階模式時才看得到。"),
    onboardingHost,
    el("div", { id: "h-board" }, boardSection(board)),
    taskCardsSection(tasksRes && tasksRes.tasks, { flows: D.flows && !D.flows.error ? D.flows.flows || [] : undefined,
      profiles: profilesRes && Array.isArray(profilesRes.profiles) ? profilesRes.profiles : undefined,
      onCreated: () => route(), onOpenTask: (id) => { location.hash = `#/workbench?task=${encodeURIComponent(id)}`; } }),
    el("section", { class: "section" },
      sectionHead("找技能", "用你的話描述要做的事，不需要記得技能名稱"),
      el("div", { class: "search" }, input),
      el("div", { class: "search-hint" }, el("span", { class: "small muted" }, "試試："),
        examples.map((w) => el("button", { type: "button", on: { click: () => { input.value = w; searchSoon.now(); input.focus(); } } }, w))),
      results),
    el("section", { class: "section" },
      sectionHead("最近的專案", null, el("a", { class: "btn small", href: "#/projects" }, "全部專案")),
      recentProjects.length ? el("div", { class: "grid" }, recentProjects.map(projectCard)) : emptyState("最近沒有工作紀錄", null)),
    problemSkills.length ? el("section", { class: "section" },
      sectionHead("需要留意的技能", "可使用的技能中，結構檢查發現問題的項目"),
      el("div", { class: "grid" }, problemSkills.slice(0, 6).map((s) => skillCard(s)))) : null);
  // the board repaints only when something it shows changed, so the search box keeps its focus
  const refresh = async () => {
    const box = document.getElementById("h-board");
    if (!box) return;
    const g = boardGroups(D.live, D.flows, D.meetings, D.staffing, D.dispatch, D.groups);
    const key = boardKey(g, boardKeyContext());
    if (key === boardShownKey) return;
    boardShownKey = key;
    setKids(box, boardSection(g));
  };
  return { node, refresh };
}

// ---------- plain pages (v0.21, P47-2) ----------------------------------------------------------------------------------------
// The home page's blocks, the employees' page and the work page. They read what the console already has (GET only) and set every name and
// sentence as text. A page never guesses: what could not be read is said so, never shown as zero or as an empty team.

const HOME_CEO_ASK = "CEO 要動手前都會先問你。";
const HOME_BUSY_TEXT = "CEO 還在回上一則（或有卡片在等你決定），所以這句話沒有送出。字已經放在他的對話的輸入框裡，按「送出」才會送。";
const HOME_LIMIT_KINDS = ["red", "budget"];

// The chats a routine opened (they are not "a chat with" anyone for the home page): the ids in the routines' runs.
function homeRoutineChatIds(routinesRes) {
  const ids = new Set();
  const list = routinesRes && typeof routinesRes === "object" && Array.isArray(routinesRes.routines) ? routinesRes.routines : [];
  for (const r of list) for (const run of r && Array.isArray(r.runs) ? r.runs : []) if (run && typeof run.chat_id === "string" && run.chat_id) ids.add(run.chat_id);
  return ids;
}
// The chats the person talked in with one employee, newest first. A chat with a problem, one a routine opened and one in a group are not.
function homeChatsOf(chatsRes, routinesRes, profileId) {
  const list = chatsRes && typeof chatsRes === "object" && Array.isArray(chatsRes.chats) ? chatsRes.chats : [];
  const routine = homeRoutineChatIds(routinesRes);
  // a chat the server labels with a routine's title is that routine's own run (the server reads it from the whole record, so it holds for a deleted routine
  // or a run older than the last ten that GET /api/routines lists): it is never "the chat with" the employee
  return list.filter((c) => c && typeof c === "object" && typeof c.id === "string" && c.profile_id === profileId && !c.problem && !routine.has(c.id)
    && typeof c.routine_title !== "string")
    .sort((a, b) => (Number(b.last_at) || 0) - (Number(a.last_at) || 0));
}
// The employee who is the CEO: the first CEO the person made (config first_ceo_id) when that card is there, else the first card whose position is CEO.
function homeCeoOf(profiles, conf) {
  const list = (Array.isArray(profiles) ? profiles : []).filter((p) => p && p.enabled !== false);
  const id = conf && typeof conf.first_ceo_id === "string" ? conf.first_ceo_id : "";
  return list.find((p) => p.id === id) || list.find((p) => cardPosition(p) === "planner") || null;
}
function homeCardOf(chatsRes, profileId) {
  const cards = chatsRes && typeof chatsRes === "object" && Array.isArray(chatsRes.cards) ? chatsRes.cards : null;
  return cards ? cards.find((c) => c && c.id === profileId) || null : null;
}
function homeWhen(sec, now) {
  const t = Number(sec);
  if (!Number.isFinite(t) || t <= 0) return "";
  const d = new Date(t * 1000);
  const two = (n) => String(n).padStart(2, "0");
  const dayStart = (x) => new Date(x.getFullYear(), x.getMonth(), x.getDate()).getTime();
  const gap = Math.round((dayStart(now) - dayStart(d)) / 86400000);
  if (gap === 0) return `${two(d.getHours())}:${two(d.getMinutes())}`;
  if (gap === 1) return "昨天";
  return `${d.getMonth() + 1}/${d.getDate()}`;
}

// Opens the chat with an employee, and with `opts.text` sends it, the way the chat page's 送出 does. One call = at most one POST /api/chats (when
// there is no chat with them yet; opening costs nothing) and at most one POST to its /messages. A card that cannot chat yet leads to the page that
// prepares it (nothing is sent). A chat whose turn is running or that has a card waiting is not sent into: the words are kept for the box of that chat.
// -> { ok, sent, kept, error, chatId }. It always goes to the chat page when it is not an error.
async function openChatWith(profileId, opts = {}) {
  const text = typeof opts.text === "string" ? opts.text : "";
  const [chatsRes, routinesRes] = await Promise.all([api.get("/api/chats").catch(() => null), api.get("/api/routines").catch(() => null)]);
  const card = homeCardOf(chatsRes, profileId);
  const prepare = () => {            // the page that makes the chat ready; the words wait under the employee's id (no chat to put them in yet)
    if (text.trim()) ceoDrafts.set(profileId, text);
    location.hash = `#/chat?profile=${encodeURIComponent(profileId)}`;
  };
  if (card && card.can_chat === false) { prepare(); return { ok: false, sent: false, kept: false, error: null, chatId: "", reason: card.reason || "" }; }
  let chat = homeChatsOf(chatsRes, routinesRes, profileId)[0] || null;
  // The AI tool of this employee cannot chat yet (not checked for chat, held back by an administrator's policy, not logged in...): a new chat would be
  // opened for nothing and a send would be refused, so the person goes to the page that says why, and the words wait under the employee's id.
  // Reading a chat that is already there (no words to send) is still allowed.
  const prep = card ? chatPrepState(card, chatsRes) : null;
  if (prep && prep.kind !== "start" && (!chat || text.trim())) { prepare(); return { ok: false, sent: false, kept: false, error: null, chatId: "", reason: prep.reason }; }
  if (!chat) {
    try {
      const r = await api.post("/api/chats", { profile_id: profileId });
      chat = r && r.chat && typeof r.chat.id === "string" ? { id: r.chat.id, open: false, waiting: false } : null;
    } catch (e) {
      prepare();
      toast("現在還不能開對話：" + e.message);
      return { ok: false, sent: false, kept: false, error: e, chatId: "" };
    }
    if (!chat) { prepare(); return { ok: false, sent: false, kept: false, error: null, chatId: "" }; }
  }
  const go = () => { location.hash = `#/chat/${encodeURIComponent(chat.id)}`; };
  if (!text.trim()) { go(); return { ok: true, sent: false, kept: false, error: null, chatId: chat.id }; }
  if (chat.open === true || chat.waiting === true) {
    ceoDrafts.set(chat.id, text);          // the chat page takes it into its box; only the send button there sends it
    go();
    return { ok: true, sent: false, kept: true, error: null, chatId: chat.id };
  }
  try { await api.post(`/api/chats/${encodeURIComponent(chat.id)}/messages`, { text }); }
  catch (e) { return { ok: false, sent: false, kept: false, error: e, chatId: chat.id }; }
  go();
  return { ok: true, sent: true, kept: false, error: null, chatId: chat.id };
}

// ---- 等你決定 ----
// The rows of what waits for the person, from what the old lobby's 「輪到你」 and the line over every page listed (the same in the normal and
// in the advanced mode). `g`: boardGroups(...); `list`: GET /api/waiting's rows (null = not read); `lamp`: today's lamp ("red" = at the limit).
// -> { rows: [{ kind, key, text, href?, act? }], notes: [what could not be read], complete }. A paused dispatch or group that has its countdown row is not said twice.
function homeWaitingRows(g, list, lamp) {
  const rows = [];
  const notes = [];
  const resumeDispatch = new Set();
  const resumeGroup = new Set();
  if (list === null) notes.push("讀不到定時工作和接著做的提醒");
  for (const w of Array.isArray(list) ? list : []) {
    if (!w || typeof w !== "object" || typeof w.name !== "string") continue;
    if (w.kind === "routine_due" && typeof w.run_id === "string") {
      const at = typeof w.slot === "string" ? w.slot.slice(11, 16) : "";
      rows.push({ kind: "routine_due", key: "due:" + w.run_id, text: `定時工作「${w.name}」${at}到時間了，還沒開始。`, act: { type: "due", id: w.run_id } });
    } else if (w.kind === "routine_missed" && typeof w.routine_id === "string") {
      rows.push({ kind: "routine_missed", key: "missed:" + w.routine_id, text: `定時工作「${w.name}」錯過了 ${Number.isFinite(w.count) ? w.count : 1} 次（VBear 剛才沒在看）。`, act: { type: "missed", id: w.routine_id } });
    } else if (w.kind === "dispatch_resume" && typeof w.dispatch_id === "string") {
      resumeDispatch.add(w.dispatch_id);
      rows.push({ kind: "dispatch_resume", key: "dr:" + w.dispatch_id, text: `分配工作「${w.name}」${typeof w.text === "string" ? w.text : "暫停了"}`, href: `#/dispatch/${encodeURIComponent(w.dispatch_id)}` });
    } else if (w.kind === "group_resume" && typeof w.group_id === "string") {
      resumeGroup.add(w.group_id);
      rows.push({ kind: "group_resume", key: "gr:" + w.group_id, text: `群組「${w.name}」${typeof w.text === "string" ? w.text : "暫停了"}`, href: `#/chat/group/${encodeURIComponent(w.group_id)}` });
    }
  }
  if (g.error) notes.push(`讀不到流程：${g.error}`);
  for (const f of g.yourTurnFlows) {
    const why = f.attention_reason || (f.phase && f.phase.reason) || "";
    rows.push({ kind: "flow", key: "f:" + f.id, text: `流程「${f.task_missing ? "（專案已刪除或無法讀取）" : f.task_title}」等你處理${why ? "：" + why : ""}`, href: `#/flows/${encodeURIComponent(f.id)}` });
  }
  for (const s of g.yourTurnSessions) {
    rows.push({ kind: "session", key: "s:" + s.terminal_id, text: `指令視窗「${s.role_label || TOOL[s.agent] || "未命名"}」在等你回覆`, href: `#/term/${encodeURIComponent(s.pane_id)}` });
  }
  if (g.meetingsError) notes.push(`讀不到會議：${g.meetingsError}`);
  for (const m of g.yourTurnMeetings || []) rows.push({ kind: "meeting", key: "m:" + m.id, text: `會議「${m.topic || "（沒有議題）"}」等你核准`, href: `#/meetings/${encodeURIComponent(m.id)}` });
  if (g.staffingError) notes.push(`讀不到組隊會議：${g.staffingError}`);
  for (const x of g.yourTurnStaffing || []) rows.push({ kind: "staffing", key: "st:" + x.id, text: `組隊會議「${staffingTurnTitle(x)}」等你決定要不要採用`, href: `#/staffing/${encodeURIComponent(x.id)}` });
  if (g.dispatchError) notes.push(`讀不到分配工作：${g.dispatchError}`);
  for (const r of g.yourTurnDispatch || []) {
    if (r.state === "proposed") rows.push({ kind: "dispatch_proposed", key: "dp:" + r.id, text: `幕僚長的提議「${r.title || "（沒有名稱）"}」等你確認（分配工作）`, href: `#/dispatch/${encodeURIComponent(r.id)}` });
    else if (!resumeDispatch.has(r.id)) rows.push({ kind: "dispatch_paused", key: "dq:" + r.id, text: `分配工作「${r.title || "（沒有名稱）"}」暫停了，等你按「繼續」`, href: `#/dispatch/${encodeURIComponent(r.id)}` });
  }
  if (g.groupsError) notes.push(`讀不到群組：${g.groupsError}`);
  for (const r of g.yourTurnGroups || []) {
    if (r.waiting === true) rows.push({ kind: "group_waiting", key: "gw:" + r.id, text: `群組「${r.name || "（沒有名稱）"}」有員工想動手，等你按「允許這一次」或「拒絕」`, href: `#/chat/group/${encodeURIComponent(r.id)}` });
    else if (!resumeGroup.has(r.id)) rows.push({ kind: "group_paused", key: "gq:" + r.id, text: `群組「${r.name || "（沒有名稱）"}」暫停了，等你按「繼續」或「不用了」`, href: `#/chat/group/${encodeURIComponent(r.id)}` });
  }
  if (lamp === "red") rows.push({ kind: "limit", key: "limit", text: "今天的用量到上限了，員工明天 0 點前不會再回話。", href: LIMIT_SETTINGS_HREF, link: "到設定看" });
  return { rows, notes, complete: !notes.length && g.runtimeAvailable === true };
}

const HOME_ROW_BUTTONS = {
  due: [["wait-start", "現在開始", true], ["wait-skip", "這次跳過", false]],
  missed: [["missed-run", "補做", true], ["missed-dismiss", "不用了", false]],
};
function homeRowNode(row, act) {
  const buttons = row.act
    ? HOME_ROW_BUTTONS[row.act.type].map(([key, label, primary]) => el("button", { type: "button", class: `btn small${primary ? " primary" : ""}`, "data-home-action": key,
      on: { click: (e) => { e.target.disabled = true; act(key, row.act.id); } } }, label))
    : [el("a", { class: "btn small", href: row.href, "data-home-action": "go" }, row.link || "去看看")];
  const node = el("div", { class: "home-row", "data-home-row": row.kind },
    el("span", { class: "home-dot", "aria-hidden": "true" }), el("span", { class: "home-row-text" }, row.text), el("span", { class: "home-row-go" }, buttons));
  if (row.kind === "limit") node.setAttribute("data-home", "limit-reached");
  return node;
}
// The block. `state.refreshWaiting()` reads again (the same GETs as the page) and repaints the list only when it changed.
function homeWaiting(state, board) {
  const list = el("div", { class: "home-rows", "data-home": "waiting-list" });
  const note = (m) => notice("warn", m);
  const requests = {
    "wait-start": (id) => api.post(`/api/routines/waiting/${encodeURIComponent(id)}`, { action: "start" }),
    "wait-skip": (id) => api.post(`/api/routines/waiting/${encodeURIComponent(id)}`, { action: "skip" }),
    "missed-run": (id) => api.post(`/api/routines/missed/${encodeURIComponent(id)}`, { action: "run" }),
    "missed-dismiss": (id) => api.post(`/api/routines/missed/${encodeURIComponent(id)}`, { action: "dismiss" }),
  };
  const done = { "wait-start": "已開始", "wait-skip": "這次跳過了", "missed-run": "已開始補做", "missed-dismiss": "不補做了" };
  const act = async (key, id) => {
    try { await requests[key](id); toast(done[key]); } catch (e) { toast(e.message); }
    await state.refreshWaiting();
    refreshWaitingBar();
  };
  const paint = (g) => {
    const m = homeWaitingRows(g, state.waitingList, state.lamp);
    const key = JSON.stringify([m.rows, m.notes, m.complete]);
    if (key === state.shown) return;
    state.shown = key;
    setKids(list,
      m.notes.map(note),
      m.rows.length ? el("div", { class: "home-row-list" }, m.rows.map((r) => homeRowNode(r, act)))
        : el("p", { class: "small muted", "data-home": "waiting-none" }, m.complete ? "現在沒有要你決定的事。" : "目前讀得到的資料裡，沒有要你決定的事。"));
  };
  paint(board);
  state.refreshWaiting = async () => {
    if (state.token !== seq) return;
    await Promise.all([loadLive().then(() => loadFlows()), loadMeetings(), loadStaffingList(), loadDispatchList(), loadGroupList()]);
    const [w, l] = await Promise.all([api.get("/api/waiting").catch(() => null), api.get("/api/meetings/ledger").catch(() => null)]);
    if (state.token !== seq) return;
    state.waitingList = w && Array.isArray(w.waiting) ? w.waiting : null;
    state.lamp = l && typeof l.lamp === "string" ? l.lamp : "";
    paint(boardGroups(D.live, D.flows, D.meetings, D.staffing, D.dispatch, D.groups));
  };
  return { node: el("section", { class: "section home-block", "data-home": "waiting" }, sectionHead(WORDS.waiting.use, null), list) };
}

// ---- 我的員工 ----
