// ---- the note for a task card ----

function meetingDecision(view) {
  const turns = view && Array.isArray(view.turns) ? view.turns : [];
  const t = [...turns].reverse().find((x) => x && x.kind === "decision" && x.state === "done" && x.output && typeof x.output === "object");
  return t ? t.output : null;
}
// Whether the decision may go into a task card: only one the CEO has made, and when it went to the chairman, one the chairman
// approved. A rejected or waiting one is not offered.
function meetingTaskNoteOffer(view) {
  const status = view && view.status;
  if (status === "waiting_chairman") return { ok: false, why: "這場會議要董事長核准，核准之後才能寫進專案。" };
  if (status === "rejected") return { ok: false, why: "董事長已否決，不寫進專案。" };
  if (status === "running") return { ok: false, why: "會議還在進行，CEO 做出決定之後才能寫進專案。" };
  if ((status === "decided" || status === "approved") && meetingDecision(view)) return { ok: true, why: "" };
  return { ok: false, why: "CEO 還沒有做出決定，沒有東西可以寫進專案。" };
}
const MEETING_NOTE_MAX = 2000;
const MEETING_NOTE_ACTIONS_MAX = 1900;
function meetingTaskNote(view) {
  const d = meetingDecision(view) || {};
  const cut = (s, n) => (typeof s === "string" && s.length > n ? s.slice(0, n - 1) + "…" : String(s || ""));
  const lines = [`會議決定（${view.id}，${meetingStatusText(view.status)}）`, `議題：${cut(view.topic, 120)}`, `決定：${cut(d.decision, 300)}`,
    `理由：${cut(d.rationale, 600)}`];
  let text = lines.join("\n");
  const actions = Array.isArray(d.actions) ? d.actions : [];
  if (actions.length) {
    text += "\n要做的事：";
    let shown = 0;
    for (const a of actions) {
      const line = `\n- [${cut(a && a.type, 20)}] ${cut(a && a.text, 200)}`;
      if (text.length + line.length > MEETING_NOTE_ACTIONS_MAX) break;
      text += line;
      shown += 1;
    }
    if (shown < actions.length) text += `\n（還有 ${actions.length - shown} 項，請看會議紀錄）`;
  }
  return text.slice(0, MEETING_NOTE_MAX);
}

// ---- evidence ----

function meetingEvidenceNode(turn) {
  const e = turn && turn.evidence && typeof turn.evidence === "object" ? turn.evidence : null;
  if (!e) return el("p", { class: "small muted", "data-mt": "evidence" }, "沒有證據紀錄（這一位沒有成功呼叫）。");
  const checked = Array.isArray(e.tools_reported) && e.tools_reported.length === 1 && e.tools_reported[0] === "StructuredOutput"
    && Array.isArray(e.mcp_servers_reported) && e.mcp_servers_reported.length === 0;
  const cost = e.cost_usd === undefined || e.cost_usd === null ? "沒有紀錄"
    : `US$${e.cost_usd}（${e.cost_source === "cli" ? "Claude Code 回報" : e.cost_source === "worst_case" ? "沒有回報，以最壞情況計" : "來源不明"}）`;
  return el("ul", { class: "small mt-evidence", "data-mt": "evidence" },
    el("li", null, `Claude Code ${e.cli_version || "版本沒有紀錄"}；回報的模型：${e.model_reported || "沒有紀錄"}`),
    checked ? el("li", { "data-mt": "checked" }, "本次確認：只有 StructuredOutput、沒有 MCP")
      : el("li", null, "本次確認：沒有紀錄（紀錄裡沒有可核對的工具清單）"),
    el("li", null, `花費 ${cost}`),
    Number.isFinite(e.duration_ms) ? el("li", null, `耗時 ${(e.duration_ms / 1000).toFixed(1)} 秒`) : null,
    Number.isInteger(turn.attempts) && turn.attempts > 1 ? el("li", null, `第 ${turn.attempts} 次嘗試`) : null);
}

// ---- the preview dialog (a new meeting and a retry) ----

function meetingPreviewDialog(pv, opts) {
  const people = Array.isArray(pv.participants) ? [...pv.participants, ...(pv.chair ? [pv.chair] : [])] : (pv.participant ? [{ ...pv.participant, prompt: pv.prompt,
    prompt_sha256: pv.prompt_sha256 }] : []);
  const cli = pv.cli && typeof pv.cli === "object" ? pv.cli : {};
  const today = pv.today && typeof pv.today === "object" ? pv.today : {};
  const lim = pv.limits && typeof pv.limits === "object" ? pv.limits : null;
  const blockers = Array.isArray(pv.blockers) ? pv.blockers : [];
  const needsCheck = blockers.some((b) => b && b.code === "boundary_unverified") || cli.verified === false;
  const titleId = "mt-preview-title";
  let modal;
  const cancel = el("button", { class: "btn", type: "button", "data-mt": "cancel-preview", on: { click: () => close() } }, "取消");
  const actions = [cancel];
  const failure = (e) => { toast(e.message); };
  if (needsCheck) {
    // The settings page's 「驗證翻譯安全邊界」 check, through the meetings' own route (POST /api/meetings/verify): that one is
    // always of Claude Code, as every meeting is, while the settings page's checks the translations' engine, which may be
    // Codex. It runs Claude Code once with the person's account, so it is asked in the page first, as there.
    const verify = el("button", { class: "btn", type: "button", "data-mt": "verify", on: { click: async () => {
      close();
      if (!(await confirmInPage("無工具安全檢查", "會用你自己的 Claude 帳號做一次小型檢查，通常不到 1 美分。這和設定頁的「驗證翻譯安全邊界」是同一個檢查；會議一律用 Claude Code，所以不論翻譯引擎選哪一個，這裡都檢查 Claude Code。", "檢查",
        { details: "將用固定的無害提示檢查目前 Claude Code 版本是否只有 StructuredOutput、沒有 MCP。會花極少量額度；請求預算 US$0.05，這不是保證帳單上限。不會改你的翻譯設定。檢查完會重新產生預覽，還不會開始開會。" }))) return;
      try {
        const r = await api.post("/api/meetings/verify", {});
        toast(`Claude Code ${r.version} 通過無工具安全檢查`);
      } catch (e) { toast("檢查失敗：" + e.message); return; }
      if (opts.onRecheck) await opts.onRecheck();
    } } }, "先做無工具安全檢查（用你的 Claude 帳號，通常不到 1 美分）");
    actions.push(verify);
  }
  if (pv.startable === true && typeof pv.preview_id === "string" && pv.preview_id) {
    const start = el("button", { class: "btn primary", type: "button", "data-mt": "start", on: { click: async () => {
      start.disabled = true;
      try { close(); await opts.onStart(pv.preview_id); } catch (e) { failure(e); }
    } } }, opts.startLabel || "開始");
    actions.push(start);
  }
  const person = (p) => el("details", { class: "mt-person", open: true },
    el("summary", null, `${p.name}（${cardHas(CARD_POSITION_LABEL, p.position) ? CARD_POSITION_LABEL[p.position] : "位置未指定"}）・模型 ${p.model || p.model_used || "未知"}`,
      p.effort !== undefined ? ["・", el("span", { "data-mt": "effort" }, `思考強度 ${meetingEffortText(p.effort)}`)] : null,
      p.proxy ? "・代發言（這張卡的工具不是 Claude Code，由 Claude Code 照這個職位的指示發言）" : ""),
    el("div", { class: "small muted" }, "職位指示全文"),
    el("pre", { class: "mt-pre", "data-mt": "instructions" }, typeof p.instructions === "string" ? p.instructions : ""),
    el("div", { class: "small muted" }, "會送出的完整內容（含 VBear 固定的會議規則）"),
    p.dynamic ? el("p", { class: "small" }, "這一段要等前面的結果才組得出來，下面是它的形狀；實際送出的內容會記在會議紀錄裡。") : null,
    el("pre", { class: "mt-pre", "data-mt": "prompt" }, typeof p.prompt === "string" ? p.prompt : ""));
  // The buttons are under every full text: the title takes the keyboard instead, so the dialog opens at its top, where the
  // blockers and the money are (Tab still goes to the buttons).
  const head = el("h2", { id: titleId, tabindex: "-1" }, opts.title || "開會前的預覽");
  modal = el("div", { class: "modal-backdrop", role: "dialog", "aria-modal": "true", "aria-labelledby": titleId, "data-mt": "preview-dialog" },
    el("div", { class: "modal-box mt-preview", style: "max-width: 780px; max-height: 88vh; overflow-y: auto;" },
      head,
      blockers.map((b) => notice("warn", (b && b.message) || "不能開始")),
      pv.decision_again || pv.proposal_again ? notice("info", `這一位重試後，CEO 會重問一次（共 ${pv.calls} 次呼叫）。`) : null,
      el("ul", { class: "small" },
        // the server leaves the version out whenever its provider check fails; which failure it was is its blocker above
        el("li", null, cli.version ? `Claude Code ${cli.version}：${cli.verified === true ? "已通過無工具安全檢查" : "還沒通過無工具安全檢查"}`
          : "Claude Code：沒有讀到已通過無工具安全檢查的版本（原因見上方），所以不能開始"),
        // the money: a meeting's limits by default; a staffing meeting gives its own lines (opts.facts)
        Array.isArray(opts.facts) ? opts.facts
          : el("li", null, `共 ${pv.calls} 次呼叫，預留 US$${pv.reserve_usd}${lim ? `（每次上限 US$${lim.per_call_usd}，每場 US$${lim.meeting_usd}，每天 US$${lim.daily_usd}）` : ""}`),
        today.spent_usd !== undefined ? el("li", null, `今天已花 US$${today.spent_usd}，花費上限 US$${today.daily_usd}`) : null,
        pv.task && pv.task.title ? el("li", null, `專案：${pv.task.title}（只送出欄位內容，不送資料夾路徑）`) : null,
        meetingSpeedText(pv.speed) ? el("li", { "data-mt": "speed" }, meetingSpeedText(pv.speed)) : null),
      opts.extra || null,
      notice("info", pv.disclosure || ""),
      el("p", { class: "small muted" }, pv.cost_note || MEETING_COST_NOTE),
      meetingMoneyWhyNode(),
      people.map(person),
      Array.isArray(pv.rules) && pv.rules.length ? el("details", null, el("summary", null, "什麼情況會交給董事長（固定規則，不是 AI 判斷）"),
        el("ul", { class: "small" }, pv.rules.map((r) => el("li", null, `${r.id}：${r.text}`)))) : null,
      el("div", { class: "modal-actions" }, actions)));
  document.body.append(modal);
  const close = withModalA11y(modal, () => modal.remove());
  head.focus();
  return close;
}

// ---- the page ----

let meetingsTick = null;

async function loadMeetings() {
  try { D.meetings = await api.get("/api/meetings"); }
  catch (e) { D.meetings = { error: e.message, meetings: [] }; }
  return D.meetings;
}
// P35-4: the staffing records, for the home page's board
async function loadStaffingList() {
  try { D.staffing = await api.get("/api/staffing"); }
  catch (e) { D.staffing = { error: e.message, staffing: [] }; }
  return D.staffing;
}

function meetingRow(m) {
  if (m.blocked) {
    return el("li", { class: "mt-row card", "data-mt": "meeting-row" },
      el("strong", null, `無法讀取的會議紀錄 ${m.id}`), badge("無法讀取", "b-bad"),
      el("span", { class: "small muted" }, m.error || "這場會議的紀錄無法安全讀取，已留在清單裡，沒有被刪掉。"));
  }
  return el("li", { class: "mt-row card", "data-mt": "meeting-row", "data-meeting-id": m.id },
    el("a", { class: "mt-row-title", href: `#/meetings/${encodeURIComponent(m.id)}` }, m.topic || "（沒有議題）"),
    meetingStatusBadge(m.status),
    m.major ? badge("重大", "b-warn", "符合交給董事長的固定規則") : null,
    el("span", { class: "small muted" }, `${fmtTime(m.created_at)}・${m.participants} 位・US$${m.spent_usd}（估值）`));
}
function meetingListNode(list) {
  if (!list || list.error) return notice("warn", `讀不到會議：${(list && list.error) || "還沒有讀取到"}`);
  const items = meetingItems(list);
  if (!items.length) return emptyState("還沒有開過會", "在上面選好參加的職位、寫下議題，按「預覽」。");
  return el("ul", { class: "mt-list" }, [...items].sort(meetingNewest).map(meetingRow));
}

function meetingForm(env) {
  const cards = (Array.isArray(env.profiles) ? env.profiles : []).filter((p) => p && typeof p === "object" && typeof p.id === "string" && p.enabled !== false);
  // The position the server checks is the one stored on the card (vbear/agent_profiles.py position_of): a note kept only in
  // this browser is not sent, so a card that has only that note is not offered, and the page says how many there are.
  const positionOf = (p) => cardPosition({ position: p.position });
  const fits = (pos) => pos === MEETING_CHAIR_POSITION || MEETING_SPEAKER_POSITIONS.includes(pos);
  const chairs = cards.filter((p) => positionOf(p) === MEETING_CHAIR_POSITION);
  const speakers = cards.filter((p) => MEETING_SPEAKER_POSITIONS.includes(positionOf(p)));
  const noteOnly = cards.filter((p) => !fits(positionOf(p)) && fits(cardPosition(p))).length;
  const tasksList = (Array.isArray(env.tasks) ? env.tasks : []).filter((t) => t && typeof t === "object" && typeof t.id === "string" && t.status !== "closed");
  const init = env.initial || {};
  const topic = el("textarea", { rows: "2", maxlength: "500", "data-mt": "topic", "aria-label": "議題", placeholder: "這場會議要討論什麼？（最多 500 字）" });
  topic.value = typeof init.topic === "string" ? init.topic : "";
  const context = el("textarea", { rows: "3", maxlength: "4000", "data-mt": "context", "aria-label": "補充說明", placeholder: "補充說明（選填，最多 4000 字）：不要貼密碼、金鑰或個資" });
  const taskSel = el("select", { "data-mt": "task", "aria-label": "專案" },
    el("option", { value: "" }, "（不綁專案）"), tasksList.map((t) => el("option", { value: t.id }, t.title || t.id)));
  taskSel.value = typeof init.task === "string" && tasksList.some((t) => t.id === init.task) ? init.task : "";
  const chairSel = el("select", { "data-mt": "chair", "aria-label": "主席（CEO）" },
    chairs.map((p) => el("option", { value: p.id }, p.name || p.id)));
  if (chairs.length) chairSel.value = chairs[0].id;
  const speakerBoxes = speakers.map((p) => {
    const box = el("input", { type: "checkbox", "data-mt": "speaker", "data-profile": p.id });
    const tool = p.model && typeof p.model === "object" ? p.model.tool : "";
    const label = el("label", { class: "mt-check" }, box,
      el("span", null, `${CARD_POSITION_LABEL[positionOf(p)]}：${p.name || p.id}`, tool && tool !== "claude" ? "（工具不是 Claude Code，由 Claude Code 代發言）" : ""));
    return { box, label, p };
  });
  // P35-4: a staffing proposal brings its staff (speakers=id,id): the ones this form lists are ticked, the rest is said
  const brought = typeof init.speakers === "string" ? [...new Set(init.speakers.split(",").filter(Boolean))].slice(0, 12) : [];
  for (const s of speakerBoxes) if (brought.includes(s.p.id)) s.box.checked = true;
  const tickedHere = speakerBoxes.filter((s) => s.box.checked).length;
  const speakersNote = brought.length ? el("p", { class: "small muted", "data-mt": "speakers-note" },
    `組隊提案帶來的 ${brought.length} 位：勾好了 ${tickedHere} 位`
    + (brought.length - tickedHere ? `；${brought.length - tickedHere} 位不在可以發言的清單裡（停用、職位不能發言，或卡已不在），沒有勾` : "")
    + "。要不要開會、找誰，由你決定；按「預覽」才會送出。") : null;
  const flagBoxes = MEETING_FLAGS.map(([id, text]) => {
    const box = el("input", { type: "checkbox", "data-mt": "flag", "data-flag": id });
    return { box, label: el("label", { class: "mt-check" }, box, el("span", null, text)) };
  });
  const lampNote = el("p", { class: "small", "data-mt": "lamp-note" });
  const preview = el("button", { class: "btn primary", type: "button", "data-mt": "preview", on: { click: () => run() } }, "預覽（還不會開始）");
  const update = (lamp) => {
    const blocked = !lamp.canOpen || !chairs.length || !speakers.length;
    preview.disabled = blocked;
    lampNote.textContent = lamp.canOpen ? ""
      : (lamp.key === "red" ? "今天的用量到你設的上限了（或已封鎖），先不開新的會議。" : "讀不到今天的花費，先不開新的會議。");
  };
  async function run() {
    const t = topic.value.trim();
    if (!t) { toast("請寫下議題"); topic.focus(); return; }
    if (t.length > 500) { toast("議題不可超過 500 字"); return; }
    if (context.value.trim().length > 4000) { toast("補充說明不可超過 4000 字"); return; }
    if (!chairs.length || !chairSel.value) { toast("需要一張 CEO 職位的員工當主席"); return; }
    const chosen = speakerBoxes.filter((s) => s.box.checked);
    if (!chosen.length) { toast("請至少選一個發言的職位"); return; }
    if (chosen.length > 6) { toast("最多 6 位發言者"); return; }
    if (new Set(chosen.map((s) => positionOf(s.p))).size !== chosen.length) { toast("每個職位只能有一張卡發言"); return; }
    const body = { topic: t, chair_profile_id: chairSel.value, speaker_profile_ids: chosen.map((s) => s.p.id),
      flags: flagBoxes.filter((f) => f.box.checked).map((f) => f.box.getAttribute("data-flag")) };
    if (context.value.trim()) body.context = context.value.trim();
    if (taskSel.value) body.task_id = taskSel.value;
    preview.disabled = true;
    try {
      const pv = await api.post("/api/meetings/preview", body);
      meetingPreviewDialog(pv, { title: "開會前的預覽", startLabel: "開始開會",
        onRecheck: run,
        onStart: async (previewId) => {
          const res = await api.post("/api/meetings", { preview_id: previewId });
          toast("會議開始了");
          location.hash = `#/meetings/${encodeURIComponent(res.id)}`;
        } });
    } catch (e) { toast(e.message); }
    finally { preview.disabled = false; env.syncLamp(); }
  }
  const node = el("section", { class: "section mt-form", "data-mt": "form" },
    sectionHead("開一場會", "你是董事長。各職位各發言一次（彼此看不到對方的發言；有選專案時 PM 另外會拿到它的進度摘要，會計師會拿到這場會議到目前為止的花費），CEO 看完全部發言後做決定；重大的事交給你核准。開始前一定先給你看會送出的全文。"),
    !chairs.length ? notice("warn", el("span", null, "還沒有 CEO 職位的員工，沒有主席就不能開會。到 ", el("a", { href: "#/employees" }, "員工頁"), " 新增一位（精靈第 2 步選 CEO）。")) : null,
    !speakers.length ? notice("warn", "還沒有可以發言的職位卡（PM、社群媒體經理、全端工程師、藝術總監、法務經理、會計師）。") : null,
    noteOnly ? el("p", { class: "small muted", "data-mt": "note-only" },
      `有 ${noteOnly} 張卡的職位只記在這個瀏覽器（舊版的備註），沒有存在卡片上；開會看的是卡片上存的職位，所以這裡沒有列出。`,
      "要讓它們參加，到員工頁用精靈重新選一次職位並儲存。") : null,
    el("label", null, "議題 *", topic),
    el("label", null, "補充說明", context),
    el("label", null, "綁在哪個專案（選填）", taskSel),
    el("label", null, "主席（CEO）", chairSel),
    el("fieldset", { class: "mt-fieldset" }, el("legend", null, "誰來發言（每個職位一張卡）"), speakersNote,
      speakerBoxes.length ? speakerBoxes.map((s) => s.label) : el("span", { class: "small muted" }, "沒有可選的卡")),
    el("fieldset", { class: "mt-fieldset" }, el("legend", null, "這件事涉及（勾了就一定交給你核准）"), flagBoxes.map((f) => f.label)),
    lampNote,
    el("div", { class: "row" }, preview));
  return { node, update };
}

async function viewMeetings(id, params) {
  const token = seq;
  if (id) return viewMeetingDetail(token, id);
  const [list, ledgerData, profilesRes, tasksRes] = await Promise.all([
    api.get("/api/meetings").catch((e) => ({ error: e.message, meetings: [] })),
    api.get("/api/meetings/ledger").catch(() => null),
    api.get("/api/agent-profiles").catch(() => null),
    api.get("/api/tasks").catch(() => null)]);
  const main = claim(token);
  let current = { list, lamp: meetingLamp(ledgerData) };
  const lampBox = el("div", { class: "mt-lamp-box" });
  const listBox = el("div", { class: "mt-list-box" });
  const form = meetingForm({ profiles: profilesRes && profilesRes.profiles, tasks: tasksRes && tasksRes.tasks, initial: params || {},
    syncLamp: () => form.update(current.lamp) });
  const draw = () => {
    setKids(lampBox, meetingLampNode(current.lamp));
    setKids(listBox, meetingListNode(current.list));
    form.update(current.lamp);
  };
  draw();
  setKids(main,
    el("h1", null, "會議"),
    el("p", { class: "lede" }, "各職位發言，CEO 做決定，重大的事交給你（董事長）。決定只是紀錄，不會自己去執行。"),
    needsClaudeSlot(token, "會議由 Claude Code 主持發言。"),
    lampBox,
    meetingMoneyWhyNode(),
    form.node,
    el("section", { class: "section" }, sectionHead("會議紀錄", "每 5 秒更新"), listBox));
  meetingsTick = async () => {
    const [l2, g2] = await Promise.all([api.get("/api/meetings").catch((e) => ({ error: e.message, meetings: [] })),
      api.get("/api/meetings/ledger").catch(() => null)]);
    current = { list: l2, lamp: meetingLamp(g2) };
    D.meetings = l2;
    if (token === seq) draw();
  };
  activeViewCleanup = () => { meetingsTick = null; };
}

async function viewMeetingDetail(token, id) {
  let cur;
  try { cur = await api.get(`/api/meetings/${encodeURIComponent(id)}`); }
  catch (e) {
    setKids(claim(token), crumbs([["會議", "#/meetings"], ["找不到"]]), notice("bad", e.status === 404 ? e.message : "讀不到這場會議：" + e.message));
    return;
  }
  const tasksRes = await api.get("/api/tasks").catch(() => null);
  const tasksList = tasksRes && Array.isArray(tasksRes.tasks) ? tasksRes.tasks.filter((t) => t && typeof t.id === "string") : [];
  const main = claim(token);
  const root = el("div", { class: "mt-detail" });
  const reload = async () => {
    try { cur = await api.get(`/api/meetings/${encodeURIComponent(id)}`); } catch (e) { toast("讀不到這場會議：" + e.message); return; }
    if (token === seq) draw();
  };
  const act = async (fn) => {
    try { const res = await fn(); if (res && typeof res === "object" && res.id === id) cur = res; if (token === seq) draw(); }
    catch (e) { toast(e.message); await reload(); }
  };
  // P35-4: adopting the draft. Each step is the person's press, through an endpoint that already exists; afterwards the
  // cards and the flows are read again and the list is drawn from them.
  const did = new Set();
  const made = staffingMadeRead(id);
  let stepBusy = false;
  const refreshCards = async () => {
    const [p, f] = await Promise.all([api.get("/api/agent-profiles").catch(() => null), api.get("/api/flows").catch(() => null)]);
    if (p && Array.isArray(p.profiles)) profiles = p.profiles;
    flows = f && Array.isArray(f.flows) ? f.flows : null;
  };
  const stepDone = async (key, fn) => {
    if (stepBusy) return;
    stepBusy = true;
    try { if ((await fn()) !== false) did.add(key); } catch (e) { toast(e.message); }
    stepBusy = false;
    await refreshCards();
    if (token === seq) draw();
  };
  const skillName = (sid) => { const sk = skills.find((x) => x && x.skill_id === sid); return sk ? String(sk.name || sid) : `${STAFFING_NOT_FOUND}（${sid}）`; };
  const recorded = (res) => {
    store.set(STAFFING_DRAFT_KEY + id, null);
    store.set(STAFFING_MADE_KEY + id, null);
    return res;
  };
  function adoptActs(view, env, draft, keep) {
    const task = tasksList.find((t) => t.id === view.task_id);
    return {
      canWizard: Boolean(catalog && Array.isArray(catalog.tools)),
      taskFound: Boolean(task),
      enable: (p) => { keep(); stepDone("enable", () => api.post(`/api/agent-profiles/${encodeURIComponent(p.id)}`, { enabled: true })); },
      create: (ref) => {
        keep();
        const n = env.news.get(ref);
        if (!n) return;
        // the wizard ticks what it can of these: the skills of every taken row of this new card, and the CEO's for it
        const skillIds = [...new Set(draft.rows.filter((r) => r.take && r.who && r.who.type === "new" && r.who.ref === ref)
          .flatMap((r) => staffingAdoptSkills(r, env)))];
        openCardWizard({ catalog, profiles, draft: { name: n.name, position: n.position, tool: n.tool, modelId: n.model_alias, skillIds },
          onSaved: async (saved) => {
            if (saved && typeof saved.id === "string") { made[ref] = saved.id; store.set(STAFFING_MADE_KEY + id, made); did.add("create"); }
            await refreshCards();
            if (token === seq) draw();
          } });
      },
      insert: (c) => {
        keep();
        stepDone("skills", async () => {
          const line = (words) => el("span", { class: "st-confirm-line" }, words);
          const names = (ids) => (ids.length ? ids.map(skillName).join("、") : "（沒有）");
          const after = c.before.concat(c.add);
          const ok = await confirmInPage(`插上技能：${c.card.name || c.card.id}`, [
            line(`插上前（${c.before.length} 張）：${names(c.before)}`), line(`插上後（${after.length} 張）：${names(after)}`),
            line(`新增：${names(c.add)}`), c.skipped.length ? line(`有 ${c.skipped.length} 張這張卡讀不到或不在技能庫，不插：${names(c.skipped)}`) : null,
            line("插上技能只是紀錄，不會安裝或下載。")], "插上");
          if (!ok) return false;
          return api.post(`/api/agent-profiles/${encodeURIComponent(c.card.id)}`, { equipped_skill_ids: after });
        });
      },
      team: (slots) => {
        keep();
        setTeamPreset({ taskId: view.task_id, from: id, slots });
        location.hash = `#/workbench?task=${encodeURIComponent(view.task_id)}`;
      },
      meetingHref: (staff) => `#/meetings?task=${encodeURIComponent(view.task_id)}&speakers=${encodeURIComponent(staff.join(","))}`,
      adopt: (note, rows) => act(async () => recorded(await api.post(`/api/staffing/${encodeURIComponent(id)}/chairman`, { decision: "adopt", note, adopted: { rows } }))),
      dismiss: (note) => act(async () => recorded(await api.post(`/api/staffing/${encodeURIComponent(id)}/chairman`, { decision: "dismiss", note }))),
    };
  }

  function seatCard(seat) {
    const t = seat.turn;
    const o = t && t.output && typeof t.output === "object" ? t.output : null;
    const body = [];
    if (t && t.state === "done" && t.kind === "opinion" && o) {
      body.push(el("p", null, badge(typeof o.stance === "string" ? o.stance : MEETING_UNKNOWN, "b-info"), " ", o.summary || ""));
      if (Array.isArray(o.points) && o.points.length) body.push(el("ul", { class: "small" }, o.points.map((p) => el("li", null, String(p)))));
      if (Array.isArray(o.risks) && o.risks.length) {
        body.push(el("div", { class: "small muted" }, "風險"), el("ul", { class: "small" }, o.risks.map((r) =>
          el("li", null, badge(r && r.level ? String(r.level) : "?", r && r.level === "高" ? "b-bad" : r && r.level === "中" ? "b-warn" : "b-mute"), " ",
            String((r && r.text) || ""), r && r.source ? el("span", { class: "muted" }, `（出處：${r.source}）`) : null))));
      }
      if (o.needs_chairman === true) body.push(el("p", { class: "small" }, badge("要求交董事長", "b-warn")));
      if (seat.position === "accountant") body.push(el("p", { class: "small muted" }, "會計師的數字是 AI 寫的，未經程式核算；VBear 只自己核算花費。"));
    } else if (t && t.state === "done" && t.kind === "decision") {
      body.push(el("p", { class: "small muted" }, "CEO 的決定在下面「CEO 決定」。"));
    } else if (t && t.state === "queued") body.push(el("p", { class: "small muted" }, "還沒輪到。"));
    else if (t && t.state === "running") body.push(el("p", { class: "small muted" }, "正在發言…"));
    else if (t) {
      const why = meetingErrorText(t.error_code);
      body.push(el("p", { class: "small", "data-mt": "reason" }, `${MEETING_BUBBLES.includes(seat.bubble) ? seat.bubble : MEETING_UNKNOWN}${why ? "：" + why : ""}`));
    } else body.push(el("p", { class: "small muted" }, "紀錄裡沒有這一位的發言。"));
    // the server refuses a retry once the chairman has decided (already_decided): it is not offered, and the page says so
    const chair = cur.chairman && typeof cur.chairman === "object" ? cur.chairman.state : "";
    const decided = chair === "approved" || chair === "rejected";
    const canRetry = t && Array.isArray(cur.retryable) && cur.retryable.includes(t.seq) && cur.status !== "running";
    const retry = canRetry && !decided
      ? el("button", { class: "btn small", type: "button", "data-mt": "retry", on: { click: () => retryOf(t.seq) } },
        `重試這一位（先給你看預覽）`)
      : canRetry ? el("p", { class: "small muted", "data-mt": "no-retry" }, "董事長已經決定了，這場會議不能再重試；要重新討論，請開新的會議。") : null;
    return el("article", { class: "card mt-card", "data-mt": "seat", "data-profile": seat.profileId },
      el("div", { class: "mt-card-head" }, officeSprite(seat.species, seat.camp, 2),
        el("div", { style: "min-width:0" }, el("strong", null, seat.name),
          el("div", { class: "small muted" }, `${seat.positionLabel}・${TOOL[seat.tool] || seat.tool || "未知工具"}・模型 ${seat.model || "未知"}`)),
        seat.proxy ? badge("代發言", "b-info", "這張卡的工具不是 Claude Code，由 Claude Code 照這個職位的指示代為發言") : null,
        el("span", { class: "mt-bubble" }, seat.bubble)),
      body, meetingEvidenceNode(t), retry);
  }

  async function retryOf(seqNo) {
    let pv;
    try { pv = await api.post(`/api/meetings/${encodeURIComponent(id)}/retry-preview`, { seq: seqNo }); }
    catch (e) { toast(e.message); return; }
    meetingPreviewDialog(pv, { title: "重試前的預覽", startLabel: "重試",
      onRecheck: () => retryOf(seqNo),
      onStart: async (previewId) => { await act(() => api.post(`/api/meetings/${encodeURIComponent(id)}/retry`, { preview_id: previewId })); } });
  }

  function decisionBlock() {
    const d = meetingDecision(cur);
    if (!d) return null;
    return el("section", { class: "section", "data-mt": "decision" },
      sectionHead("CEO 決定", "這只是紀錄：VBear 不會去執行它。要做的話，寫進專案，再照原本的流程。"),
      el("div", { class: "card pad" },
        el("p", null, el("strong", null, d.decision || "")),
        el("p", null, d.rationale || ""),
        Array.isArray(d.dissent_addressed) && d.dissent_addressed.length ? [el("div", { class: "small muted" }, "對不同意見的回應"),
          el("ul", { class: "small" }, d.dissent_addressed.map((x) => el("li", null, String(x))))] : null,
        Array.isArray(d.actions) && d.actions.length ? [el("div", { class: "small muted" }, "要做的事"),
          el("ul", null, d.actions.map((a) => el("li", null, badge(String((a && a.type) || "?"), "b-info"), " ", String((a && a.text) || ""))))] : null,
        d.escalate === true ? notice("warn", `CEO 要求交給董事長：${d.escalate_reason || "（沒有寫原因）"}`) : null,
        Array.isArray(d.follow_up_topics) && d.follow_up_topics.length ? [el("div", { class: "small muted" }, "CEO 提議的下一場議題（只會填進表單，要你按預覽才會開）"),
          d.follow_up_topics.map((x) => el("button", { class: "btn small", type: "button", "data-mt": "follow-up", on: { click: () => {
            location.hash = `#/meetings?topic=${encodeURIComponent(String(x))}${cur.task_id ? "&task=" + encodeURIComponent(cur.task_id) : ""}`;
          } } }, `開新會議討論：${x}`))] : null));
  }

  function chairmanBlock() {
    const c = cur.chairman && typeof cur.chairman === "object" ? cur.chairman : { state: "pending" };
    const note = el("textarea", { rows: "2", maxlength: "500", "data-mt": "chairman-note", "aria-label": "備註（選填）", placeholder: "備註（選填，最多 500 字）" });
    const decide = (decision) => act(() => api.post(`/api/meetings/${encodeURIComponent(id)}/chairman`, { decision, note: note.value.trim() }));
    let head;
    const buttons = [];
    if (cur.status === "running") head = "會議進行中，結束後才能決定。";
    else if (c.state === "approved") head = "董事長已核准";
    else if (c.state === "rejected") head = "董事長已否決";
    else if (cur.status === "waiting_chairman") {
      head = "輪到你：董事長核准";
      buttons.push(el("button", { class: "btn primary", type: "button", "data-mt": "approve", on: { click: () => decide("approve") } }, "核准"));
    } else head = cur.status === "decided" ? "CEO 已決定（不需要董事長核准，你仍然可以否決）" : "CEO 還沒有做出決定";
    if (cur.status !== "running" && c.state !== "approved" && c.state !== "rejected") {
      buttons.push(el("button", { class: "btn", type: "button", "data-mt": "reject", on: { click: () => decide("reject") } }, "否決"));
    }
    return el("section", { class: `section mt-chairman${cur.status === "waiting_chairman" ? " mt-chairman-waits" : ""}`, "data-mt": "chairman" },
      sectionHead("董事長桌", MEETING_CHAIRMAN_NOTE),
      el("div", { class: "card pad" },
        el("p", null, el("strong", null, head)),
        Array.isArray(cur.rules) && cur.rules.length ? [el("div", { class: "small muted" }, "為什麼要交給董事長（固定規則，AI 只能把它升級、不能降級）"),
          el("ul", { class: "small", "data-mt": "rules" }, cur.rules.map((r) => el("li", null, `${r.id}：${r.text}`)))] : null,
        c.note ? el("p", { class: "small" }, `備註：${c.note}`) : null,
        c.at ? el("p", { class: "small muted" }, `${fmtTime(c.at)}・${MEETING_CHAIRMAN_NOTE}`) : null,
        buttons.length ? [el("label", null, "備註", note), el("div", { class: "row" }, buttons)] : null));
  }

  function taskNoteBlock() {
    const offer = meetingTaskNoteOffer(cur);
    const nodes = [];
    const go = (taskId) => { location.hash = `#/workbench?task=${encodeURIComponent(taskId)}&meeting=${encodeURIComponent(id)}`; };
    if (!offer.ok) nodes.push(el("p", { class: "small muted", "data-mt": "write-task-why" }, offer.why));
    else if (cur.task_id) {
      nodes.push(el("button", { class: "btn", type: "button", "data-mt": "write-task", on: { click: () => go(cur.task_id) } }, "把決定寫進專案"),
        el("span", { class: "small muted" }, "只會打開專案的編輯器並填好文字，要你自己按「儲存修改」。"));
    } else if (tasksList.length) {
      const pick = el("select", { class: "mt-task-pick", "data-mt": "write-task-pick", "aria-label": "寫進哪個專案" },
        el("option", { value: "" }, "（選一個專案）"), tasksList.map((t) => el("option", { value: t.id }, t.title || t.id)));
      const btn = el("button", { class: "btn", type: "button", disabled: true, "data-mt": "write-task", on: { click: () => { if (pick.value) go(pick.value); } } },
        "把決定寫進專案");
      pick.addEventListener("change", () => { btn.disabled = !pick.value; });
      nodes.push(pick, btn, el("span", { class: "small muted" }, "只會打開編輯器並填好文字，要你自己按「儲存修改」。"));
    } else nodes.push(el("p", { class: "small muted", "data-mt": "write-task-why" }, "沒有專案可以寫。"));
    return el("section", { class: "section", "data-mt": "task-note" }, sectionHead("寫進專案", null), el("div", { class: "row" }, nodes));
  }

  function draw() {
    const seats = meetingSeats(cur);
    const task = cur.task_id ? tasksList.find((t) => t.id === cur.task_id) : null;
    const running = cur.status === "running";
    const flags = Array.isArray(cur.flags_by_chairman) ? cur.flags_by_chairman : [];
    setKids(root,
      el("div", { class: "row" }, el("h1", null, cur.topic || "（沒有議題）")),
      el("div", { class: "row small" }, meetingStatusBadge(cur.status), cur.major ? badge("重大", "b-warn", "符合交給董事長的固定規則") : null,
        el("span", { class: "muted" }, `會議紀錄 ${cur.id}・${fmtTime(cur.created_at)}・花費 US$${cur.spent_usd}（估值）`),
        cur.task_id ? el("a", { href: `#/workbench?task=${encodeURIComponent(cur.task_id)}` }, task ? `專案：${task.title}` : "專案") : null),
      flags.length ? el("p", { class: "small" }, `你建立時勾了：${flags.map((f) => (MEETING_FLAGS.find((x) => x[0] === f) || [f, f])[1]).join("、")}`) : null,
      cur.context ? el("p", { class: "small" }, `補充說明：${cur.context}`) : null,
      meetingClockText(cur.clock) ? el("p", { class: "small mt-clock", "data-mt": "clock", role: "status" }, meetingClockText(cur.clock)) : null,
      el("p", { class: "small muted" }, MEETING_COST_NOTE),
      meetingMoneyWhyNode(),
      el("section", { class: "section" }, sectionHead("座位", "每一位的內容都是紀錄裡的原文；模型寫的字一律當文字顯示，這裡只有證據是 VBear 自己整理的。"),
        el("div", { class: "mt-cards" }, seats.map(seatCard))),
      decisionBlock(), chairmanBlock(), taskNoteBlock(),
      el("div", { class: "row" },
        running ? el("button", { class: "btn", type: "button", "data-mt": "cancel", on: { click: () => act(() => api.post(`/api/meetings/${encodeURIComponent(id)}/cancel`, {})) } }, "取消這場會議") : null,
        !running ? el("button", { class: "btn", type: "button", "data-mt": "delete", on: { click: async () => {
          if (!(await confirmInPage("刪除會議", `確定要刪除這場會議「${cur.topic}」的紀錄嗎？刪除後無法復原。`, "刪除"))) return;
          try { await api.del(`/api/meetings/${encodeURIComponent(id)}`); toast("會議已刪除"); location.hash = "#/meetings"; }
          catch (e) { toast("刪除失敗：" + e.message); }
        } } }, "刪除這場會議") : null));
  }
  draw();
  setKids(main, crumbs([["會議", "#/meetings"], [cur.topic || id]]), root);
  if (cur.status === "running") {
    meetingsTick = async () => { if (cur.status === "running") await reload(); };
    activeViewCleanup = () => { meetingsTick = null; };
  }
}

// A task card's meetings: the ones about it, newest first, and the way to a new one.
function taskMeetingsBlock(taskId, data) {
  const rows = data && Array.isArray(data.meetings)
    ? data.meetings.filter((m) => m && typeof m === "object" && !m.blocked && m.task_id === taskId).sort(meetingNewest) : null;
  return el("div", { class: "wb-field-group", "data-mt": "task-meetings" },
    el("div", { class: "wb-field-label" }, "相關會議"),
    el("div", { class: "wb-field-val" },
      rows && rows.length ? el("ul", { style: "margin:0 0 6px; padding-left:18px" }, rows.slice(0, 5).map((m) =>
        el("li", null, el("a", { href: `#/meetings/${encodeURIComponent(m.id)}` }, m.topic || "（沒有議題）"), " ", meetingStatusBadge(m.status))))
        : el("p", { class: "small muted" }, rows ? "這張任務卡還沒有開過會。" : "讀不到會議清單。"),
      el("a", { class: "btn small", href: `#/meetings?task=${encodeURIComponent(taskId)}` }, "開會討論")));
}

// ---------- staffing meetings (P35-3) -------------------------------------------------------------------------------
// The pages of a staffing meeting (vbear/staffing_runner.py): the form on one task card, the preview, the list, and one
// staffing meeting. VBear ticks who it suggests to speak, with each reason, by a fixed table (vbear/staffing.py
// SUGGEST_SPEAKERS); the person may change all of it. Every speaker says once, alone, then the CEO writes a staffing
// proposal. What a page shows is the record: a bubble or a status comes from a closed table, an alias of the record (C1,
// S1, N1) is shown as the name of what it stands for today, or as 「找不到」, and what a model wrote is set as text. Nothing
// here creates a card, inserts a skill or puts anyone on a team: a staffing meeting starts only from a preview the person
// confirmed, and its proposal is a record.

const STAFFING_STATUS = {
  running: ["進行中", "b-info"], ready: ["CEO 已提案：等你看", "b-warn"], incomplete: ["沒有完成", "b-bad"],
  adopted: ["已記下：採用", "b-ok"], dismissed: ["已記下：不採用", "b-mute"],
};
function staffingStatusText(status) { return cardHas(STAFFING_STATUS, status) ? STAFFING_STATUS[status][0] : MEETING_UNKNOWN; }
function staffingStatusBadge(status) {
  return badge(staffingStatusText(status), cardHas(STAFFING_STATUS, status) ? STAFFING_STATUS[status][1] : "b-mute");
}
// The speaking positions in the order of VBear's table (vbear/staffing.py SUGGEST_SPEAKERS); a test keeps them equal.
const STAFFING_SPEAKER_ORDER = ["pm", "executor", "legal", "accountant", "social", "art"];
const STAFFING_SPEAKERS_MAX = 6;
const STAFFING_NOTE_MAX = 500;   // vbear/staffing.py NOTE_MAX
const STAFFING_DISABLED_NOTE = "停用的卡不能發言，但 CEO 可以提案用它（採用時要先由你啟用）。";
const STAFFING_WHAT = "各職位先各自發言一次（彼此看不到），CEO 看完全部發言後寫組隊提案：4 個位置各放誰、開會找哪些幕僚、要不要新建卡、"
  + "每人插哪些技能、缺哪些技能，以及採納了誰的意見。提案只是建議：VBear 不會自己建卡、插技能或排隊伍，每一步都由你自己按。";

function staffingItems(list) {
  return list && typeof list === "object" && Array.isArray(list.staffing) ? list.staffing.filter((r) => r && typeof r === "object") : [];
}
function staffingTaskTitle(taskId, tasksList) {
  const t = (Array.isArray(tasksList) ? tasksList : []).find((x) => x && x.id === taskId);
  return t ? t.title || "（沒有名稱）" : "（找不到這張任務卡）";
}
function staffingRow(r, tasksList) {
  if (r.blocked) {
    return el("li", { class: "mt-row card", "data-st": "staffing-row" },
      el("strong", null, `無法讀取的組隊紀錄 ${r.id}`), badge("無法讀取", "b-bad"),
      el("span", { class: "small muted" }, r.error || "這份組隊紀錄無法安全讀取，已留在清單裡，沒有被刪掉。"));
  }
  return el("li", { class: "mt-row card", "data-st": "staffing-row", "data-staffing-id": r.id },
    el("a", { class: "mt-row-title", href: `#/staffing/${encodeURIComponent(r.id)}` }, `組隊會議：${staffingTaskTitle(r.task_id, tasksList)}`),
    staffingStatusBadge(r.status),
    r.high_risk === true ? badge("有高風險", "b-warn", "有發言者把風險標成「高」；這只是提醒") : null,
    el("span", { class: "small muted" }, `${fmtTime(r.created_at)}・${r.participants} 位・US$${r.spent_usd}（估值）`));
}
function staffingListNode(list, tasksList, empty) {
  if (!list || list.error) return notice("warn", `讀不到組隊會議：${(list && list.error) || "還沒有讀取到"}`);
  const items = staffingItems(list);
  if (!items.length) return emptyState(empty || "還沒有組隊會議", "在任務卡上按「請 CEO 組隊」。");
  return el("ul", { class: "mt-list" }, [...items].sort(meetingNewest).map((r) => staffingRow(r, tasksList)));
}

// A task card's staffing meetings, newest first, and the way to a new one (the workbench's task tab).
function taskStaffingBlock(taskId, data) {
  const all = data && Array.isArray(data.staffing) ? data.staffing.filter((r) => r && typeof r === "object") : null;
  const rows = all ? all.filter((r) => !r.blocked && r.task_id === taskId).sort(meetingNewest) : null;
  const blocked = all ? all.filter((r) => r.blocked).length : 0;
  return el("div", { class: "wb-field-group", "data-st": "task-staffing" },
    el("div", { class: "wb-field-label" }, "組隊會議"),
    el("div", { class: "wb-field-val" },
      rows && rows.length ? el("ul", { style: "margin:0 0 6px; padding-left:18px" }, rows.slice(0, 5).map((r) =>
        el("li", null, el("a", { href: `#/staffing/${encodeURIComponent(r.id)}` }, `組隊會議（${fmtTime(r.created_at)}）`), " ", staffingStatusBadge(r.status))))
        : el("p", { class: "small muted" }, rows ? "這張任務卡還沒有組隊會議。" : "讀不到組隊會議清單。"),
      blocked ? el("p", { class: "small muted" }, `有 ${blocked} 份組隊紀錄無法讀取，請到組隊會議頁查看。`) : null,
      el("a", { class: "btn small", href: `#/staffing?task=${encodeURIComponent(taskId)}` }, "請 CEO 組隊")));
}

// ---- the preview's own lines: the money as a staffing meeting reserves it, the list, VBear's suggestions ----

function staffingPreviewFacts(pv) {
  const r = pv.reserve && typeof pv.reserve === "object" ? pv.reserve : null;
  const lim = pv.limits && typeof pv.limits === "object" ? pv.limits : null;
  const reserve = r ? `預留 US$${pv.reserve_usd} ＝ 發言 ${r.speakers} × US$${r.per_call_usd} ＋ CEO US$${r.proposal_call_usd}` : `預留 US$${pv.reserve_usd}`;
  const limits = lim ? `；這份組隊提案最多 US$${lim.total_usd}，每天 US$${lim.daily_usd}（和會議共用）` : "";
  const list = pv.list && typeof pv.list === "object" ? pv.list : null;
  const left = list && list.omitted && typeof list.omitted === "object" ? list.omitted : {};
  return [el("li", { "data-st": "reserve" }, `共 ${pv.calls} 次呼叫，${reserve}${limits}`),
    list ? el("li", { "data-st": "list-size" }, `送出的清單：角色卡 ${list.cards} 張、技能 ${list.skills} 張；另有 ${left.cards} 張角色卡、${left.skills} 張技能沒有列出`
      + "（發言者和 CEO 看得到這個數字；卡和技能只用代號，不送真正的 id）") : null];
}
function staffingSuggestedNode(pv) {
  const list = Array.isArray(pv.suggested) ? pv.suggested.filter((x) => x && typeof x === "object") : null;
  if (!list) return null;
  return el("div", { class: "small", "data-st": "suggested" },
    el("div", { class: "muted" }, "VBear 建議的人選（固定規則，不是 AI 判斷）"),
    list.length ? el("ul", null, list.map((x) => el("li", null,
      `${x.name || x.profile_id}（${cardHas(CARD_POSITION_LABEL, x.position) ? CARD_POSITION_LABEL[x.position] : "位置未指定"}）：${x.why || ""}——`,
      x.chosen === true ? "你勾了" : "你沒勾")))
      : el("p", null, "VBear 這次沒有建議任何人選。"));
}

// ---- the form ----

function staffingForm(env) {
  const task = env.task;
  const suggested = Array.isArray(env.suggest.suggested) ? env.suggest.suggested.filter((x) => x && typeof x.profile_id === "string") : [];
  const why = new Map(suggested.map((x) => [x.profile_id, typeof x.why === "string" ? x.why : ""]));
  const all = (Array.isArray(env.profiles) ? env.profiles : []).filter((p) => p && typeof p === "object" && typeof p.id === "string");
  // the position the server checks is the one stored on the card (vbear/agent_profiles.py position_of)
  const positionOf = (p) => cardPosition({ position: p.position });
  const cards = all.filter((p) => p.enabled !== false);
  const chairs = cards.filter((p) => positionOf(p) === MEETING_CHAIR_POSITION);
  const order = (p) => STAFFING_SPEAKER_ORDER.indexOf(positionOf(p));
  const speakers = cards.filter((p) => order(p) >= 0).sort((a, b) => (order(a) - order(b)) || ((why.has(a.id) ? 0 : 1) - (why.has(b.id) ? 0 : 1))
    || String(a.name || "").localeCompare(String(b.name || "")) || a.id.localeCompare(b.id));
  const disabled = all.filter((p) => p.enabled === false && STAFFING_SPEAKER_ORDER.includes(positionOf(p))).length;
  const categories = Array.isArray(env.suggest.categories) ? env.suggest.categories.filter((c) => c && typeof c === "object") : [];
  const chairSel = el("select", { "data-mt": "chair", "aria-label": "主席（CEO）" }, chairs.map((p) => el("option", { value: p.id }, p.name || p.id)));
  if (chairs.length) chairSel.value = chairs[0].id;
  const boxes = speakers.map((p) => {
    const box = el("input", { type: "checkbox", "data-st": "speaker", "data-profile": p.id });
    box.checked = why.has(p.id);
    const tool = p.model && typeof p.model === "object" ? p.model.tool : "";
    const label = el("label", { class: "mt-check st-speaker" }, box,
      el("span", null, `${CARD_POSITION_LABEL[positionOf(p)]}：${p.name || p.id}`, tool && tool !== "claude" ? "（工具不是 Claude Code，由 Claude Code 代發言）" : ""),
      why.has(p.id) ? el("span", { class: "small st-why", "data-st": "why" }, `VBear 建議：${why.get(p.id)}`)
        : el("span", { class: "small muted" }, "VBear 沒有建議（你可以自己勾）"));
    return { box, label, p };
  });
  const note = el("textarea", { rows: "3", maxlength: String(STAFFING_NOTE_MAX), "data-st": "note", "aria-label": "補充說明",
    placeholder: `給大家的補充說明（選填，最多 ${STAFFING_NOTE_MAX} 字）：不要貼密碼、金鑰或個資` });
  const lampNote = el("p", { class: "small", "data-mt": "lamp-note" });
  const preview = el("button", { class: "btn primary", type: "button", "data-mt": "preview", on: { click: () => run() } }, "預覽（還不會開始）");
  const update = (lamp) => {
    preview.disabled = !lamp.canOpen || !chairs.length || !speakers.length;
    lampNote.textContent = lamp.canOpen ? ""
      : (lamp.key === "red" ? "今日額度已用完（或已封鎖），先不開新的組隊會議。" : "讀不到今天的花費，先不開新的組隊會議。");
  };
  async function run() {
    if (!chairs.length || !chairSel.value) { toast("需要一張 CEO 職位的角色卡當主席"); return; }
    const chosen = boxes.filter((s) => s.box.checked);
    if (!chosen.length) { toast("請至少選一位發言者"); return; }
    if (chosen.length > STAFFING_SPEAKERS_MAX) { toast(`最多 ${STAFFING_SPEAKERS_MAX} 位發言者`); return; }
    if (new Set(chosen.map((s) => positionOf(s.p))).size !== chosen.length) { toast("每個職位只能有一張卡發言"); return; }
    const text = note.value.trim();
    if (text.length > STAFFING_NOTE_MAX) { toast(`補充說明不可超過 ${STAFFING_NOTE_MAX} 字`); return; }
    const body = { task_id: task.id, chair_profile_id: chairSel.value, speaker_profile_ids: chosen.map((s) => s.p.id) };
    if (text) body.note = text;
    preview.disabled = true;
    try {
      const pv = await api.post("/api/staffing/preview", body);
      meetingPreviewDialog(pv, { title: "組隊會議前的預覽", startLabel: "開始組隊會議", facts: staffingPreviewFacts(pv), extra: staffingSuggestedNode(pv),
        onRecheck: run,
        onStart: async (previewId) => {
          const res = await api.post("/api/staffing", { preview_id: previewId });
          toast("組隊會議開始了");
          location.hash = `#/staffing/${encodeURIComponent(res.id)}`;
        } });
    } catch (e) { toast(e.message); }
    finally { preview.disabled = false; env.syncLamp(); }
  }
  const node = el("section", { class: "section mt-form", "data-st": "form" },
    sectionHead("請 CEO 組隊", `VBear 依任務內容先勾好建議來開會的人，並寫出理由；你可以改，最多 ${STAFFING_SPEAKERS_MAX} 位，每個職位一張卡。開始前一定先給你看會送出的全文。`),
    el("p", { class: "small" }, STAFFING_WHAT),
    !chairs.length ? notice("warn", el("span", null, "還沒有 CEO 職位的角色卡，沒有 CEO 就不能組隊。到 ", el("a", { href: "#/team" }, "角色卡池"), " 建一張（精靈第 2 步選 CEO）。")) : null,
    !speakers.length ? notice("warn", "還沒有可以發言的職位卡（PM、全端工程師、法務經理、會計師、社群媒體經理、藝術總監）。") : null,
    el("p", { class: "small", "data-st": "categories" }, categories.length
      ? `VBear 從任務文字分出的分類：${categories.map((c) => `${c.label}（提到「${c.keyword}」）`).join("、")}`
      : "VBear 沒有從任務文字分出任何分類。"),
    el("label", null, "主席（CEO，寫組隊提案）", chairSel),
    el("fieldset", { class: "mt-fieldset st-speakers" }, el("legend", null, "誰來發言（VBear 先勾好，你可以改；每個職位一張卡）"),
      boxes.length ? boxes.map((s) => s.label) : el("span", { class: "small muted" }, "沒有可選的卡")),
    el("p", { class: "small muted", "data-st": "disabled-note" }, disabled ? `有 ${disabled} 張發言職位的卡停用中，沒有列在這裡。` : "", STAFFING_DISABLED_NOTE),
    el("label", null, "補充說明", note),
    el("p", { class: "small muted" }, "思考強度只用低或中（會議為了快，不提供高）；每位的強度和這場的時間上限，預覽裡會寫明。"),
    el("p", { class: "small muted" }, "預留的錢 = 發言人數 × 發言者每次上限 ＋ CEO 每次上限；實際數字、這份組隊提案的上限和每天的上限（和會議共用），預覽裡會寫明。"),
    lampNote,
    el("div", { class: "row" }, preview));
  return { node, update };
}

// ---- the pages ----

let staffingTick = null;

async function viewStaffing(id, params) {
  const token = seq;
  if (id) return viewStaffingDetail(token, id);
  const taskId = params && typeof params.task === "string" && params.task ? params.task : "";
  const listPath = taskId ? `/api/staffing?task_id=${encodeURIComponent(taskId)}` : "/api/staffing";
  const [suggest, list, ledgerData, profilesRes, tasksRes] = await Promise.all([
    taskId ? api.get(`/api/staffing/suggest?task_id=${encodeURIComponent(taskId)}`).catch((e) => ({ error: e.message || "讀不到" })) : null,
    api.get(listPath).catch((e) => ({ error: e.message, staffing: [] })),
    api.get("/api/meetings/ledger").catch(() => null),
    taskId ? api.get("/api/agent-profiles").catch(() => null) : null,
    api.get("/api/tasks").catch(() => null)]);
  const main = claim(token);
  const tasksList = tasksRes && Array.isArray(tasksRes.tasks) ? tasksRes.tasks.filter((t) => t && typeof t.id === "string") : [];
  let current = { list, lamp: meetingLamp(ledgerData) };
  const lampBox = el("div", { class: "mt-lamp-box" });
  const listBox = el("div", { class: "mt-list-box" });
  let form = null;
  const draw = () => {
    setKids(lampBox, meetingLampNode(current.lamp));
    setKids(listBox, staffingListNode(current.list, tasksList, taskId ? "這張任務卡還沒有組隊會議" : null));
    if (form) form.update(current.lamp);
  };
  if (taskId) {
    const task = tasksList.find((t) => t.id === taskId) || { id: taskId, title: "" };
    if (suggest.error) {
      setKids(main, crumbs([["組隊會議", "#/staffing"], ["找不到"]]), notice("bad", suggest.error));
      return;
    }
    form = staffingForm({ task, suggest, profiles: profilesRes && profilesRes.profiles, syncLamp: () => form.update(current.lamp) });
    draw();
    setKids(main, crumbs([["組隊會議", "#/staffing"], [task.title || taskId]]),
      el("h1", null, `請 CEO 組隊：${task.title || "（沒有名稱）"}`),
      needsClaudeSlot(token, "組隊會議由 Claude Code 主持發言。"),
      lampBox, meetingMoneyWhyNode(), form.node,
      el("section", { class: "section" }, sectionHead("這張任務卡的組隊會議", "每 5 秒更新"), listBox));
  } else {
    const open = tasksList.filter((t) => t.status !== "closed" && t.status !== "handed_off");
    const pick = el("select", { class: "mt-task-pick", "data-st": "task-pick", "aria-label": "替哪張任務卡組隊" },
      el("option", { value: "" }, "（選一張任務卡）"), open.map((t) => el("option", { value: t.id }, t.title || t.id)));
    pick.addEventListener("change", () => { if (pick.value) location.hash = `#/staffing?task=${encodeURIComponent(pick.value)}`; });
    draw();
    setKids(main, el("h1", null, "組隊會議"),
      el("p", { class: "lede" }, STAFFING_WHAT),
      needsClaudeSlot(token, "組隊會議由 Claude Code 主持發言。"),
      lampBox, meetingMoneyWhyNode(),
      el("section", { class: "section" }, sectionHead("替哪張任務卡組隊", "選好之後，VBear 會先勾好建議的人選。"),
        open.length ? pick : el("p", { class: "small muted" }, "沒有未結案的任務卡。")),
      el("section", { class: "section" }, sectionHead("組隊紀錄", "每 5 秒更新"), listBox));
  }
  staffingTick = async () => {
    const [l2, g2] = await Promise.all([api.get(listPath).catch((e) => ({ error: e.message, staffing: [] })),
      api.get("/api/meetings/ledger").catch(() => null)]);
    current = { list: l2, lamp: meetingLamp(g2) };
    if (token === seq) draw();
  };
  activeViewCleanup = () => { staffingTick = null; };
}

// ---- one staffing meeting: bubbles, seats, names ----

// The only words a seat's bubble can say on a staffing meeting. Whatever the record holds, the bubble is one of these.
const STAFFING_BUBBLES = ["等發言", "發言中", "已建議", "失敗", "卡住", "額度不夠沒發言", "時間到沒發言", "無法確認花費", "沒有發言", "已取消", "中斷",
  "整理意見中", "已提案", MEETING_UNKNOWN];
function staffingBubble(turn) {
  if (!turn || typeof turn !== "object" || (turn.kind !== "opinion" && turn.kind !== "proposal")) return MEETING_UNKNOWN;
  const chair = turn.kind === "proposal";
  switch (turn.state) {
    case "queued": return "等發言";
    case "running": return chair ? "整理意見中" : "發言中";
    case "done": return chair ? "已提案" : "已建議";
    case "failed": return "失敗";
    case "blocked": return "卡住";
    case "skipped": return skippedBubble(turn.error_code);
    case "cancelled": return "已取消";
    case "interrupted": return "中斷";
    default: return MEETING_UNKNOWN;
  }
}
function staffingSeats(view) { return meetingSeats(view, { bubble: staffingBubble, record: "組隊紀錄" }); }

// What VBear says of an item it kept but did not tick in advance (vbear/staffing.py FLAGS; a test keeps them equal).
const STAFFING_FLAG_TEXT = {
  disabled: "這張卡停用中，要先啟用",
  cannot_start: "VBear 不能幫這張卡出發（安全模式下的 Codex、AGY、Grok、MCODE，或共用卡）",
  slot_fit: "這張卡的職位和這個位置不太合",
  same_card: "同一張卡不能審查自己",
  reviewer_family_unknown: "審查位的陣營是「共用」或不明，審查結果不算數",
  executor_family_unknown: "執行位的陣營是「共用」或不明，審查結果不算數",
  same_family: "審查位和執行位同一陣營，審查結果不算數",
  already_equipped: "這張卡已經插著這張技能",
};
function staffingFlagText(code) { return typeof code === "string" && cardHas(STAFFING_FLAG_TEXT, code) ? STAFFING_FLAG_TEXT[code] : `代碼：${code}`; }
function staffingFlagNodes(flags) {
  const list = Array.isArray(flags) ? flags : [];
  return list.map((f) => (f === "already_equipped" ? badge("已插上", "b-mute", STAFFING_FLAG_TEXT.already_equipped) : badge(staffingFlagText(f), "b-warn")));
}
const STAFFING_NOT_FOUND = "找不到";
const STAFFING_SLOT_LABEL = { planner: "規劃位", executor: "執行位", reviewer1: "審查位", reviewer2: "第二位審查", staff: "開會時找的幕僚" };
const STAFFING_SLOTS = ["planner", "executor", "reviewer1", "reviewer2"];
function staffingPositionText(position) { return cardHas(CARD_POSITION_LABEL, position) ? CARD_POSITION_LABEL[position] : "位置未指定"; }

function staffingKept(turn) {
  return turn && turn.state === "done" && turn.output && typeof turn.output === "object" && turn.output.kept && typeof turn.output.kept === "object"
    ? turn.output.kept : null;
}
function staffingProposalOf(view) {
  const turns = view && Array.isArray(view.turns) ? view.turns : [];
  const last = turns.length ? turns[turns.length - 1] : null;
  return last && last.kind === "proposal" ? staffingKept(last) : null;
}
function staffingList(obj, key) { return obj && Array.isArray(obj[key]) ? obj[key].filter((x) => x && typeof x === "object") : []; }

// What each alias of a record stands for today: a card (C#) through the record's list to the card as it is now, a skill (S#)
// to the skill in the catalog, a new card (N#) to the CEO's new cards. What cannot be found reads 「找不到」, with its alias.
function staffingNames(view, profiles, skills) {
  const sent = view && view.sent && typeof view.sent === "object" ? view.sent : {};
  const cardAlias = new Map(staffingList(sent, "cards").map((c) => [c.alias, c]));
  const skillAlias = new Map(staffingList(sent, "skills").map((s) => [s.alias, s]));
  const byId = new Map((Array.isArray(profiles) ? profiles : []).filter((p) => p && typeof p.id === "string").map((p) => [p.id, p]));
  const skillById = new Map((Array.isArray(skills) ? skills : []).filter((s) => s && typeof s.skill_id === "string").map((s) => [s.skill_id, s]));
  const news = new Map(staffingList(staffingProposalOf(view), "new_cards").map((n) => [n.ref, n]));
  const changed = new Set(view && Array.isArray(view.changed_cards) ? view.changed_cards : []);
  const missing = (kind, alias) => ({ kind, alias, found: false, text: `${STAFFING_NOT_FOUND}（${typeof alias === "string" ? alias : ""}）` });
  function card(alias) {
    const row = cardAlias.get(alias);
    const p = row ? byId.get(row.profile_id) : null;
    if (!p) return missing("card", alias);
    const tool = p.model && typeof p.model.tool === "string" ? p.model.tool : "";
    return { kind: "card", alias, found: true, profile: p, profileId: p.id, tool, enabled: p.enabled !== false, changed: changed.has(alias),
      text: String(p.name || p.id) };
  }
  function newCard(ref) {
    const n = news.get(ref);
    return n ? { kind: "new", alias: ref, found: true, newCard: n, tool: n.tool, text: `新卡「${n.name}」（建議新建）` } : missing("new", ref);
  }
  function skill(alias) {
    const row = skillAlias.get(alias);
    const s = row ? skillById.get(row.skill_id) : null;
    return s ? { alias, found: true, skill: s, skillId: s.skill_id, text: String(s.name || s.skill_id) } : missing("skill", alias);
  }
  // a skill's or a gap's "for": a card, a new card, then a position (a speaker's) or a place (the CEO's)
  function place(v, prefer) {
    if (typeof v !== "string") return missing("place", "");
    if (/^C[0-9]+$/.test(v)) return card(v);
    if (/^N[0-9]+$/.test(v)) return newCard(v);
    const pos = cardHas(CARD_POSITION_LABEL, v) ? CARD_POSITION_LABEL[v] : null;
    const slot = cardHas(STAFFING_SLOT_LABEL, v) ? STAFFING_SLOT_LABEL[v] : null;
    const words = prefer === "slot" ? slot || pos : pos || slot;
    return words ? { kind: "place", alias: v, found: true, text: words } : missing("place", v);
  }
  return { card, newCard, skill, place, byId, skillById, news };
}

// ---- skill gaps: plain text, and a search of this console's skill library ----

function staffingGapLink(word, category) {
  const cat = typeof category === "string" && category && category !== "other" ? `&cat=${encodeURIComponent(category)}` : "";
  return `#/skills?q=${encodeURIComponent(typeof word === "string" ? word : "")}${cat}`;
}
function staffingCategoryLabel(id, table) {
  if (id === "other") return "其他";
  const row = (Array.isArray(table) ? table : []).find((c) => c && c.id === id);
  return row && typeof row.label === "string" ? row.label : String(id || "");
}
// What the skill library holds of a gap's category: none, some this card reads, or only some it does not. No card (a
// speaker's gap): only how many there are.
function staffingGapState(gap, tool, skills, table) {
  if (!gap || gap.category === "other") return "分類是「其他」，VBear 沒有比對技能庫";
  const label = staffingCategoryLabel(gap.category, table);
  const same = (Array.isArray(skills) ? skills : []).filter((s) => s && Array.isArray(s.categories) && s.categories.includes(gap.category));
  if (!same.length) return `技能庫沒有「${label}」分類的技能（目前沒有安裝）`;
  if (!tool) return `技能庫有 ${same.length} 張「${label}」分類的技能`;
  const can = same.filter((s) => skillCompatible(s, tool)).length;
  if (!can) return `技能庫有 ${same.length} 張可能相關，但這張卡讀不到`;
  return `技能庫有 ${can} 張「${label}」分類、這張卡讀得到的技能${same.length > can ? `（另有 ${same.length - can} 張讀不到）` : ""}`;
}
// ctx: { names, skills, categories, toolOf(gap) -> tool or "" , prefer }
function staffingGapsNode(gaps, ctx) {
  if (!gaps.length) return null;
  return [el("div", { class: "small muted" }, "技能缺口（只是清單：要不要裝、去哪裡裝由你決定；VBear 不會安裝或下載）"),
    el("ul", { class: "small st-gaps" }, gaps.map((g) => {
      const words = Array.isArray(g.search_words) ? g.search_words.filter((w) => typeof w === "string" && w) : [];
      const label = staffingCategoryLabel(g.category, ctx.categories);
      return el("li", { "data-st": "gap" },
        el("strong", null, String(g.need || "")), `（${label}）`,
        typeof g.for === "string" ? `，給 ${ctx.names.place(g.for, ctx.prefer).text}` : "",
        g.why ? `：${g.why}` : "",
        el("div", { class: "muted", "data-st": "gap-state" }, staffingGapState(g, ctx.toolOf ? ctx.toolOf(g) : "", ctx.skills, ctx.categories)),
        words.length ? el("div", { class: "row" }, words.map((w) => el("a", { class: "btn small", href: staffingGapLink(w, g.category), "data-st": "gap-link" },
          `去技能庫搜尋「${w}」`)))
          : g.category !== "other" ? el("a", { class: "btn small", href: staffingGapLink("", g.category), "data-st": "gap-link" }, `去技能庫看「${label}」分類`) : null);
    }))];
}

// ---- what one speaker said, by names ----

function staffingOpinionNodes(kept, ctx) {
  const n = ctx.names;
  const out = [el("p", null, String(kept.summary || ""))];
  const needs = staffingList(kept, "needs");
  if (needs.length) {
    out.push(el("div", { class: "small muted" }, "這個任務需要的能力"),
      el("ul", { class: "small" }, needs.map((x) => el("li", null, `${x.what}（${staffingPositionText(x.position)}）`))));
  }
  const rec = staffingList(kept, "recommend");
  if (rec.length) {
    out.push(el("div", { class: "small muted" }, "推薦的人選"), el("ul", { class: "small" }, rec.map((x) => el("li", { "data-st": "recommend" },
      el("strong", null, x.card ? n.card(x.card).text : "沒有合適的卡"),
      x.slot === "staff" ? `：${STAFFING_SLOT_LABEL.staff}` : `：放${STAFFING_SLOT_LABEL[x.slot] || STAFFING_NOT_FOUND}`,
      `（${staffingPositionText(x.position)}）`, x.why ? `：${x.why}` : "", " ", staffingFlagNodes(x.flags)))));
  }
  const picks = staffingList(kept, "skills");
  if (picks.length) {
    out.push(el("div", { class: "small muted" }, "建議插的技能"), el("ul", { class: "small" }, picks.map((x) => el("li", { "data-st": "skill-pick" },
      el("strong", null, n.skill(x.skill).text), ` 給 ${n.place(x.for, "position").text}`, x.why ? `：${x.why}` : "", " ", staffingFlagNodes(x.flags)))));
  }
  const gaps = staffingGapsNode(staffingList(kept, "skill_gaps"), { ...ctx, prefer: "position", toolOf: () => "" });
  if (gaps) out.push(gaps);
  const risks = staffingList(kept, "risks");
  if (risks.length) {
    out.push(el("div", { class: "small muted" }, "風險"), el("ul", { class: "small" }, risks.map((r) =>
      el("li", null, badge(String(r.level || "?"), r.level === "高" ? "b-bad" : r.level === "中" ? "b-warn" : "b-mute"), " ", String(r.text || ""),
        r.source ? el("span", { class: "muted" }, `（出處：${r.source}）`) : null))));
  }
  return out;
}
// A note names what it is about by its alias (「C3」, 「S1」, 「N1」), as the record keeps it; the page adds what each alias is
// today, by the same names as the rest of the page, or that it is not found.
function staffingNoteText(words, names) {
  const aliases = [];
  for (const m of words.matchAll(/「([CSN][1-9][0-9]{0,2})」/g)) if (!aliases.includes(m[1])) aliases.push(m[1]);
  if (!names || !aliases.length) return words;
  const what = aliases.map((a) => {
    const x = a[0] === "C" ? names.card(a) : a[0] === "S" ? names.skill(a) : names.newCard(a);
    return !x.found ? `${a} ${STAFFING_NOT_FOUND}` : a[0] === "N" ? `${a} 是新卡「${x.newCard.name}」` : `${a} 是「${x.text}」`;
  });
  return `${words}（${what.join("；")}）`;
}

function staffingNotesNode(output, names) {
  const notes = output && Array.isArray(output.notes) ? output.notes.filter((x) => x && typeof x.text === "string") : [];
  return notes.length ? [el("div", { class: "small muted" }, "VBear 拿掉或改動的地方"),
    el("ul", { class: "small", "data-st": "notes" }, notes.map((x) => el("li", null, staffingNoteText(x.text, names))))] : null;
}

// ---- the CEO's proposal, by names ----

function staffingProposalNode(kept, output, ctx) {
  const n = ctx.names;
  const who = (x) => (x.pick === "existing" ? n.card(x.card).text : x.pick === "new" ? n.newCard(x.new_ref).text : "空著");
  const skillsOf = (x) => {
    const list = staffingList(x, "skills");
    return list.length ? el("ul", { class: "small" }, list.map((s) => el("li", null, el("strong", null, n.skill(s.skill).text), s.why ? `：${s.why}` : "", " ",
      badge("CEO 建議", "b-info"), " ", staffingFlagNodes(s.flags)))) : null;
  };
  const team = staffingList(kept, "team");
  const toolOfSlot = (slot) => {
    const x = team.find((t) => t.slot === slot);
    return !x ? "" : x.pick === "existing" ? n.card(x.card).tool || "" : x.pick === "new" ? n.newCard(x.new_ref).tool || "" : "";
  };
  const toolOfGap = (g) => (/^[CN][0-9]+$/.test(g.for) ? n.place(g.for, "slot").tool || "" : toolOfSlot(g.for));
  const used = staffingList(kept, "opinions_used");
  const opinion = (x) => el("li", null, el("strong", null, staffingPositionText(x.from)), `：${x.point}`, x.why ? `——${x.why}` : "");
  const lines = (key, title) => {
    const list = Array.isArray(kept[key]) ? kept[key].filter((x) => typeof x === "string") : [];
    return list.length ? [el("h3", null, title), el("ul", { class: "small" }, list.map((x) => el("li", null, x)))] : null;
  };
  return el("div", { class: "card pad st-proposal" },
    el("p", null, el("strong", null, String(kept.summary || ""))),
    el("h3", null, "任務卡的 4 個位置"),
    el("ul", { class: "st-rows" }, STAFFING_SLOTS.map((slot) => {
      const x = team.find((t) => t.slot === slot);
      if (!x) return el("li", { "data-st": "team-row", "data-slot": slot }, el("strong", null, STAFFING_SLOT_LABEL[slot]), "：（CEO 沒有寫這個位置）");
      return el("li", { "data-st": "team-row", "data-slot": slot },
        el("strong", null, STAFFING_SLOT_LABEL[slot]), `：${who(x)} `, staffingFlagNodes(x.flags),
        x.reason ? el("div", { class: "small" }, `理由：${x.reason}`) : null, skillsOf(x));
    })),
    staffingList(kept, "staff").length ? [el("h3", null, "開會時找的幕僚"), el("ul", { class: "st-rows" }, staffingList(kept, "staff").map((x) =>
      el("li", { "data-st": "staff-row", "data-position": x.position }, el("strong", null, staffingPositionText(x.position)), `：${who(x)} `, staffingFlagNodes(x.flags),
        x.reason ? el("div", { class: "small" }, `理由：${x.reason}`) : null, skillsOf(x))))] : null,
    staffingList(kept, "new_cards").length ? [el("h3", null, "建議新建的卡（要你自己用精靈建）"), el("ul", { class: "st-rows" }, staffingList(kept, "new_cards").map((x) =>
      el("li", { "data-st": "new-card" }, el("strong", null, String(x.name || "")),
        `（${staffingPositionText(x.position)}・${CARD_TOOL_LABEL[x.tool] || x.tool}${x.model_alias ? `・模型 ${x.model_alias}` : ""}）`,
        x.reason ? el("div", { class: "small" }, `理由：${x.reason}`) : null, skillsOf(x))))] : null,
    staffingGapsNode(staffingList(kept, "skill_gaps"), { ...ctx, prefer: "slot", toolOf: toolOfGap }),
    el("h3", null, "採納與沒採納的意見"),
    el("div", { class: "st-opinions" },
      el("div", { "data-st": "adopted" }, el("h4", null, "採納的意見"), used.filter((x) => x.adopted === true).length
        ? el("ul", { class: "small" }, used.filter((x) => x.adopted === true).map(opinion)) : el("p", { class: "small muted" }, "（沒有）")),
      el("div", { "data-st": "not-adopted" }, el("h4", null, "沒採納的意見"), used.filter((x) => x.adopted === false).length
        ? el("ul", { class: "small" }, used.filter((x) => x.adopted === false).map(opinion)) : el("p", { class: "small muted" }, "（沒有）"))),
    lines("risks", "CEO 看到的風險"), lines("questions_for_chairman", "要問你（董事長）的"),
    staffingNotesNode(output, n));
}

// ---- the person's draft of the proposal ----
// The proposal as the person changes it before adopting it: who is in each place and on the staff, whether a row is to be
// adopted, and which skills to insert. It is kept in this browser only (staffing.edit.<id>) and sends nothing. VBear checks
// a row again by the page's own rules (the card as it is now, the place it fits, a review's camp against the executor's,
// as on a task card) and does not tick a row it flags; a row is never ticked by a change in another row.
const STAFFING_SLOT_FIT = { planner: ["planner", "pm"], executor: ["executor", "social", "art"], reviewer1: ["reviewer", "executor"],
  reviewer2: ["reviewer", "executor"] };   // vbear/staffing.py SLOT_FIT; a test keeps them equal
const STAFFING_STAFF_POSITIONS = ["pm", "legal", "accountant", "social", "art", "executor"];   // vbear/staffing.py STAFF_POSITIONS
const STAFFING_DRAFT_KEY = "staffing.edit.";
const STAFFING_DRAFT_NOTE = "草稿只存在這個瀏覽器，不會改角色卡、技能或隊伍；VBear 標出問題的列預設不勾，要不要採用由你決定。";
const STAFFING_SWAP_NOTE = "換過人：VBear 能不能幫這張卡出發，這裡沒有重新判斷，請看角色卡上的出發通行證。";

function staffingDraftBasis(view) {
  const turns = Array.isArray(view.turns) ? view.turns : [];
  const t = turns[turns.length - 1] || {};
  return `${t.seq}:${t.attempts}:${t.ended_at}`;
}
// env: { byId (cards by id, as they are now), news (the CEO's new cards by ref), skills, skillById, names, made (P35-4: the
// card the wizard made from a new card, by ref) }. A new card made in the wizard is that card, as it is now.
function staffingDraftWho(who, env) {
  if (!who || typeof who !== "object") return null;
  if (who.type === "card") {
    const p = env.byId.get(who.profileId);
    if (!p) return { found: false, text: STAFFING_NOT_FOUND, tool: "", position: null, equipped: [] };
    const tool = p.model && typeof p.model.tool === "string" ? p.model.tool : "";
    return { found: true, key: p.id, text: String(p.name || p.id), tool, position: cardPosition({ position: p.position }), enabled: p.enabled !== false,
      equipped: Array.isArray(p.equipped_skill_ids) ? p.equipped_skill_ids : [] };
  }
  const n = who.type === "new" ? env.news.get(who.ref) : null;
  const madeId = n && env.made && cardHas(env.made, who.ref) ? env.made[who.ref] : "";
  if (madeId && env.byId.has(madeId)) {
    const w = staffingDraftWho({ type: "card", profileId: madeId }, env);
    return { ...w, made: true, text: `${w.text}（由 CEO 建議的新卡建立）` };
  }
  return n ? { found: true, key: who.ref, text: `新卡「${n.name}」（建議新建）`, tool: n.tool, position: n.position, enabled: true, equipped: [] }
    : { found: false, text: STAFFING_NOT_FOUND, tool: "", position: null, equipped: [] };
}
function staffingDraftFlags(row, rows, env) {
  const w = staffingDraftWho(row.who, env);
  if (!w || !w.found) return [];
  const out = [];
  if (w.enabled === false) out.push("disabled");
  if (!row.swapped && row.serverFlags.includes("cannot_start")) out.push("cannot_start");   // the server's, for the card it was given
  if (!(row.kind === "slot" ? STAFFING_SLOT_FIT[row.place] : [row.place]).includes(w.position)) out.push("slot_fit");
  if (row.kind === "slot" && row.place.startsWith("reviewer")) {
    const ex = rows.find((r) => r.kind === "slot" && r.place === "executor");
    const ew = ex ? staffingDraftWho(ex.who, env) : null;
    const like = (x) => ({ profile_id: x.key, tool: x.tool });
    const problem = slotProblem(row.place, like(w), { executor: ew && ew.found ? like(ew) : null });
    if (problem) out.push(problem.code);
  }
  return out;
}
function staffingDraftFrom(view, env) {
  const kept = staffingProposalOf(view);
  const row = (x, kind, place) => {
    let who = null;
    let lost = "";
    if (x && x.pick === "existing") {
      const c = env.names.card(x.card);
      if (c.found) who = { type: "card", profileId: c.profileId }; else lost = String(x.card || "");
    } else if (x && x.pick === "new" && typeof x.new_ref === "string") who = { type: "new", ref: x.new_ref };
    const skills = [];
    let gone = 0;
    for (const s of staffingList(x, "skills")) {
      const sk = env.names.skill(s.skill);
      if (!sk.found) { gone += 1; continue; }
      if (!skills.some((y) => y.skillId === sk.skillId)) skills.push({ skillId: sk.skillId, take: true, ceo: true });
    }
    return { key: `${kind}:${place}`, kind, place, who, lost, gone, serverFlags: Array.isArray(x && x.flags) ? x.flags.filter((f) => typeof f === "string") : [],
      swapped: false, take: false, skills, dropped: 0 };
  };
  const rows = STAFFING_SLOTS.map((slot) => row(staffingList(kept, "team").find((t) => t.slot === slot), "slot", slot));
  for (const x of staffingList(kept, "staff")) {
    if (STAFFING_STAFF_POSITIONS.includes(x.position) && !rows.some((r) => r.key === `staff:${x.position}`)) rows.push(row(x, "staff", x.position));
  }
  for (const r of rows) r.take = Boolean(r.who) && !r.serverFlags.length && !staffingDraftFlags(r, rows, env).length;
  return { basis: staffingDraftBasis(view), rows };
}
// A draft kept in this browser, read back only when it is of this very proposal and every row is one this page could
// have written; anything else is dropped (stale says it was of an earlier proposal).
function staffingDraftRead(id, view) {
  const raw = store.get(STAFFING_DRAFT_KEY + id, null);
  const basis = staffingDraftBasis(view);
  if (!raw || typeof raw !== "object") return { draft: null, stale: false };
  if (raw.basis !== basis) return { draft: null, stale: typeof raw.basis === "string" };
  if (!Array.isArray(raw.rows)) return { draft: null, stale: false };
  const rows = [];
  const str = (v) => typeof v === "string";
  for (const r of raw.rows) {
    if (!r || typeof r !== "object") return { draft: null, stale: false };
    const okPlace = r.kind === "slot" ? STAFFING_SLOTS.includes(r.place) : r.kind === "staff" && STAFFING_STAFF_POSITIONS.includes(r.place);
    const okWho = r.who === null || (r.who && r.who.type === "card" && str(r.who.profileId)) || (r.who && r.who.type === "new" && /^N[1-3]$/.test(r.who.ref));
    const okSkills = Array.isArray(r.skills) && r.skills.every((s) => s && str(s.skillId) && typeof s.take === "boolean" && typeof s.ceo === "boolean");
    if (!okPlace || !okWho || !okSkills || typeof r.take !== "boolean" || typeof r.swapped !== "boolean" || !Array.isArray(r.serverFlags)
        || !r.serverFlags.every(str) || rows.some((x) => x.key === `${r.kind}:${r.place}`)) return { draft: null, stale: false };
    rows.push({ key: `${r.kind}:${r.place}`, kind: r.kind, place: r.place, who: r.who ? { ...r.who } : null, lost: str(r.lost) ? r.lost : "",
      gone: Number.isInteger(r.gone) && r.gone > 0 ? r.gone : 0, serverFlags: r.serverFlags.slice(), swapped: r.swapped, take: r.take,
      skills: r.skills.map((s) => ({ skillId: s.skillId, take: s.take, ceo: s.ceo })), dropped: Number.isInteger(r.dropped) && r.dropped > 0 ? r.dropped : 0 });
  }
  if (STAFFING_SLOTS.some((slot) => rows.filter((x) => x.key === `slot:${slot}`).length !== 1)) return { draft: null, stale: false };
  return { draft: { basis, rows }, stale: false };
}

function staffingDraftSection(id, view, env) {
  const read = staffingDraftRead(id, view);
  let draft = read.draft || staffingDraftFrom(view, env);
  let stale = read.stale;
  const host = el("section", { class: "section st-draft", "data-st": "draft" });
  const changed = new Set(Array.isArray(view.changed_cards) ? view.changed_cards : []);
  const changedIds = new Set((view.sent && Array.isArray(view.sent.cards) ? view.sent.cards : []).filter((c) => c && changed.has(c.alias)).map((c) => c.profile_id));
  const save = () => store.set(STAFFING_DRAFT_KEY + id, draft);
  // after any change: a row VBear flags anew (its flags are not what they were) is not ticked; the person's own tick of a
  // row already flagged holds (要不要採用由你決定); nothing is ticked by a change in another row
  const flagsNow = (r) => staffingDraftFlags(r, draft.rows, env).join(",");
  const change = (fn) => {
    const before = new Map(draft.rows.map((r) => [r, flagsNow(r)]));
    fn();
    for (const r of draft.rows) { const f = flagsNow(r); if (f && f !== before.get(r)) r.take = false; }
    save();
    paint();
  };
  const placeLabel = (r) => (r.kind === "slot" ? STAFFING_SLOT_LABEL[r.place] : `幕僚：${staffingPositionText(r.place)}`);
  const cards = [...env.byId.values()];

  function swapSelect(r) {
    const fit = r.kind === "slot" ? STAFFING_SLOT_FIT[r.place] : [r.place];
    const pos = (p) => cardPosition({ position: p.position });
    const sorted = [...cards].sort((a, b) => ((fit.includes(pos(a)) ? 0 : 1) - (fit.includes(pos(b)) ? 0 : 1))
      || ((a.enabled === false ? 1 : 0) - (b.enabled === false ? 1 : 0)) || String(a.name || "").localeCompare(String(b.name || "")) || a.id.localeCompare(b.id));
    const tool = (p) => (p.model && typeof p.model.tool === "string" ? p.model.tool : "");
    const sel = el("select", { class: "st-swap", "data-st": "swap", "aria-label": `換人：${placeLabel(r)}` },
      el("option", { value: "" }, "（空著）"),
      sorted.map((p) => el("option", { value: `card:${p.id}` }, `${p.name || p.id}（${staffingPositionText(pos(p))}・${CARD_TOOL_SHORT[tool(p)] || tool(p) || "未知工具"}`
        + `${p.enabled === false ? "・停用中" : ""}）`)),
      [...env.news.values()].map((n) => el("option", { value: `new:${n.ref}` }, `新卡「${n.name}」（建議新建）`)));
    sel.value = r.who ? (r.who.type === "card" ? `card:${r.who.profileId}` : `new:${r.who.ref}`) : "";
    sel.addEventListener("change", () => change(() => {
      const v = sel.value;
      r.swapped = true;
      r.serverFlags = [];
      r.lost = "";
      if (!v) { r.who = null; r.skills = []; r.dropped = 0; r.take = false; return; }
      r.who = v.startsWith("card:") ? { type: "card", profileId: v.slice(5) } : { type: "new", ref: v.slice(4) };
      const w = staffingDraftWho(r.who, env);
      const before = r.skills.length;
      r.skills = r.skills.filter((s) => { const sk = env.skillById.get(s.skillId); return sk && skillCompatible(sk, w.tool); });
      r.dropped = before - r.skills.length;
      r.take = !staffingDraftFlags(r, draft.rows, env).length;
    }));
    return sel;
  }

  function rowNode(r) {
    const w = staffingDraftWho(r.who, env);
    const flags = staffingDraftFlags(r, draft.rows, env);
    const take = el("input", { type: "checkbox", "data-st": "take", disabled: !w || !w.found });
    take.checked = r.take && Boolean(w && w.found);
    take.addEventListener("change", () => change(() => { r.take = take.checked; }));
    const skills = r.skills.map((s) => {
      const sk = env.skillById.get(s.skillId);
      const equipped = Boolean(w && w.equipped.includes(s.skillId));
      const box = el("input", { type: "checkbox", "data-st": "draft-skill", "data-skill": s.skillId, disabled: equipped });
      box.checked = s.take && !equipped;
      box.addEventListener("change", () => change(() => { s.take = box.checked; }));
      return el("li", null, el("label", { class: "mt-check" }, box, el("span", null, sk ? String(sk.name || sk.skill_id) : STAFFING_NOT_FOUND)),
        " ", s.ceo ? badge("CEO 建議", "b-info") : badge("你加的", "b-mute"), equipped ? [" ", badge("已插上", "b-mute", STAFFING_FLAG_TEXT.already_equipped)] : null);
    });
    let addSkill = null;
    if (w && w.found) {
      const have = new Set(r.skills.map((s) => s.skillId).concat(w.equipped));
      const offer = skillPickPlan(env.skills, w.tool).listed.map((e) => e.skill).filter((s) => !have.has(s.skill_id));
      if (offer.length) {
        addSkill = el("select", { class: "st-add-skill", "data-st": "add-skill", "aria-label": `加一張技能：${placeLabel(r)}` },
          el("option", { value: "" }, "（加一張這張卡讀得到的技能）"), offer.map((s) => el("option", { value: s.skill_id }, `${s.name}（${CARD_TOOL_SHORT[s.tool] || s.tool}）`)));
        addSkill.addEventListener("change", () => { if (addSkill.value) change(() => { r.skills.push({ skillId: addSkill.value, take: true, ceo: false }); }); });
      }
    }
    return el("li", { class: "card st-draft-row", "data-st": "draft-row", "data-key": r.key },
      el("div", { class: "row" },
        el("label", { class: "mt-check" }, take, el("strong", null, `${placeLabel(r)}：${w ? w.text : "空著"}`)),
        flags.map((f) => el("span", { "data-st": "draft-flag" }, badge(staffingFlagText(f), "b-warn")))),
      r.lost ? el("p", { class: "small muted" }, `CEO 提的卡找不到了（${r.lost}）`) : null,
      w && w.found && r.who.type === "card" && changedIds.has(r.who.profileId) ? el("p", { class: "small muted" }, "這張卡在組隊會議之後改過。") : null,
      r.swapped && w && w.found ? el("p", { class: "small muted" }, STAFFING_SWAP_NOTE) : null,
      r.dropped ? el("p", { class: "small" }, `拿掉了 ${r.dropped} 張這張卡讀不到的技能。`) : null,
      r.gone ? el("p", { class: "small muted" }, `CEO 建議的技能有 ${r.gone} 張在技能庫找不到，沒有放進草稿。`) : null,
      skills.length ? el("ul", { class: "st-draft-skills" }, skills) : null,
      el("div", { class: "row" }, swapSelect(r), addSkill,
        el("button", { class: "btn small", type: "button", "data-st": "remove", on: { click: () => change(() => {
          if (r.kind === "staff") draft.rows = draft.rows.filter((x) => x !== r);
          else { r.who = null; r.skills = []; r.take = false; r.swapped = true; r.dropped = 0; r.serverFlags = []; r.lost = ""; }
        }) } }, r.kind === "staff" ? "拿掉這位幕僚" : "拿掉（空著）")));
  }

  function paint() {
    const taken = draft.rows.filter((r) => r.take);
    const inserts = taken.reduce((n, r) => {
      const w = staffingDraftWho(r.who, env);
      return n + r.skills.filter((s) => s.take && !(w && w.equipped.includes(s.skillId))).length;
    }, 0);
    const free = STAFFING_STAFF_POSITIONS.filter((p) => !draft.rows.some((r) => r.key === `staff:${p}`));
    const addStaff = free.length ? el("select", { "data-st": "add-staff", "aria-label": "加一位開會時找的幕僚" },
      el("option", { value: "" }, "（加一位幕僚）"), free.map((p) => el("option", { value: p }, staffingPositionText(p)))) : null;
    if (addStaff) addStaff.addEventListener("change", () => { const p = addStaff.value; if (p) change(() => {
      draft.rows.push({ key: `staff:${p}`, kind: "staff", place: p, who: null, lost: "", gone: 0, serverFlags: [], swapped: true, take: false, skills: [], dropped: 0 });
    }); });
    setKids(host,
      sectionHead("改成你要的樣子（草稿）", STAFFING_DRAFT_NOTE,
        el("button", { class: "btn small", type: "button", "data-st": "draft-reset", on: { click: () => {
          store.set(STAFFING_DRAFT_KEY + id, null);
          draft = staffingDraftFrom(view, env);
          stale = false;
          paint();
        } } }, "回到 CEO 的提案")),
      stale ? notice("info", "CEO 重新提案過，草稿已改回新的提案。") : null,
      el("p", { class: "small", "data-st": "draft-sum", role: "status" }, `草稿：要採用 ${taken.length} 列，要插 ${inserts} 張技能（不含已插上的）。插上技能只是紀錄，不會安裝或下載。`),
      el("ul", { class: "st-draft-rows" }, draft.rows.map(rowNode)),
      addStaff ? el("div", { class: "row" }, addStaff) : null);
    if (adoptHost) setKids(adoptHost, env.adopt(draft, save));
  }
  const adoptHost = typeof env.adopt === "function" ? el("div", { "data-st": "adopt-host" }) : null;
  paint();
  return adoptHost ? [host, adoptHost] : host;
}

// ---- adopting the draft, one step at a time (P35-4) ----
// What adopting the draft still asks of the person, read from the cards, the task card's flow and this browser as they
// are now, in a fixed order: 啟用 → 建新卡 → 插技能 → 帶到隊伍, then the meeting (it may be skipped) and the record.
// Each step is a button the person presses and goes through an endpoint that already exists; VBear does none of it by
// itself, and a step waits for the ones before it. The team is put on the task card's board unsaved, so flows.json is
// written only by 建立隊伍 or 儲存隊伍 there. The cards made in the wizard are kept in this browser (staffing.made.<id>).
const STAFFING_MADE_KEY = "staffing.made.";
const CARD_SKILLS_MAX = 200;   // vbear/agent_profiles.py MAX_SKILLS_PER_PROFILE; a test keeps them equal
const STAFFING_ADOPTED_SKILLS_MAX = 40;   // vbear/staffing.py ADOPTED_SKILLS_MAX
const STAFFING_ADOPT_STEPS = [["enable", "啟用"], ["create", "建新卡"], ["skills", "插技能"], ["team", "帶到隊伍"], ["meeting", "帶去開會"], ["record", "記下"]];
const STAFFING_ADOPT_NOTE = "每一步都要你自己按，VBear 不會自己做；順序固定：啟用 → 建新卡 → 插技能 → 帶到隊伍，前一步做完才能做下一步。"
  + "插上技能只是紀錄，不會安裝或下載。";

function staffingMadeRead(id) {
  const raw = store.get(STAFFING_MADE_KEY + id, null);
  const out = {};
  if (raw && typeof raw === "object" && !Array.isArray(raw)) {
    for (const [ref, cid] of Object.entries(raw)) if (/^N[1-3]$/.test(ref) && typeof cid === "string" && cid) out[ref] = cid;
  }
  return out;
}
// The skills a row adopts: those ticked in the draft and, for a new card, those the CEO gave it, by their ids today.
function staffingAdoptSkills(r, env) {
  const ids = r.skills.filter((s) => s.take).map((s) => s.skillId);
  const n = r.who && r.who.type === "new" ? env.news.get(r.who.ref) : null;
  for (const x of staffingList(n, "skills")) {   // { skill (an alias), why, flags }, as the server keeps them
    const sk = env.names.skill(x.skill);
    if (sk.found && !ids.includes(sk.skillId)) ids.push(sk.skillId);
  }
  return [...new Set(ids)];
}
// env: the draft's env, with did (the steps done from this page) and sentOff (the cards that were disabled at the meeting).
// flow: the task card's flow, null when it has none, undefined when it could not be read.
function staffingAdoptPlan(draft, env, flow) {
  const rows = [];
  let lost = 0;
  for (const r of draft.rows) {
    if (!r.take) continue;
    const w = staffingDraftWho(r.who, env);
    if (!w || !w.found) { lost += 1; continue; }
    rows.push({ r, w, card: r.who.type === "card" || w.made ? env.byId.get(w.key) : null });
  }
  const did = env.did || new Set();
  const equipped = (p) => (Array.isArray(p.equipped_skill_ids) ? p.equipped_skill_ids.filter((x) => typeof x === "string") : []);
  // 1. 啟用
  const cardIds = [...new Set(rows.filter((x) => x.card).map((x) => x.card.id))];
  const off = cardIds.map((cid) => env.byId.get(cid)).filter((p) => p.enabled === false);
  const wasOff = cardIds.some((cid) => env.sentOff && env.sentOff.has(cid));
  const enable = { todo: off, state: off.length ? "todo" : wasOff || did.has("enable") ? "done" : "none" };
  // 2. 建新卡
  const made = env.made || {};
  const refs = [...new Set(rows.filter((x) => x.r.who.type === "new").map((x) => x.r.who.ref))];
  const create = { todo: refs.filter((ref) => !(cardHas(made, ref) && env.byId.has(made[ref])))
    .map((ref) => ({ ref, newCard: env.news.get(ref), gone: cardHas(made, ref) })), done: refs.filter((ref) => cardHas(made, ref) && env.byId.has(made[ref])) };
  create.state = create.todo.length ? "todo" : refs.length ? "done" : "none";
  // 3. 插技能: per card, the ticked skills it does not have yet; one it cannot read, or not in the library, is said, not inserted
  const want = new Map();
  for (const x of rows) {
    if (!x.card) continue;
    const list = want.get(x.card.id) || [];
    for (const s of x.r.skills) if (s.take && !list.includes(s.skillId)) list.push(s.skillId);
    want.set(x.card.id, list);
  }
  const cards = [];
  let on = 0;
  for (const [cid, list] of want) {
    const p = env.byId.get(cid);
    const before = equipped(p);
    const tool = p.model && typeof p.model.tool === "string" ? p.model.tool : "";
    const add = [];
    const skipped = [];
    for (const sid of list) {
      if (before.includes(sid)) { on += 1; continue; }
      const sk = env.skillById.get(sid);
      if (sk && skillCompatible(sk, tool)) add.push(sid); else skipped.push(sid);
    }
    if (add.length || skipped.length) cards.push({ card: p, before, add, skipped, over: before.length + add.length > CARD_SKILLS_MAX });
  }
  const skills = { cards, todo: cards.filter((c) => c.add.length) };
  skills.state = skills.todo.length ? "todo" : on ? "done" : "none";
  // 4. 帶到隊伍: done when the task card's flow has each place's card, put there as the card is now
  const slotRows = rows.filter((x) => x.r.kind === "slot");
  const slots = {};
  for (const x of slotRows) if (x.card) slots[x.r.place] = x.card.id;
  const inFlow = flow ? teamSlotsFromRoles(flow.roles) : null;
  const placed = slotRows.filter((x) => x.card && inFlow && inFlow[x.r.place] && inFlow[x.r.place].profile_id === x.card.id
    && teamCardState(inFlow[x.r.place], [...env.byId.values()]).state === "same");
  const team = { slots, unread: flow === undefined, missing: slotRows.length - placed.length,
    state: !slotRows.length ? "none" : placed.length === slotRows.length ? "done" : "todo" };
  // 5. 帶去開會 (it may be skipped): the staff the draft takes
  const staff = [...new Set(rows.filter((x) => x.r.kind === "staff" && x.card).map((x) => x.card.id))];
  // 6. 記下: the rows as they are on the cards now; a skill counts once it is on the card (for a card the wizard made, the
  // skills the CEO gave the new card too, as the wizard ticked them first)
  const adopted = rows.filter((x) => x.card).map((x) => {
    const ids = staffingAdoptSkills(x.r, env);
    return { kind: x.r.kind, place: x.r.place, profile_id: x.card.id, new_ref: x.r.who.type === "new" ? x.r.who.ref : "",
      skill_ids: ids.filter((sid) => equipped(x.card).includes(sid)) };
  });
  const first = [enable, create, skills, team].findIndex((x) => x.state === "todo");
  let why = "記下採用只是紀錄：不會再改角色卡、技能或隊伍。";
  if (first >= 0) why = `先做完第 ${first + 1} 步，才能記下採用。`;
  else if (!adopted.length) why = "草稿沒有勾任何一列，沒有東西可以採用；不採用的話，按「記下：不採用」。";
  else if (adopted.some((x) => x.skill_ids.length > STAFFING_ADOPTED_SKILLS_MAX)) why = `一列最多記 ${STAFFING_ADOPTED_SKILLS_MAX} 張技能，請在草稿少勾幾張。`;
  const canAdopt = first < 0 && adopted.length > 0 && !adopted.some((x) => x.skill_ids.length > STAFFING_ADOPTED_SKILLS_MAX);
  return { rows, lost, enable, create, skills, team, staff, adopted, first, canAdopt, why };
}

// acts: { enable(p), create(ref), insert(c), team(slots), meetingHref(staff), adopt(note, rows), dismiss(note), canWizard, taskFound }
function staffingAdoptSection(plan, acts) {
  const name = (p) => String(p.name || p.id);
  const gate = (i) => plan.first >= 0 && plan.first < i;
  const stateText = (i, x) => (x.state === "done" ? "已完成" : x.state === "none" ? "沒有要做的"
    : plan.first === i ? "輪到這一步" : `先做完第 ${plan.first + 1} 步`);
  const btn = (attrs, label, click, primary) => el("button", { class: primary ? "btn small primary" : "btn small", type: "button", ...attrs,
    on: { click } }, label);
  const bodies = {
    enable: () => [plan.enable.todo.length
      ? el("ul", { class: "small" }, plan.enable.todo.map((p) => el("li", null,
        btn({ "data-st": "do-enable", "data-profile": p.id }, `啟用「${name(p)}」`, () => acts.enable(p)))))
      : el("p", { class: "small muted" }, plan.enable.state === "done" ? "草稿要用的卡都啟用了。" : "草稿要用的卡都是啟用的。"),
    el("p", { class: "small muted" }, "啟用只會打開角色卡的開關，不會改別的。")],
    create: () => [plan.create.todo.length ? el("ul", { class: "small" }, plan.create.todo.map((t) => el("li", null,
      btn({ "data-st": "do-create", "data-ref": t.ref, disabled: gate(1) || !acts.canWizard }, `用精靈建「${t.newCard ? t.newCard.name : t.ref}」`, () => acts.create(t.ref)),
      t.gone ? el("span", { class: "small muted" }, " 用精靈建的卡已不在（可能刪掉了），可以再建一次。") : null))) : null,
    plan.create.done.length ? el("p", { class: "small muted" }, `已用精靈建好：${plan.create.done.join("、")}。`) : null,
    plan.create.todo.length ? el("p", { class: "small muted" }, acts.canWizard
      ? "會打開建角色卡的精靈，照 CEO 的提案先填好；都可以改，按「建立」才會存。" : "讀不到建卡用的清單，現在不能打開精靈；請重新整理這一頁。") : null],
    skills: () => [plan.skills.cards.length ? el("ul", { class: "small" }, plan.skills.cards.map((c) => el("li", null,
      `${name(c.card)}：要插 ${c.add.length} 張`, c.skipped.length ? `；${c.skipped.length} 張這張卡讀不到或不在技能庫，不插` : "", "。",
      c.over ? el("span", { class: "small" }, ` 插上後會有 ${c.before.length + c.add.length} 張，角色卡最多 ${CARD_SKILLS_MAX} 張；請先到角色卡拿掉一些，或在草稿少勾幾張。`) : null,
      c.add.length ? [" ", btn({ "data-st": "do-insert", "data-profile": c.card.id, disabled: gate(2) || c.over }, `插上（${name(c.card)}）`, () => acts.insert(c))] : null)))
      : el("p", { class: "small muted" }, plan.skills.state === "done" ? "草稿勾的技能都已經插在卡上。" : "草稿沒有要插的技能。"),
    el("p", { class: "small muted" }, "按下去會先給你看插上前後的技能清單，確定了才會存。")],
    team: () => [plan.team.state === "todo" ? el("p", { class: "small" }, plan.team.unread ? "讀不到任務卡的隊伍，不知道放好了沒有；請重新整理這一頁。"
      : `還有 ${plan.team.missing} 個位置不在任務卡的隊伍上，或卡在放上去以後改過。`) : null,
    plan.team.state === "done" ? el("p", { class: "small muted" }, "任務卡的隊伍已經是草稿的樣子。") : null,
    plan.team.state === "todo" ? btn({ "data-st": "do-team", disabled: gate(3) || !acts.taskFound }, "帶到任務卡的隊伍", () => acts.team(plan.team.slots)) : null,
    plan.team.state === "todo" && !acts.taskFound ? el("p", { class: "small" }, "找不到這張任務卡，不能帶過去。") : null,
    el("p", { class: "small muted" }, "會打開任務卡，把草稿的位置先放上隊伍，還沒儲存；要你在那裡按「建立隊伍」或「儲存隊伍」才會寫入。提案沒有提到的位置維持原樣。")],
    meeting: () => [plan.staff.length && plan.first < 0
      ? el("a", { class: "btn small", "data-st": "do-meeting", href: acts.meetingHref(plan.staff) }, "帶這幾位幕僚去開會")
      : null,
    el("p", { class: "small muted" }, plan.staff.length ? "只會在開會頁勾好發言者；要不要開、找誰，由你決定，按「預覽」才會送出。這一步可以跳過。"
      : "草稿沒有要找的幕僚。")],
    record: () => {
      const note = el("textarea", { rows: "2", maxlength: "500", "data-st": "adopt-note", "aria-label": "備註（選填）", placeholder: "備註（選填，最多 500 字）" });
      return [note,
        el("div", { class: "row" },
          btn({ "data-st": "do-adopt", disabled: !plan.canAdopt }, "記下：採用", () => acts.adopt(note.value.trim(), plan.adopted), true),
          btn({ "data-st": "do-dismiss" }, "記下：不採用", () => acts.dismiss(note.value.trim()))),
        el("p", { class: "small", "data-st": "adopt-why", role: "status" }, plan.canAdopt ? `會記下 ${plan.adopted.length} 列。${plan.why}` : plan.why)];
    },
  };
  const states = {
    enable: stateText(0, plan.enable), create: stateText(1, plan.create), skills: stateText(2, plan.skills), team: stateText(3, plan.team),
    meeting: !plan.staff.length ? "沒有要做的" : plan.first >= 0 ? `先做完第 ${plan.first + 1} 步` : "可以做，也可以跳過",
    record: plan.canAdopt ? "輪到這一步" : plan.first >= 0 ? `先做完第 ${plan.first + 1} 步` : "沒有可以採用的列",
  };
  return el("section", { class: "section st-adopt", "data-st": "adopt" },
    sectionHead("照草稿採用", STAFFING_ADOPT_NOTE),
    plan.lost ? el("p", { class: "small" }, `有 ${plan.lost} 列勾了，但卡找不到，不算進採用。`) : null,
    el("ol", { class: "st-adopt-steps" }, STAFFING_ADOPT_STEPS.map(([key, label], i) => el("li", { class: "card pad st-adopt-step", "data-st": "adopt-step", "data-step": key },
      el("div", { class: "row" }, el("strong", null, `第 ${i + 1} 步：${label}`), el("span", { class: "small muted", "data-st": "step-state" }, states[key])),
      bodies[key]()))));
}

// ---- the page ----

async function viewStaffingDetail(token, id) {
  let cur;
  try { cur = await api.get(`/api/staffing/${encodeURIComponent(id)}`); }
  catch (e) {
    setKids(claim(token), crumbs([["組隊會議", "#/staffing"], ["找不到"]]), notice("bad", e.status === 404 ? e.message : "讀不到這份組隊紀錄：" + e.message));
    return;
  }
  const [tasksRes, profilesRes, catalog, flowsRes] = await Promise.all([api.get("/api/tasks").catch(() => null),
    api.get("/api/agent-profiles").catch(() => null), api.get("/api/agent-builder/catalog").catch(() => null),
    api.get("/api/flows").catch(() => null)]);
  const tasksList = tasksRes && Array.isArray(tasksRes.tasks) ? tasksRes.tasks.filter((t) => t && typeof t.id === "string") : [];
  let profiles = profilesRes && Array.isArray(profilesRes.profiles) ? profilesRes.profiles : [];
  let flows = flowsRes && Array.isArray(flowsRes.flows) ? flowsRes.flows : null;   // null: could not be read
  const skills = catalog && Array.isArray(catalog.skills) ? catalog.skills : [];
  const categories = catalog && Array.isArray(catalog.skill_categories) ? catalog.skill_categories : [];
  const main = claim(token);
  const root = el("div", { class: "mt-detail" });
  const reload = async () => {
    try { cur = await api.get(`/api/staffing/${encodeURIComponent(id)}`); } catch (e) { toast("讀不到這份組隊紀錄：" + e.message); return; }
    if (token === seq) draw();
  };
  const act = async (fn) => {
    try { const res = await fn(); if (res && typeof res === "object" && res.id === id) cur = res; if (token === seq) draw(); }
    catch (e) { toast(e.message); await reload(); }
  };
  // P35-4: adopting the draft. Each step is the person's press, through an endpoint that already exists; afterwards the
  // cards and the flows are read again and the list is drawn from them.
  const did = new Set();
  const made = staffingMadeRead(id);
  let stepBusy = false;
  const refreshCards = async () => {
    const [p, f] = await Promise.all([api.get("/api/agent-profiles").catch(() => null), api.get("/api/flows").catch(() => null)]);
    if (p && Array.isArray(p.profiles)) profiles = p.profiles;
    flows = f && Array.isArray(f.flows) ? f.flows : null;
  };
  const stepDone = async (key, fn) => {
    if (stepBusy) return;
    stepBusy = true;
    try { if ((await fn()) !== false) did.add(key); } catch (e) { toast(e.message); }
    stepBusy = false;
    await refreshCards();
    if (token === seq) draw();
  };
  const skillName = (sid) => { const sk = skills.find((x) => x && x.skill_id === sid); return sk ? String(sk.name || sid) : `${STAFFING_NOT_FOUND}（${sid}）`; };
  const recorded = (res) => {
    store.set(STAFFING_DRAFT_KEY + id, null);
    store.set(STAFFING_MADE_KEY + id, null);
    return res;
  };
  function adoptActs(view, env, draft, keep) {
    const task = tasksList.find((t) => t.id === view.task_id);
    return {
      canWizard: Boolean(catalog && Array.isArray(catalog.tools)),
      taskFound: Boolean(task),
      enable: (p) => { keep(); stepDone("enable", () => api.post(`/api/agent-profiles/${encodeURIComponent(p.id)}`, { enabled: true })); },
      create: (ref) => {
        keep();
        const n = env.news.get(ref);
        if (!n) return;
        // the wizard ticks what it can of these: the skills of every taken row of this new card, and the CEO's for it
        const skillIds = [...new Set(draft.rows.filter((r) => r.take && r.who && r.who.type === "new" && r.who.ref === ref)
          .flatMap((r) => staffingAdoptSkills(r, env)))];
        openCardWizard({ catalog, profiles, draft: { name: n.name, position: n.position, tool: n.tool, modelId: n.model_alias, skillIds },
          onSaved: async (saved) => {
            if (saved && typeof saved.id === "string") { made[ref] = saved.id; store.set(STAFFING_MADE_KEY + id, made); did.add("create"); }
            await refreshCards();
            if (token === seq) draw();
          } });
      },
      insert: (c) => {
        keep();
        stepDone("skills", async () => {
          const line = (words) => el("span", { class: "st-confirm-line" }, words);
          const names = (ids) => (ids.length ? ids.map(skillName).join("、") : "（沒有）");
          const after = c.before.concat(c.add);
          const ok = await confirmInPage(`插上技能：${c.card.name || c.card.id}`, [
            line(`插上前（${c.before.length} 張）：${names(c.before)}`), line(`插上後（${after.length} 張）：${names(after)}`),
            line(`新增：${names(c.add)}`), c.skipped.length ? line(`有 ${c.skipped.length} 張這張卡讀不到或不在技能庫，不插：${names(c.skipped)}`) : null,
            line("插上技能只是紀錄，不會安裝或下載。")], "插上");
          if (!ok) return false;
          return api.post(`/api/agent-profiles/${encodeURIComponent(c.card.id)}`, { equipped_skill_ids: after });
        });
      },
      team: (slots) => {
        keep();
        setTeamPreset({ taskId: view.task_id, from: id, slots });
        location.hash = `#/workbench?task=${encodeURIComponent(view.task_id)}`;
      },
      meetingHref: (staff) => `#/meetings?task=${encodeURIComponent(view.task_id)}&speakers=${encodeURIComponent(staff.join(","))}`,
      adopt: (note, rows) => act(async () => recorded(await api.post(`/api/staffing/${encodeURIComponent(id)}/chairman`, { decision: "adopt", note, adopted: { rows } }))),
      dismiss: (note) => act(async () => recorded(await api.post(`/api/staffing/${encodeURIComponent(id)}/chairman`, { decision: "dismiss", note }))),
    };
  }

  function seatCard(seat, ctx) {
    const t = seat.turn;
    const kept = staffingKept(t);
    const body = [];
    if (kept && t.kind === "opinion") body.push(staffingOpinionNodes(kept, ctx), staffingNotesNode(t.output, ctx.names));
    else if (kept && t.kind === "proposal") body.push(el("p", { class: "small muted" }, "CEO 的組隊提案在下面。"));
    else if (t && t.state === "queued") body.push(el("p", { class: "small muted" }, "還沒輪到。"));
    else if (t && t.state === "running") body.push(el("p", { class: "small muted" }, t.kind === "proposal" ? "正在整理意見…" : "正在發言…"));
    else if (t) {
      const why = meetingErrorText(t.error_code);
      body.push(el("p", { class: "small", "data-st": "reason" }, `${STAFFING_BUBBLES.includes(seat.bubble) ? seat.bubble : MEETING_UNKNOWN}${why ? "：" + why : ""}`));
    } else body.push(el("p", { class: "small muted" }, "紀錄裡沒有這一位的發言。"));
    const chair = cur.chairman && typeof cur.chairman === "object" ? cur.chairman.state : "";
    const decided = chair === "adopted" || chair === "dismissed";
    const canRetry = t && Array.isArray(cur.retryable) && cur.retryable.includes(t.seq) && cur.status !== "running";
    const retry = canRetry && !decided
      ? el("button", { class: "btn small", type: "button", "data-st": "retry", on: { click: () => retryOf(t.seq) } }, "重試這一位（先給你看預覽）")
      : canRetry ? el("p", { class: "small muted" }, "董事長已經記下採用與否，這份組隊會議不能再重試；要重新討論，請開新的組隊會議。") : null;
    return el("article", { class: "card mt-card", "data-st": "seat", "data-profile": seat.profileId },
      el("div", { class: "mt-card-head" }, officeSprite(seat.species, seat.camp, 2),
        el("div", { style: "min-width:0" }, el("strong", null, seat.name),
          el("div", { class: "small muted" }, `${seat.positionLabel}・${TOOL[seat.tool] || seat.tool || "未知工具"}・模型 ${seat.model || "未知"}`)),
        seat.proxy ? badge("代發言", "b-info", "這張卡的工具不是 Claude Code，由 Claude Code 照這個職位的指示代為發言") : null,
        el("span", { class: "mt-bubble" }, seat.bubble)),
      body, meetingEvidenceNode(t), retry);
  }

  async function retryOf(seqNo) {
    let pv;
    try { pv = await api.post(`/api/staffing/${encodeURIComponent(id)}/retry-preview`, { seq: seqNo }); }
    catch (e) { toast(e.message); return; }
    meetingPreviewDialog(pv, { title: "重試前的預覽", startLabel: "重試", facts: staffingPreviewFacts(pv),
      onRecheck: () => retryOf(seqNo),
      onStart: async (previewId) => { await act(() => api.post(`/api/staffing/${encodeURIComponent(id)}/retry`, { preview_id: previewId })); } });
  }

  // adoptable: the list of steps is on the page, and it holds the buttons; otherwise a record that is not running and not
  // decided can only be dismissed here (the server takes an adoption only of a finished proposal)
  function chairmanBlock(adoptable) {
    const c = cur.chairman && typeof cur.chairman === "object" ? cur.chairman : { state: "pending" };
    const head = c.state === "adopted" ? "董事長記下：採用" : c.state === "dismissed" ? "董事長記下：不採用"
      : cur.status === "running" ? "組隊會議進行中" : "還沒有記下採用或不採用";
    const rows = c.state === "adopted" && c.adopted && Array.isArray(c.adopted.rows) ? c.adopted.rows.filter((r) => r && typeof r === "object") : [];
    const byId = new Map(profiles.filter((p) => p && typeof p.id === "string").map((p) => [p.id, p]));
    const placeOf = (r) => (r.kind === "slot" && cardHas(STAFFING_SLOT_LABEL, r.place) ? STAFFING_SLOT_LABEL[r.place] : `幕僚：${staffingPositionText(r.place)}`);
    const rowText = (r) => {
      const p = byId.get(r.profile_id);
      const n = Array.isArray(r.skill_ids) ? r.skill_ids.length : 0;
      return `${placeOf(r)}：${p ? String(p.name || p.id) : `${STAFFING_NOT_FOUND}（${r.profile_id}）`}${r.new_ref ? `（由 CEO 建議的新卡 ${r.new_ref} 建立）` : ""}`
        + (n ? `・插 ${n} 張技能` : "");
    };
    let dismiss = null;
    if (!adoptable && c.state === "pending" && cur.status !== "running") {
      const note = el("textarea", { rows: "2", maxlength: "500", "data-st": "chairman-note", "aria-label": "備註（選填）", placeholder: "備註（選填，最多 500 字）" });
      dismiss = [el("p", { class: "small" }, "CEO 沒有完成提案，這份組隊紀錄不能採用；可以記下不採用。"), note,
        el("div", { class: "row" }, el("button", { class: "btn small", type: "button", "data-st": "do-dismiss", on: { click: () => act(async () =>
          recorded(await api.post(`/api/staffing/${encodeURIComponent(id)}/chairman`, { decision: "dismiss", note: note.value.trim() }))) } }, "記下：不採用"))];
    }
    return el("section", { class: "section mt-chairman", "data-st": "chairman" }, sectionHead("董事長桌", MEETING_CHAIRMAN_NOTE),
      el("div", { class: "card pad" }, el("p", null, el("strong", null, head)),
        c.note ? el("p", { class: "small" }, `備註：${c.note}`) : null,
        c.at ? el("p", { class: "small muted" }, `${fmtTime(c.at)}・${MEETING_CHAIRMAN_NOTE}`) : null,
        rows.length ? el("ul", { class: "small", "data-st": "adopted-rows" }, rows.map((r) => el("li", null, rowText(r)))) : null,
        dismiss,
        el("p", { class: "small muted" }, "記下採用與否只是紀錄，不會建卡、插技能或排隊伍。")));
  }

  function draw() {
    const names = staffingNames(cur, profiles, skills);
    const ctx = { names, skills, categories };
    const seats = staffingSeats(cur);
    const title = staffingTaskTitle(cur.task_id, tasksList);
    const running = cur.status === "running";
    const limits = cur.limits && typeof cur.limits === "object" ? cur.limits : {};
    const proposal = staffingProposalOf(cur);
    const last = Array.isArray(cur.turns) && cur.turns.length ? cur.turns[cur.turns.length - 1] : null;
    const changed = Array.isArray(cur.changed_cards) ? cur.changed_cards : null;
    const suggested = Array.isArray(cur.suggested) ? cur.suggested.filter((x) => x && typeof x.profile_id === "string") : [];
    const spoke = new Set((Array.isArray(cur.participants) ? cur.participants : []).map((p) => p && p.profile_id));
    const clock = meetingClockText(cur.clock);
    const adoptable = Boolean(proposal && cur.status === "ready" && cur.chairman && cur.chairman.state === "pending");
    const sentOff = new Set((cur.sent && Array.isArray(cur.sent.cards) ? cur.sent.cards : []).filter((c) => c && c.enabled === false).map((c) => c.profile_id));
    const flow = flows === null ? undefined : flows.find((f) => f && f.task_id === cur.task_id) || null;
    const env = { byId: names.byId, news: names.news, skills, skillById: names.skillById, names, made, did, sentOff };
    env.adopt = (draft, keep) => staffingAdoptSection(staffingAdoptPlan(draft, env, flow), adoptActs(cur, env, draft, keep));
    setKids(root,
      el("div", { class: "row" }, el("h1", null, `組隊會議：${title}`)),
      el("div", { class: "row small" }, staffingStatusBadge(cur.status),
        cur.high_risk === true ? badge("有高風險", "b-warn", "有發言者把風險標成「高」；這只是提醒") : null,
        el("span", { class: "muted" }, `組隊紀錄 ${cur.id}・${fmtTime(cur.created_at)}・花費 US$${cur.spent_usd}（估值）／這份組隊提案最多 US$${limits.total_usd}`),
        el("a", { href: `#/workbench?task=${encodeURIComponent(cur.task_id)}` }, `任務卡：${title}`)),
      clock ? el("p", { class: "small mt-clock", "data-mt": "clock", role: "status" }, clock) : null,
      el("p", { class: "small muted" }, MEETING_COST_NOTE),
      meetingMoneyWhyNode(),
      cur.high_risk === true ? notice("warn", "有發言者把風險標成「高」，請先看過再決定。這只是提醒，不會擋住採用。") : null,
      changed && changed.length ? el("div", { "data-st": "changed" }, notice("warn", `組隊會議之後，這些卡改過：${changed.map((a) => names.card(a).text).join("、")}。看提案時請以卡現在的樣子為準。`))
        : changed ? null : el("p", { class: "small muted", "data-st": "changed" }, "VBear 這次沒有比對卡片有沒有改過（不代表沒有改過）。"),
      cur.note ? el("p", { class: "small" }, `補充說明：${cur.note}`) : null,
      suggested.length ? el("details", { class: "small" }, el("summary", null, "VBear 建議的人選與理由（固定規則，不是 AI 判斷）"),
        el("ul", null, suggested.map((x) => el("li", null, `${(names.byId.get(x.profile_id) || {}).name || "（這張卡已不在）"}：${x.why}——`,
          spoke.has(x.profile_id) ? "這次有發言" : "這次沒有發言")))) : null,
      el("section", { class: "section" }, sectionHead("座位", "每一位各自發言一次，彼此看不到；頭上的字只來自組隊紀錄。"),
        el("div", { class: "mt-seats" }, seats.map((s) => meetingSeatNode(s))),
        el("div", { class: "mt-cards" }, seats.map((s) => seatCard(s, ctx)))),
      proposal ? el("section", { class: "section", "data-st": "proposal" },
        sectionHead("CEO 的組隊提案", "這只是建議：VBear 不會自己建卡、插技能或排隊伍。卡和技能是用代號寫的，這裡換成它們現在的名稱；找不到的寫「找不到」。"),
        staffingProposalNode(proposal, last.output, ctx)) : null,
      adoptable ? staffingDraftSection(id, cur, env) : null,
      chairmanBlock(adoptable),
      el("div", { class: "row" },
        running ? el("button", { class: "btn", type: "button", "data-mt": "cancel", on: { click: () => act(() => api.post(`/api/staffing/${encodeURIComponent(id)}/cancel`, {})) } },
          "取消這場組隊會議") : null,
        !running ? el("button", { class: "btn", type: "button", "data-mt": "delete", on: { click: async () => {
          if (!(await confirmInPage("刪除組隊紀錄", `確定要刪除「${title}」的這份組隊紀錄嗎？刪除後無法復原。`, "刪除"))) return;
          try { await api.del(`/api/staffing/${encodeURIComponent(id)}`); toast("組隊紀錄已刪除"); location.hash = "#/staffing"; }
          catch (e) { toast("刪除失敗：" + e.message); }
        } } }, "刪除這份組隊紀錄") : null));
  }
  draw();
  setKids(main, crumbs([["組隊會議", "#/staffing"], [staffingTaskTitle(cur.task_id, tasksList)]]), root);
  if (cur.status === "running") {
    staffingTick = async () => { if (cur.status === "running") await reload(); };
    activeViewCleanup = () => { staffingTick = null; };
  }
}

setTheme(store.get("theme", "auto"));
setInterval(() => { if (!document.hidden && !authLostShown && !authPending) { refreshTranslations(); pollRoleTranslations(); } }, 2500);
setInterval(() => { if (!document.hidden && !authLostShown && !authPending) refreshWaitingBar(); }, 30000);
// Coming back to this tab: refresh at once instead of waiting.
document.addEventListener("visibilitychange", () => { if (!document.hidden && liveTick && !authPending) liveTick(); });
// The skip link moves focus only; it must not become a route ("#main" is not a page).
function skipToMain(e) {
  if (e) e.preventDefault();
  const main = $main();
  main.focus({ preventScroll: true });
  main.scrollIntoView({ block: "start" });
}
document.querySelector("a.skip").addEventListener("click", skipToMain);
wireNavMenu();
window.addEventListener("hashchange", () => {
  if (authPending) return;   // bootstrap routes to the address as it is once the login code is traded
  if (location.hash === "#main" && routedHash !== null) {  // reached without the click handler
    history.replaceState(null, "", routedHash || location.pathname + location.search);
    skipToMain();
    return;
  }
  scrollTo(0, 0); route(); document.getElementById("main").focus({ preventScroll: true });
});
if (location.hash === "#main") history.replaceState(null, "", location.pathname + location.search);

// Opening VBear (launcher, app) lands here with #auth=<token> once; trade it
// for the HttpOnly session cookie and drop it from the address bar at once.
// The exchange comes first and the router waits for it: while the code is being traded the page has no session, so
// every other request (the translation poll, a nav click, a tab coming back to the front) is held back instead of
// meeting a 401 and putting up "open VBear" on a page that is about to log in. authPending is set before the first
// await, so no timer or event can run in between.
async function bootstrap() {
  const m = /^#auth=([A-Za-z0-9_-]{20,200})$/.exec(location.hash || "");
  if (m) {
    authPending = true;
    history.replaceState(null, "", location.pathname + location.search + "#/");
    try { await api.post("/api/auth", { token: m[1] }); }
    catch (_) { /* the first API call then shows how to open VBear */ }
    finally { authPending = false; }
  }
  route();
}
bootstrap();

// ---------- team templates (v0.19, P45-1) ----------
// 團隊範本 (ADR 0011): a set of ready-made employees, skills and routines. The person ticks the ones they want (from one template or several),
// looks at the preview, and presses 套用 (P45-2). This block reads GET /api/templates and asks POST /api/templates/preview, which only plans;
// the page itself writes nothing: 套用, 復原這次套用 (P45-2) and 存成團隊範本, 改名, 刪除 (P45-3) are presses of the person that the server
// answers, and nothing here makes a card, a skill or a routine by itself. Names and texts are set with textContent only (el() children).
const TPL_LINES = [
  "團隊範本是一組現成的員工、常用做法和定時工作。勾你要的，按「預覽並套用」看清楚再套用。",
  "套用不用 AI、不花錢。員工一律用「每件事先問我」，跑指令、改檔案照舊每次都問你；記憶和共用資料夾照你平常的設定；定時工作建好是關著的。",
  "每次套用都可以「復原這次套用」：只刪這次建的、你沒改過也沒用過的，改過或用過的會留著並告訴你。團隊範本不會改或刪你原本就有的東西。",
  "團隊範本只存在這台電腦，不會上傳，也不能匯出。",
];
const TPL_CEO_LINE = "要用幕僚長分配工作，還需要一位 CEO（到員工頁新增）。";
const TPL_PREVIEW_LINES = {
  safe: "員工一律用「每件事先問我」：跑指令、改檔案照舊每次都問你。團隊範本不會建出「完全交給他（有風險）」的員工。",
  memory: "記憶照你平常的設定（Claude Code 的員工帶記憶，Codex 的員工不帶，因為記憶會送到 OpenAI）；共用資料夾都關著。要改，到記憶頁或共用資料夾頁一位一位打開。",
  off: "定時工作建好是關著的，要你自己到定時工作頁打開。",
  free: "套用不用 AI、不花錢。之後跟員工聊天才會花錢，照你的每回合上限與花費上限。",
  codex: "Codex 的員工在 VBear 裡可以聊天；要在指令視窗用 Codex 只能用「完全交給他（有風險）」，團隊範本建的員工不會是「完全交給他（有風險）」。",
  notReady: "這個 AI 工具還沒準備好：員工會建好，但要先到開始設定登入才能聊天。",
  agy: "AGY 的員工預設不帶記憶（打開時要你同意，內容會送到 Google），這版也不能用共用資料夾；員工會用到你自己裝的 AGY 技能。要在指令視窗用 AGY 只能用「完全交給他（有風險）」，團隊範本建的員工不會是「完全交給他（有風險）」。",
  agyUnverified: "你的 AGY 還沒通過聊天驗證：員工會建好，但要先到聊天頁按「驗證聊天」（用你的 Google 方案）才能聊天。",
};
const TPL_TOOL_LABEL = { claude: "Claude Code", codex: "Codex", agy: "AGY" };
const TPL_KINDS = [["cards", "員工"], ["skills", "常用做法"], ["routines", "定時工作"]];
const TPL_ONE = { card: "員工", skill: "常用做法", routine: "定時工作" };
const TPL_STATE_TEXT = { done: "完成", partial: "建到一半停下了", interrupted: "中斷了", applying: "進行中" };
const TPL_INTERRUPTED = "這次套用中斷了，最後一個常用做法或定時工作可能已經建好但沒記到，復原不會刪它；請到常用做法頁、定時工作頁看看。";
const TPL_APPLIES_LIMIT = "只能復原最近 50 次套用；更早的東西照樣留著，要刪請到各自的頁面。";
const TPL_APPLIED_LINE = "定時工作都是關著的，要用的話到定時工作頁打開。不滿意的話，到頁面下面的套用紀錄按「復原這次套用」。";

function tplId(ref) { return `${ref.template}/${ref.key}`; }
function tplSelection() { return { cards: new Map(), skills: new Map(), routines: new Map() }; }
function tplCounts(sel) { return { cards: sel.cards.size, skills: sel.skills.size, routines: sel.routines.size }; }
function tplCountText(sel) {
  const c = tplCounts(sel);
  return `已勾：${c.cards} 位員工、${c.skills} 個常用做法、${c.routines} 件定時工作`;
}
// The request of the preview and (P45-2) of the apply: the same body. `name` and `to` are sent only when the person changed them.
function tplRequestBody(sel, opts) {
  const from = (r) => ({ template: r.from.template, key: r.from.key });
  const body = {
    tool: opts.tool,
    cards: Array.from(sel.cards.values()).map((c) => (c.name === undefined ? { from: from(c) } : { from: from(c), name: c.name })),
    skills: Array.from(sel.skills.values()).map((s) => ({ from: from(s) })),
    routines: Array.from(sel.routines.values()).map((r) => (r.to === undefined ? { from: from(r) } : { from: from(r), to: r.to })),
  };
  if (opts.confirm === true) body.confirm_warning = true;
  return body;
}
// Tick or untick one item. A routine that was handed to a card that is no longer ticked goes back to the template's own choice.
function tplSetPick(sel, kind, ref, on) {
  const id = tplId(ref);
  if (on) { if (!sel[kind].has(id)) sel[kind].set(id, { from: { template: ref.template, key: ref.key } }); return; }
  sel[kind].delete(id);
  if (kind === "cards") sel.routines.forEach((r) => { if (r.to && r.to.card && tplId(r.to.card) === id) delete r.to; });
}
function tplScheduleText(r) {
  const days = r.days.length === 7 ? "每天" : `每週${r.days.map((d) => ROUTINE_DAYS[d]).join("、")}`;
  return `${days}　${r.times.join("、")}`;
}
function tplModelText(card) { return card.claude_model ? `建議模型 ${card.claude_model}` : ""; }

// One team template as a block: its name, what it is for, and three rows of tick boxes. `ctx.sel` is the selection of the page; `ctx.boxes` collects
// the boxes so that one call of `ctx.sync()` can redraw their state and the line at the bottom.
function templatesBlock(template, ctx) {
  const sel = ctx.sel;
  const cardName = (key) => (template.cards.find((c) => c.key === key) || {}).name;
  const line = (kind, item) => {
    const ref = { template: template.id, key: item.key };
    const box = el("input", { type: "checkbox", "data-tpl-pick": kind, "data-tpl-template": template.id, "data-tpl-key": item.key,
      "aria-label": `勾選${item.name}`,
      on: { change: (e) => { tplSetPick(sel, kind, ref, e.target.checked); ctx.sync(); } } });
    box.checked = sel[kind].has(tplId(ref));
    ctx.boxes.push({ box, kind, id: tplId(ref) });
    const facts = kind === "cards"
      ? [el("span", { class: "tag" }, CARD_POSITION_LABEL[item.position] || "未指定"), " ", el("span", { class: "small muted" }, tplModelText(item))]
      : kind === "routines"
        ? [el("span", { class: "small muted" }, `${tplScheduleText(item)}　交給：${item.who ? cardName(item.who) || "（這個團隊範本裡沒有）" : "套用時再選"}`)]
        : [];
    const words = kind === "cards" ? (item.instructions || "（沒有固定指示）") : item.text;
    return el("li", { class: "tpl-item", "data-tpl-item": kind, "data-tpl-key": item.key },
      el("label", { class: "tpl-pick" }, box, " ", el("strong", null, item.name), " ", facts),
      el("details", { class: "tpl-more" }, el("summary", { class: "small" }, "看全文"), el("p", { class: "small tpl-text", "data-tpl-text": kind }, words)));
  };
  const all = (on) => {
    TPL_KINDS.forEach(([kind]) => template[kind].forEach((item) => tplSetPick(sel, kind, { template: template.id, key: item.key }, on)));
    ctx.sync();
  };
  return el("section", { class: "panel pad tpl-block", "data-templates": "block", "data-template-id": template.id },
    el("h2", null, template.name, " ", template.builtin ? el("span", { class: "tag" }, "VBear 內建") : el("span", { class: "tag mine" }, "你存的")),
    template.about ? el("p", { class: "small muted", "data-templates": "about" }, template.about) : null,
    el("div", { class: "row" },
      el("button", { class: "btn small", type: "button", "data-tpl-action": "all", on: { click: () => all(true) } }, "全選"), " ",
      el("button", { class: "btn small", type: "button", "data-tpl-action": "none", on: { click: () => all(false) } }, "全不選"), " ",
      templatesBlockActions(template, ctx)),
    TPL_KINDS.map(([kind, word]) => (template[kind].length
      ? el("div", { class: "tpl-group", "data-templates": kind }, el("h3", null, word), el("ul", { class: "tpl-list" }, template[kind].map((item) => line(kind, item))))
      : null)));
}

// ---- the person's own team templates (P45-3): 存成團隊範本, 你現在的, 改名, 刪除 ----
// Saving posts to /api/templates/mine with what is ticked in the blocks and what is ticked in 「你現在的」; the server keeps a copy.
const TPL_SAVE_LINES = [
  "存的是現在這一刻的複本：之後你改了原本的員工、常用做法或定時工作，這個團隊範本不會跟著變。",
  "員工只存名字、職位、你寫在卡上的固定指示和 Claude 的模型。不存 AI 工具、技能卡、記憶、共用資料夾和聊天紀錄；「完全交給他（有風險）」的員工存下來也不帶開始工作模式，套用時一律是「每件事先問我」。",
  "定時工作存名稱、內容、星期和時間，還有交給誰（那位員工也一起存才有，沒有的話套用時再選）；存下來沒有開關，套用時一律是關著的。常用做法存名稱和內容。",
  "存之前每段字都會用和記憶、常用做法同一組規則檢查：有金鑰、密碼這類字不能存，像是叫員工不問你就做事的字要你多確認一次。",
  "團隊範本只存在這台電腦，不會上傳，也不能匯出。",
];
const TPL_NOW_LINE = "這一區只給「存成團隊範本」用：這些已經在你這裡了，套用時不會再建一次。";
const TPL_NOW_KEY = { cards: "profile_id", skills: "skill_id", routines: "routine_id" };

// What the person ticked in 「你現在的」, as ids; and the listeners that redraw the buttons whenever the page's boxes change.
function tplNowState(ctx) {
  if (!ctx.now) {
    ctx.now = { cards: new Set(), skills: new Set(), routines: new Set(), listeners: [] };
    const base = ctx.sync;
    ctx.sync = () => { base(); ctx.now.listeners.forEach((f) => f()); };
  }
  return ctx.now;
}
function tplSaveItems(ctx) {
  const all = (ctx.data.builtin || []).concat(ctx.data.mine || []);
  const now = tplNowState(ctx);
  const out = {};
  TPL_KINDS.forEach(([kind]) => {
    const rows = [];
    ctx.sel[kind].forEach((r) => {
      const template = all.find((x) => x.id === r.from.template);
      const item = template ? (template[kind] || []).find((x) => x.key === r.from.key) : null;
      rows.push({ body: { from: { template: r.from.template, key: r.from.key } }, name: item ? item.name : r.from.key });
    });
    const have = (ctx.data.current && ctx.data.current[kind]) || [];
    now[kind].forEach((id) => {
      const item = have.find((x) => x.id === id);
      rows.push({ body: { [TPL_NOW_KEY[kind]]: id }, name: item ? item.name : id });
    });
    out[kind] = rows;
  });
  return out;
}
function tplSaveCount(ctx) {
  const items = tplSaveItems(ctx);
  return { cards: items.cards.length, skills: items.skills.length, routines: items.routines.length };
}
function tplCanSave(ctx) {
  const c = tplSaveCount(ctx);
  return ctx.data.mine_readable !== false && c.cards + c.skills + c.routines > 0;
}
function tplReloadHere(ctx) { if (typeof location !== "undefined" && location.hash === "#/templates") ctx.reload(); }

// The buttons of a block of the person's own: 改名 and 刪除. A built-in block has none.
function templatesBlockActions(template, ctx) {
  if (template.builtin) return null;
  return el("span", { "data-templates": "mine-actions" },
    el("button", { class: "btn small", type: "button", "data-tpl-action": "rename", "data-tpl-target": template.id, on: { click: () => openTemplatesRename(template, ctx) } }, "改名"), " ",
    el("button", { class: "btn small", type: "button", "data-tpl-action": "delete", "data-tpl-target": template.id, on: { click: async () => {
      if (!(await confirmInPage(`刪除「${template.name}」`, "只刪這個團隊範本。用它建過的員工、常用做法、定時工作，和它是從哪裡存來的，都不會動。", "刪除"))) return;
      try { await api.post(`/api/templates/mine/${encodeURIComponent(template.id)}/delete`, {}); toast("已刪除"); tplReloadHere(ctx); }
      catch (e) { toast("刪不了：" + e.message); }
    } } }, "刪除"));
}

// 「你現在的」: the employees, skills and routines the person has now. Only for saving: they can not be ticked for applying.
function templatesMineSection(ctx) {
  const now = tplNowState(ctx);
  const have = ctx.data.current || { cards: [], skills: [], routines: [] };
  const line = (kind, item) => {
    const box = el("input", { type: "checkbox", "data-tpl-now": kind, "data-tpl-id": item.id, "aria-label": `勾選${item.name}（存成團隊範本用）`,
      on: { change: (e) => { if (e.target.checked) now[kind].add(item.id); else now[kind].delete(item.id); ctx.sync(); } } });
    box.checked = now[kind].has(item.id);
    return el("li", { class: "tpl-item", "data-tpl-now-item": kind },
      el("label", { class: "tpl-pick" }, box, " ", el("strong", null, item.name), " ",
        kind === "cards" ? el("span", { class: "tag" }, CARD_POSITION_LABEL[item.position] || "未指定") : null));
  };
  const empty = TPL_KINDS.every(([kind]) => (have[kind] || []).length === 0);
  const count = el("span", { class: "small", "data-templates": "now-count" });
  const button = el("button", { class: "btn small", type: "button", "data-tpl-action": "save-now", on: { click: () => openTemplatesSave(ctx) } }, "存成團隊範本");
  const redraw = () => {
    count.textContent = `你現在的，已勾：${now.cards.size} 位員工、${now.skills.size} 個常用做法、${now.routines.size} 件定時工作`;
    button.disabled = !tplCanSave(ctx);
  };
  now.listeners.push(redraw);
  redraw();
  return el("section", { class: "panel pad tpl-block", "data-templates": "now" },
    el("h2", null, "你現在的"),
    el("p", { class: "small muted", "data-templates": "now-line" }, TPL_NOW_LINE),
    empty ? el("p", { class: "small muted", "data-templates": "now-empty" }, "你現在還沒有員工、常用做法或定時工作。") : null,
    TPL_KINDS.map(([kind, word]) => ((have[kind] || []).length
      ? el("div", { class: "tpl-group", "data-templates": `now-${kind}` }, el("h3", null, word), el("ul", { class: "tpl-list" }, have[kind].map((item) => line(kind, item))))
      : null)),
    el("div", { class: "row" }, count, " ", button));
}

// The dialog shared by the two ways in. Posts what is ticked; on 409 shows what needs a second yes; on success keeps the dialog open
// to say what was saved and what was left out, and reloads the page behind it.
function openTemplatesSave(ctx) {
  const items = tplSaveItems(ctx);
  const limits = ctx.data.limits || {};
  const per = limits.per_template || { cards: 12, skills: 24, routines: 12 };
  const state = { confirm: false, error: "", warn: null, done: null, busy: false };
  const titleId = "tpl-save-title";
  const input = el("input", { type: "text", maxlength: String(limits.max_name || 40), "data-tpl-save": "name", "aria-label": "團隊範本的名稱", placeholder: "取一個名字" });
  const bodyBox = el("div", { "data-templates": "save-body" });
  const foot = el("div", { class: "modal-actions", "data-templates": "save-foot" });
  const modal = el("div", { class: "modal-backdrop", role: "dialog", "aria-modal": "true", "aria-labelledby": titleId, "data-templates": "save" },
    el("div", { class: "modal-box", style: "max-width: 680px; max-height: 88vh; overflow-y: auto;" },
      el("h2", { id: titleId, tabindex: "-1" }, "存成團隊範本"), bodyBox, foot));
  document.body.append(modal);
  const close = withModalA11y(modal, () => modal.remove());
  const request = (confirm) => {
    const body = { name: input.value.trim() };
    TPL_KINDS.forEach(([kind]) => { if (items[kind].length) body[kind] = items[kind].map((r) => r.body); });
    if (confirm) body.confirm_warning = true;
    return body;
  };
  const whereOf = (kind, index) => {                         // the item a refusal or a warning points at, by its place in the request (the server holds no name)
    if (kind === "template") return "團隊範本的名稱";
    const row = items[kind] && items[kind][index];
    return row ? `${(TPL_KINDS.find(([k]) => k === kind) || [])[1]}：${row.name}` : "";
  };
  const save = async () => {
    state.busy = true; state.error = ""; draw();
    try {
      state.done = await api.post("/api/templates/mine", request(state.confirm));
      state.warn = null;
      tplReloadHere(ctx);
    } catch (e) {
      state.done = null;
      if (e.code === "confirm_warning" && e.data) {
        state.warn = { text: (e.data.warn_text || [e.message]).join(" "), where: (e.data.items || []).map((w) => whereOf(w.kind, w.index)).filter(Boolean).join("、") };
        state.confirm = false; state.error = "";
      } else { state.warn = null; state.error = e.message; state.where = e.data && e.data.kind !== undefined ? whereOf(e.data.kind, e.data.index) : ""; }
    }
    state.busy = false; draw();
  };
  const list = (kind, word) => (items[kind].length
    ? el("div", { "data-templates": `save-${kind}` }, el("h3", null, word),
      el("ul", { class: "tpl-list" }, items[kind].map((r) => el("li", { "data-tpl-save-item": kind }, r.name)))) : null);
  const draw = () => {
    if (state.done) {
      const t = state.done.template;
      setKids(bodyBox,
        notice("info", `已存成團隊範本「${t.name}」：${t.cards.length} 位員工、${t.skills.length} 個常用做法、${t.routines.length} 件定時工作。`),
        (state.done.notes || []).map((n) => el("p", { class: "small", "data-tpl-save-note": n.code }, n.text)),
        el("p", { class: "small muted" }, "要用的時候，在上面「你存的團隊範本」勾選，按「預覽並套用」。"));
      setKids(foot, el("button", { class: "btn primary", type: "button", "data-tpl-action": "save-close", on: { click: () => close() } }, "關閉"));
      return;
    }
    const kids = [
      el("label", { class: "small" }, "名稱（1 到 40 個字）　", input),
      el("p", { class: "small", "data-templates": "save-summary" },
        `這次會存：${items.cards.length} 位員工、${items.skills.length} 個常用做法、${items.routines.length} 件定時工作。` +
        `最多存 ${limits.max_mine || 20} 個團隊範本，一個最多 ${per.cards} 位員工、${per.skills} 個常用做法、${per.routines} 件定時工作。`),
      list("cards", "員工"), list("skills", "常用做法"), list("routines", "定時工作")];
    if (state.error) kids.push(notice("bad", state.error + (state.where ? `（${state.where}）` : "")));
    if (state.warn) {
      const box = el("input", { type: "checkbox", "data-tpl-save": "confirm", on: { change: (e) => { state.confirm = e.target.checked; draw(); } } });
      box.checked = state.confirm === true;
      kids.push(el("div", { class: "tpl-warn", "data-templates": "save-warn" }, notice("warn", state.warn.text), state.warn.where ? el("p", { class: "small" }, state.warn.where) : null,
        el("label", null, box, " 我確定")));
    }
    kids.push(el("ul", { class: "small tpl-fixed", "data-templates": "save-fixed" }, TPL_SAVE_LINES.map((l) => el("li", null, l))));
    setKids(bodyBox, kids);
    const go = el("button", { class: "btn primary", type: "button", "data-tpl-action": "save-go", on: { click: save } }, "存成團隊範本");
    go.disabled = state.busy || (state.warn !== null && state.confirm !== true);
    setKids(foot, el("button", { class: "btn", type: "button", "data-tpl-action": "cancel", on: { click: () => close() } }, "取消"), go);
  };
  draw();
  input.focus();
  return { close, state };
}

// 改名: the name is the only thing of a saved team template that can change (to change what is in it, save a new one).
function openTemplatesRename(template, ctx) {
  const state = { confirm: false, error: "", warn: null, busy: false };
  const titleId = "tpl-rename-title";
  const input = el("input", { type: "text", maxlength: "40", value: template.name, "data-tpl-rename": "name", "aria-label": "新的名稱" });
  input.value = template.name;
  const bodyBox = el("div", { "data-templates": "rename-body" });
  const foot = el("div", { class: "modal-actions" });
  const modal = el("div", { class: "modal-backdrop", role: "dialog", "aria-modal": "true", "aria-labelledby": titleId, "data-templates": "rename" },
    el("div", { class: "modal-box" }, el("h2", { id: titleId, tabindex: "-1" }, "改團隊範本的名稱"), bodyBox, foot));
  document.body.append(modal);
  const close = withModalA11y(modal, () => modal.remove());
  const rename = async () => {
    state.busy = true; state.error = ""; draw();
    try {
      await api.post(`/api/templates/mine/${encodeURIComponent(template.id)}`, state.confirm ? { name: input.value.trim(), confirm_warning: true } : { name: input.value.trim() });
      close(); tplReloadHere(ctx); return;
    } catch (e) {
      if (e.code === "confirm_warning" && e.data) { state.warn = (e.data.warn_text || [e.message]).join(" "); state.confirm = false; }
      else { state.warn = null; state.error = e.message; }
    }
    state.busy = false; draw();
  };
  const draw = () => {
    const kids = [el("label", { class: "small" }, "新的名稱　", input), el("p", { class: "small muted" }, "只改名稱，裡面的員工、常用做法和定時工作不變。")];
    if (state.error) kids.push(notice("bad", state.error));
    if (state.warn) {
      const box = el("input", { type: "checkbox", "data-tpl-rename": "confirm", on: { change: (e) => { state.confirm = e.target.checked; draw(); } } });
      box.checked = state.confirm === true;
      kids.push(el("div", { class: "tpl-warn" }, notice("warn", state.warn), el("label", null, box, " 我確定")));
    }
    setKids(bodyBox, kids);
    const go = el("button", { class: "btn primary", type: "button", "data-tpl-action": "rename-go", on: { click: rename } }, "改名");
    go.disabled = state.busy || (state.warn !== null && state.confirm !== true);
    setKids(foot, el("button", { class: "btn", type: "button", "data-tpl-action": "cancel", on: { click: () => close() } }, "取消"), go);
  };
  draw();
  input.focus();
  return { close, state };
}

// 套用紀錄 (P45-2): the last 50 applies, each with the button 復原這次套用 while something of it is still there.
function tplTemplateName(ctx, id) {
  const all = (ctx.data.builtin || []).concat(ctx.data.mine || []);
  const found = all.find((t) => t.id === id);
  return found ? found.name : "（團隊範本已刪除）";
}
function tplCountLine(c) { return `${c.cards} 位員工、${c.skills} 個常用做法、${c.routines} 件定時工作`; }
function templatesAppliesSection(ctx) {
  const applies = Array.isArray(ctx.data.applies) ? ctx.data.applies : [];
  const row = (a) => {
    const left = a.left.cards + a.left.skills + a.left.routines;
    const done = a.counts.cards + a.counts.skills + a.counts.routines;
    const items = a.items.filter((i) => i.state === "made" || i.state === "deleted").map((i) =>
      el("li", { "data-tpl-apply-item": i.kind, "data-tpl-apply-state": i.state },
        `${TPL_ONE[i.kind]}：${i.state === "deleted" ? "（已刪掉）" : i.name || "（已經不在了）"}　`,
        el("span", { class: "small muted" }, `來自：${tplTemplateName(ctx, i.from.template)}`)));
    const undo = el("button", { class: "btn small", type: "button", "data-tpl-action": "undo", "data-tpl-apply": a.id,
      on: { click: () => openTemplatesUndo(ctx, a) } }, "復原這次套用");
    return el("li", { class: "tpl-apply", "data-tpl-apply": a.id, "data-tpl-apply-status": a.state },
      el("div", { class: "row" },
        el("strong", null, fmtTime(a.at)), "　", el("span", { class: "tag" }, TPL_TOOL_LABEL[a.tool] || a.tool), "　",
        el("span", { "data-tpl-apply-count": "yes" }, `建了 ${tplCountLine(a.counts)}`), "　",
        el("span", { class: "small" }, TPL_STATE_TEXT[a.state] || a.state),
        done > 0 && left === 0 ? el("span", { class: "small muted", "data-tpl-apply-undone": "yes" }, "　已復原這次套用") : null, " ",
        a.state !== "applying" && left > 0 ? undo : null),
      a.state === "interrupted" ? el("p", { class: "small muted", "data-tpl-apply-note": "interrupted" }, TPL_INTERRUPTED) : null,
      items.length ? el("details", { class: "tpl-more" }, el("summary", { class: "small" }, "看這次建了什麼"), el("ul", { class: "tpl-list" }, items)) : null);
  };
  return el("section", { class: "panel pad tpl-applies", "data-templates": "applies" },
    el("h2", null, "套用紀錄"),
    el("p", { class: "small muted", "data-templates": "applies-limit" }, TPL_APPLIES_LIMIT),
    applies.length ? el("ul", { class: "tpl-list", "data-templates": "applies-list" }, applies.map(row))
      : el("p", { class: "small muted", "data-templates": "applies-none" }, "還沒有套用過。"));
}

// 復原這次套用: first the list (what will be deleted, what stays and why, what is gone), then 刪掉這些. Names and reasons are shown as text.
function openTemplatesUndo(ctx, apply) {
  const state = { preview: null, error: "", busy: false, result: null };
  const titleId = "tpl-undo-title";
  const bodyBox = el("div", { "data-templates": "undo-body" });
  const foot = el("div", { class: "modal-actions", "data-templates": "undo-foot" });
  const modal = el("div", { class: "modal-backdrop", role: "dialog", "aria-modal": "true", "aria-labelledby": titleId, "data-templates": "undo" },
    el("div", { class: "modal-box", style: "max-width: 680px; max-height: 88vh; overflow-y: auto;" },
      el("h2", { id: titleId, tabindex: "-1" }, "復原這次套用"), bodyBox, foot));
  document.body.append(modal);
  const close = withModalA11y(modal, () => modal.remove());
  const named = (x) => `${TPL_ONE[x.kind]}：${x.name || "（沒有名字）"}`;
  const list = (key, rows, text) => (rows.length
    ? el("div", null, el("ul", { class: "tpl-list", "data-templates": key }, rows.map((x) =>
      el("li", { "data-tpl-undo": key, "data-tpl-undo-kind": x.kind }, text(x)))))
    : null);
  const draw = () => {
    const p = state.preview;
    const kids = [];
    if (state.error) kids.push(notice("bad", state.error));
    if (state.result) {
      const r = state.result;
      kids.push(el("p", { "data-templates": "undo-summary" }, `已刪掉 ${r.deleted.length} 項；留著 ${r.kept.length} 項。`),
        r.deleted.length ? el("div", null, el("h3", null, "已刪掉"), list("undo-deleted", r.deleted, named)) : null,
        r.kept.length ? el("div", null, el("h3", null, "留著"), list("undo-kept", r.kept, (x) => `${named(x)}　${x.text}`)) : null);
      setKids(bodyBox, kids);
      setKids(foot, el("button", { class: "btn primary", type: "button", "data-tpl-action": "undo-done", on: { click: () => { close(); ctx.reload(); } } }, "完成"));
      return;
    }
    if (p) {
      kids.push(
        p.delete.length ? el("div", null, el("h3", null, "會刪掉"), list("undo-delete", p.delete, named)) : el("p", { "data-templates": "undo-nothing" }, "沒有可以刪的。"),
        p.keep.length ? el("div", null, el("h3", null, "會留著"), list("undo-keep", p.keep, (x) => `${named(x)}　${x.text}`)) : null,
        p.gone.length ? el("div", null, el("h3", null, "已經不在了"), list("undo-gone", p.gone, (x) => `${named(x)}　你自己刪掉了`)) : null,
        p.notes.length ? el("ul", { class: "small tpl-fixed", "data-templates": "undo-notes" }, p.notes.map((n) => el("li", { "data-tpl-undo-note": n.code }, n.text))) : null);
    } else if (!state.error) kids.push(el("p", { class: "small muted" }, "整理中…"));
    setKids(bodyBox, kids);
    setKids(foot,
      el("button", { class: "btn", type: "button", "data-tpl-action": "undo-cancel", on: { click: () => close() } }, "取消"),
      el("button", { class: "btn primary", type: "button", "data-tpl-action": "undo-confirm", disabled: !p || p.delete.length === 0 || state.busy,
        on: { click: () => press() } }, "刪掉這些"));
  };
  const press = async () => {
    if (state.busy || !state.preview) return;
    state.busy = true; state.error = "";
    draw();
    try { state.result = await api.post(`/api/templates/applies/${encodeURIComponent(apply.id)}/undo`, { delete: state.preview.delete.map((d) => d.id) }); }
    catch (e) { state.error = e.message; }
    state.busy = false;
    draw();
  };
  draw();
  api.post(`/api/templates/applies/${encodeURIComponent(apply.id)}/undo-preview`, {})
    .then((res) => { state.preview = res; draw(); })
    .catch((e) => { state.error = e.message; draw(); });
  return { close, state };
}

// The button 存成團隊範本 beside 預覽並套用: for what is ticked in the blocks and in 「你現在的」.
function templatesSaveAction(ctx) {
  const now = tplNowState(ctx);
  const button = el("button", { class: "btn", type: "button", "data-tpl-action": "save", on: { click: () => openTemplatesSave(ctx) } }, "存成團隊範本");
  const redraw = () => { button.disabled = !tplCanSave(ctx); };
  now.listeners.push(redraw);
  redraw();
  return button;
}

// The 套用 button of the preview (P45-2). `box`: { ctx, state, preview, body(), close, redraw }; it can be pressed only when `preview.ok` says nothing stops the
// apply. One press posts the same body as the preview; the answer (made, or stopped in the middle) is shown in the same dialog.
function templatesApplyAction(box) {
  const { state, preview } = box;
  const can = Boolean(preview) && preview.ok === true && !state.busy && !state.applying;
  return el("span", { "data-templates": "apply-slot" },
    el("button", { class: "btn primary", type: "button", disabled: !can, "data-tpl-action": "apply", on: { click: () => templatesApplyPress(box) } },
      state.applying ? "套用中…" : "套用"));
}
async function templatesApplyPress(box) {
  const { state } = box;
  if (state.applying || state.done || !state.preview || state.preview.ok !== true) return;
  state.applying = true; state.error = "";
  box.redraw();
  try {
    const res = await api.post("/api/templates/apply", box.body());
    state.done = { partial: false, apply: res.apply, text: `已建好：${tplCountLine(res.apply.counts)}。${TPL_APPLIED_LINE}` };
  } catch (e) {
    if (e.code === "template_partial" && e.data && e.data.apply) state.done = { partial: true, apply: e.data.apply, text: e.message };
    else state.error = e.message;
  }
  state.applying = false;
  box.redraw();
}

function openTemplatesPreview(ctx) {
  const data = ctx.data;
  const state = { tool: data.tools && (data.tools.default === "codex" || (data.tools.default === "agy" && data.tools.agy)) ? data.tools.default : "claude", confirm: false, preview: null, error: "", busy: false, applying: false, done: null };
  const titleId = "tpl-preview-title";
  const bodyBox = el("div", { "data-templates": "preview-body" });
  const foot = el("div", { class: "modal-actions", "data-templates": "preview-foot" });
  const modal = el("div", { class: "modal-backdrop", role: "dialog", "aria-modal": "true", "aria-labelledby": titleId, "data-templates": "preview" },
    el("div", { class: "modal-box", style: "max-width: 720px; max-height: 88vh; overflow-y: auto;" },
      el("h2", { id: titleId, tabindex: "-1" }, "預覽這次套用"), bodyBox, foot));
  document.body.append(modal);
  const close = withModalA11y(modal, () => modal.remove());
  let asked = 0;
  const ask = async () => {
    if (state.applying || state.done) return;
    const mine = ++asked;
    state.busy = true;
    draw();
    try {
      const res = await api.post("/api/templates/preview", tplRequestBody(ctx.sel, state));
      if (mine !== asked) return;
      state.preview = res.preview; state.error = "";
    } catch (e) {
      if (mine !== asked) return;
      state.preview = null; state.error = e.message;
    }
    state.busy = false;
    draw();
  };
  const toolRow = () => {
    const tools = data.tools || {};
    const radio = (tool) => {
      const input = el("input", { type: "radio", name: "tpl-tool", value: tool, "data-tpl-tool": tool, disabled: state.applying,
        on: { change: () => { state.tool = tool; ask(); } } });
      input.checked = state.tool === tool;
      return el("label", { class: "tpl-radio" }, input, " ", TPL_TOOL_LABEL[tool]);
    };
    const chosen = tools[state.tool];
    return el("div", { class: "tpl-tool", "data-templates": "tool" },
      el("span", { "data-templates": "tool-label" }, "這次的員工都用："), " ", radio("claude"), "　", radio("codex"), tools.agy ? ["　", radio("agy")] : null,
      chosen && chosen.ready === false
        ? el("p", { class: "small", "data-templates": "tool-not-ready" }, TPL_PREVIEW_LINES.notReady, chosen.why ? ` ${chosen.why}` : "") : null);
  };
  const cardLine = (c) => {
    const input = el("input", { type: "text", maxlength: "40", value: c.name, "data-tpl-name": tplId(c.from), "aria-label": `員工的名字：${c.default_name}`,
      on: { change: (e) => { const entry = ctx.sel.cards.get(tplId(c.from)); if (entry) { entry.name = e.target.value; ask(); } } } });
    input.value = c.name;
    return el("li", { "data-tpl-preview": "card" }, input, " ",
      el("span", { class: "tag" }, CARD_POSITION_LABEL[c.position] || "未指定"), " ",
      el("span", { class: "small muted" }, `${TPL_TOOL_LABEL[state.preview.tool]}${c.model_id ? `　${c.model_id}` : "　工具自己的預設模型"}`),
      c.instructions_head ? el("p", { class: "small tpl-text", "data-tpl-preview": "head" }, c.instructions_head + (c.instructions_cut ? "…" : "")) : null,
      c.same_in_batch ? el("p", { class: "small muted", "data-tpl-preview": "same-batch" }, `這次有不只一位叫「${c.name}」，只是提醒。`) : null,
      c.same_existing ? el("p", { class: "small muted", "data-tpl-preview": "same-existing" }, `你已經有一位叫「${c.name}」，只是提醒。`) : null);
  };
  const assigneeValue = (a) => (a.kind === "card" ? `card:${tplId(a.card)}` : a.kind === "existing" ? `existing:${a.profile_id}` : "");
  const routineLine = (r) => {
    const choices = state.preview.choices;
    const pick = el("select", { "data-tpl-to": tplId(r.from), "aria-label": `定時工作「${r.name}」交給誰`,
      on: { change: (e) => {
        const entry = ctx.sel.routines.get(tplId(r.from));
        const v = String(e.target.value || "");
        if (!entry) return;
        if (v.startsWith("card:")) { const [template, key] = v.slice(5).split("/"); entry.to = { card: { template, key } }; }
        else if (v.startsWith("existing:")) entry.to = { profile_id: v.slice(9) };
        else delete entry.to;
        ask();
      } } },
      el("option", { value: "" }, r.assignee.kind ? "（照團隊範本的安排）" : "（還沒選）"),
      choices.cards.map((c) => el("option", { value: `card:${tplId(c)}` }, `這次勾的員工：${c.name}`)),
      choices.existing.map((c) => el("option", { value: `existing:${c.profile_id}` }, `你現在的員工：${c.name}`)));
    pick.value = assigneeValue(r.assignee);
    return el("li", { "data-tpl-preview": "routine" }, el("strong", null, r.name), "　", el("span", { class: "small muted" }, tplScheduleText(r)), "　交給 ", pick,
      r.assignee.name ? el("span", { class: "small", "data-tpl-preview": "to-name" }, ` ${r.assignee.name}`) : null);
  };
  const afterLine = (after) =>
    `套用後：員工 ${after.cards.after}/${after.cards.max}、常用做法 ${after.skills.after}/${after.skills.max}、定時工作 ${after.routines.after}/${after.routines.max}`;
  const itemName = (kind, from) => {
    const template = (data.builtin || []).concat(data.mine || []).find((t) => t.id === from.template);
    const item = template ? (template[kind === "card" ? "cards" : kind === "skill" ? "skills" : "routines"] || []).find((x) => x.key === from.key) : null;
    return item ? item.name : from.key;
  };
  const warnBox = (p) => {
    const box = el("input", { type: "checkbox", "data-tpl-confirm": "yes", on: { change: (e) => { state.confirm = e.target.checked; ask(); } } });
    box.checked = state.confirm === true;
    return el("div", { class: "tpl-warn", "data-templates": "warn" },
      tplServerNotice("warn", Object.values(p.warn_text || {}).join(" "), p),
      el("ul", { class: "small" }, p.warn_items.map((w) => el("li", { "data-tpl-warn": w.kind },
        `${w.kind === "card" ? "員工" : w.kind === "skill" ? "常用做法" : "定時工作"}：${itemName(w.kind, w.from)}`))),
      el("label", null, box, " 我確定"));
  };
  const doneItem = (item) => {
    const word = item.state === "failed" ? "停在這裡" : item.state === "made" ? "已建好" : "";
    return el("li", { "data-tpl-done": `${item.kind}:${item.state}` }, `${TPL_ONE[item.kind]}：${item.name || itemName(item.kind, item.from)}`, word ? `　${word}` : "");
  };
  const draw = () => {
    const p = state.preview;
    if (state.done) {
      setKids(bodyBox, notice(state.done.partial ? "bad" : "info", state.done.text),
        el("ul", { class: "tpl-list", "data-templates": "done-items" }, state.done.apply.items.map(doneItem)));
      setKids(foot, el("button", { class: "btn primary", type: "button", "data-tpl-action": "done", on: { click: () => { close(); ctx.reload(); } } }, "完成"));
      return;
    }
    const kids = [toolRow()];
    if (state.error) kids.push(tplServerNotice("bad", state.error, p));
    if (p) {
      kids.push(
        el("p", { "data-templates": "summary" }, `這次會建：${p.cards.length} 位員工、${p.skills.length} 個常用做法、${p.routines.length} 件定時工作。`),
        p.cards.length ? el("div", null, el("h3", null, "員工"), el("ul", { class: "tpl-list", "data-templates": "preview-cards" }, p.cards.map(cardLine))) : null,
        p.skills.length ? el("div", null, el("h3", null, "常用做法"), el("ul", { class: "tpl-list", "data-templates": "preview-skills" },
          p.skills.map((s) => el("li", { "data-tpl-preview": "skill" }, s.name)))) : null,
        p.routines.length ? el("div", null, el("h3", null, "定時工作"), el("ul", { class: "tpl-list", "data-templates": "preview-routines" }, p.routines.map(routineLine))) : null,
        el("p", { class: "small", "data-templates": "after" }, afterLine(p.after)),
        p.problems.filter((x) => x.code !== "confirm_warning").map((x) => tplServerNotice("bad", x, p)),
        p.warn_items.length ? warnBox(p) : null,
        p.notes.map((n) => el("p", { class: "small muted", "data-tpl-preview": "note" }, tplWords(n.text))));
    } else if (!state.error) kids.push(el("p", { class: "small muted" }, "整理中…"));
    const lines = [TPL_PREVIEW_LINES.safe, TPL_PREVIEW_LINES.memory, TPL_PREVIEW_LINES.off, TPL_PREVIEW_LINES.free];
    if (state.tool === "codex") lines.push(TPL_PREVIEW_LINES.codex);
    if (state.tool === "agy") {
      lines.push(TPL_PREVIEW_LINES.agy);
      if (data.tools && data.tools.agy && data.tools.agy.chat_verified === false) lines.push(TPL_PREVIEW_LINES.agyUnverified);
    }
    kids.push(el("ul", { class: "small tpl-fixed", "data-templates": "fixed" }, lines.map((l) => el("li", null, l))));
    setKids(bodyBox, kids);
    setKids(foot,
      el("button", { class: "btn", type: "button", "data-tpl-action": "cancel", disabled: state.applying, on: { click: () => close() } }, "取消"),
      templatesApplyAction({ ctx, state, preview: state.preview, body: () => tplRequestBody(ctx.sel, state), close, redraw: draw }));
  };
  draw();
  ask();
  return { close, state };
}

// The sentences the server writes for a team template's preview still say 角色卡, 技能, 例行工作 and 安全模式 (its Python words are not changed).
// The page says them in its own words (the same sentence, other nouns) and keeps the server's sentence whole behind 「技術細節」. A counting
// sentence (template_full) is built from the counts of the preview, since 張 and 個 do not fit 員工.
const TPL_SWAPS = [[/角色卡/g, "員工"], [/例行工作/g, "定時工作"], [/技能/g, "常用做法"], [/安全模式/g, "每件事先問我"]];
const TPL_KIND_WORDS = { cards: ["員工", "位"], skills: ["常用做法", "個"], routines: ["定時工作", "件"] };
function tplWords(raw) { return TPL_SWAPS.reduce((t, [re, to]) => t.replace(re, to), String(raw)); }
function tplServerNotice(kind, x, preview) {
  const raw = typeof x === "string" ? x : x && typeof x.text === "string" ? x.text : "";
  if (!raw) return null;
  let text = tplWords(raw);
  if (x && x.code === "template_full" && cardHas(TPL_KIND_WORDS, x.kind) && preview && preview.after && preview.after[x.kind] && Number.isFinite(x.over)) {
    const a = preview.after[x.kind];
    const [word, unit] = TPL_KIND_WORDS[x.kind];
    text = `${word}會超過 ${a.max} ${unit}：你現在有 ${a.now} ${unit}，這次要加 ${a.add} ${unit}，請少勾 ${x.over} ${unit}。`;
  }
  return text === raw ? noticeBox(kind, raw) : noticeBox(kind, [text, plainTechFold(raw)]);
}

async function viewTemplates() {
  const token = seq;
  let data;
  try { data = await api.get("/api/templates"); }
  catch (e) { setKids(claim(token), el("h1", null, "團隊範本"), notice("bad", "讀不到團隊範本：" + e.message)); return; }
  // the line about the CEO is for a person who has none: shown only when the employees were read and none of them is a CEO (not read: not said)
  const staff = await api.get("/api/agent-profiles").catch(() => null);
  if (token !== seq) return;
  const noCeo = !!staff && Array.isArray(staff.profiles) && !staff.profiles.some((p) => p && typeof p === "object" && cardPosition({ position: p.position }) === MEETING_CHAIR_POSITION);
  const main = claim(token);
  const ctx = { data, sel: tplSelection(), boxes: [], reload: () => viewTemplates() };
  const count = el("span", { "data-templates": "count" });
  const preview = el("button", { class: "btn primary", type: "button", "data-tpl-action": "preview", on: { click: () => openTemplatesPreview(ctx) } }, "預覽並套用");
  ctx.sync = () => {
    ctx.boxes.forEach((b) => { b.box.checked = ctx.sel[b.kind].has(b.id); });
    count.textContent = tplCountText(ctx.sel);
    const c = tplCounts(ctx.sel);
    preview.disabled = c.cards + c.skills + c.routines === 0;
  };
  const problems = Array.isArray(data.problems) ? data.problems : [];
  const blocks = (data.builtin || []).map((t) => templatesBlock(t, ctx));
  const own = Array.isArray(data.mine) ? data.mine : [];
  setKids(main, el("h1", null, "團隊範本"),
    el("ul", { class: "lede tpl-lines", "data-templates": "lines" }, TPL_LINES.map((l) => el("li", null, l))),
    noCeo ? el("p", { class: "small muted", "data-templates": "ceo-line" }, TPL_CEO_LINE) : null,
    problems.map((p) => notice("warn", `${p}　這個檔案讀不出來之前，不能套用。`)),
    data.mine_readable === false ? notice("warn", data.problem || "你存的團隊範本的檔案讀不出來；VBear 內建的照常可以用。") : null,
    blocks,
    own.length ? el("h2", { "data-templates": "mine-title" }, "你存的團隊範本") : null,
    own.map((t) => templatesBlock(t, ctx)),
    templatesMineSection(ctx),
    templatesAppliesSection(ctx),
    el("div", { class: "panel pad tpl-foot", "data-templates": "foot" }, count, " ", preview, " ",
      el("span", { "data-templates": "foot-actions" }, templatesSaveAction(ctx))));
  ctx.sync();
}
